#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_FILE_SIZE (10 * 1024 * 1024 * 1024)
#define MAX_CONCURRENT_REQUESTS 5
#define RATE_LIMIT 100

typedef struct {
    int fd;
    pthread_t thread;
} file_info;

int max_value = INT_MIN;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_file(void* arg) {
    file_info* info = (file_info*)arg;
    int fd = info->fd;
    close(info->fd); // Close the file descriptor
    free(info);
    return NULL;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    int file_count = 0;
    char buffer[1024];

    while (1) {
        // Accept incoming requests
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(0, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd == -1) {
            perror("Error accepting connection");
            continue;
        }

        // Read the file size and name
        read(client_fd, buffer, 1024);
        char* filename = strtok(buffer, " ");
        int filesize = atoi(strtok(NULL, " "));

        // Check if the file is too large
        if (filesize > MAX_FILE_SIZE) {
            send(client_fd, "File too large", strlen("File too large"), 0);
            close(client_fd);
            continue;
        }

        // Read the file in chunks
        int chunk_size = 1024 * 1024; // 1MB chunks
        char* data = (char*)malloc(chunk_size);
        int bytes_read = read(client_fd, data, chunk_size);

        while (bytes_read > 0) {
            // Process the data
            for (int i = 0; i < bytes_read / sizeof(int); i++) {
                int value = *(int*)&data[i * sizeof(int)];
                if (value > max_value)
                    max_value = value;
            }

            // Close and reopen the file to prevent buffer overflow
            close(client_fd);
            client_fd = open(filename, O_RDONLY);

            // Read the next chunk
            bytes_read = read(client_fd, data, chunk_size);
        }

        // Close the file and release resources
        close(client_fd);
        free(data);

        // Handle errors
        if (bytes_read == -1) {
            perror("Error reading file");
            continue;
        } else if (bytes_read == 0) {
            break; // End of file, exit loop
        }

        // Release the thread
        pthread_mutex_lock(&mutex);
        file_info* info = (file_info*)malloc(sizeof(file_info));
        info->fd = client_fd;
        pthread_create(&threads[file_count], NULL, process_file, info);
        file_count++;
        pthread_mutex_unlock(&mutex);

        if (file_count >= MAX_CONCURRENT_REQUESTS) {
            // Rate limit and wait for threads to complete
            while (1) {
                int i = 0;
                while (i < file_count) {
                    pthread_join(threads[i], NULL);
                    i++;
                }

                if (getpid() % RATE_LIMIT == 0)
                    break; // Wait for rate limiting

                usleep(RATE_LIMIT * 1000); // Sleep for 1 second
            }
        }
    }

    return 0;
}
