import hashlib
import os
import time
from typing import Dict, Any

class FileHashingService:
    def __init__(self):
        self.metadata_repository: Dict[str, Any] = {}
        self.cache: Dict[str, Any] = {}

    def hash_file(self, file_path: str) -> (str, str):
        md5_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
        sha256_hash = hashlib.sha256(open(file_path, 'rb').read()).hexdigest()

        return md5_hash, sha256_hash

    def fetch_metadata(self, file_path: str) -> Dict[str, Any]:
        if file_path in self.cache:
            return self.cache[file_path]

        try:
            metadata = self.metadata_repository.get(file_path)
            if not metadata:
                raise KeyError(f"Metadata for {file_path} not found")

            return metadata
        except Exception as e:
            # fallback strategy: calculate hash without metadata
            print(f"Failed to fetch metadata: {e}")
            return {}

    def process_file(self, file_path: str) -> (str, str):
        try:
            md5_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
            sha256_hash = hashlib.sha256(open(file_path, 'rb').read()).hexdigest()

            # fetch metadata
            metadata = self.fetch_metadata(file_path)

            return md5_hash, sha256_hash, metadata

        except Exception as e:
            print(f"Error processing file: {e}")
            return None, None, {}

    def start(self):
        while True:
            try:
                file_path = input("Enter a file path (or 'stop' to exit): ")
                if file_path.lower() == 'stop':
                    break

                md5_hash, sha256_hash, metadata = self.process_file(file_path)

                print(f"MD5: {md5_hash}")
                print(f"SHA-256: {sha256_hash}")
                if metadata:
                    for key, value in metadata.items():
                        print(f"{key}: {value}")

            except KeyboardInterrupt:
                break

    def configure(self):
        # set throttling mechanism
        self.metadata_repository = {'path/to/file1': {'mimetype': 'text/plain', 'last_modified': 1643723400}, 
                                    'path/to/file2': {'mimetype': 'image/jpeg', 'last_modified': 1643754600}}

    def run(self):
        try:
            while True:
                self.start()
        except KeyboardInterrupt:
            print("Exiting...")
