import jinja2
from yaml import safe_dump
from json import loads
from requests.exceptions import RequestException
from logging import getLogger

logger = getLogger()

def generate_compose_file(template_yaml: str, env_vars_dict: dict, environment: str):
    try:
        template = jinja2.Template(open(template_yaml).read())
        rendered_template = template.render(env_vars_dict)
        compose_file_contents = loads(rendered_template)

        if not compose_file_contents:
            raise ValueError("Invalid or empty Docker Compose configuration")

        for service in compose_file_contents.get('services', {}):
            expose_ports(service, env_vars_dict)

        optimize_network_config(compose_file_contents)

        with open(f"{environment}.yaml", 'w') as file:
            file.write(safe_dump(compose_file_contents))

    except jinja2.exceptions.TemplateError as e:
        logger.error(f"Failed to render template: {e}")
        raise
    except RequestException as e:
        logger.error(f"Failed to fetch default values from API: {e}")
        raise
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
        raise

def expose_ports(service: dict, env_vars_dict: dict):
    try:
        for port in service.get('ports', []):
            if port.get('container_port') and port.get('host_port'):
                host_port = int(port['host_port'])
                container_port = int(port['container_port'])

                # Validate port specifications
                if not 0 < host_port < 65535 or not 0 < container_port < 65535:
                    raise ValueError(f"Invalid port specification: {port}")

                # Mask sensitive data (if applicable)
                if env_vars_dict.get('SECURE_MODE'):
                    service['ports'].remove(port)

            else:
                raise ValueError("Missing port information")
    except Exception as e:
        logger.error(f"Failed to expose ports for service: {e}")
        raise

def optimize_network_config(compose_file_contents: dict):
    try:
        networks = compose_file_contents.get('networks', {})
        if not networks:
            return

        # Handle network configurations
        for network in networks.values():
            if 'driver' not in network or network['driver'] == 'bridge':
                continue

            # Set up load balancing and latency handling
            if environment == 'production':
                network['driver'] = 'overlay'
            elif environment == 'staging':
                network['driver'] = 'host'

        compose_file_contents['networks'].update(networks)
    except Exception as e:
        logger.error(f"Failed to optimize network configuration: {e}")
        raise

if __name__ == '__main__':
    generate_compose_file('template.yaml', {'VARIABLE1': 'value1'}, 'production')
