    std::vector<CryptographicFunction*> functions = {
        new HardwareAcceleratedCryptographicFunction(),
        new SoftwareBasedCryptographicFunction()
    };

    runtimeDiscovery.discoverFunctions(functions);

    CryptographicFunction* selectedFunction = runtimeDiscovery.selectFunction();
    if (selectedFunction) {
        runtimeDiscovery.operate(selectedFunction);
    }

    return 0;
