```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a structure for the semaphore
typedef struct {
    int value; // Current permit count
    pthread_mutex_t mutex; // Mutex for synchronization
    pthread_cond_t cond_var; // Condition variable for signaling
} Semaphore;

// Function to initialize the semaphore with an initial value
Semaphore* init_semaphore(int value) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->value = value;
    if (pthread_mutex_init(&sem->mutex, NULL)) {
        printf("Mutex initialization failed\n");
        return NULL;
    }
    if (pthread_cond_init(&sem->cond_var, NULL)) {
        printf("Condition variable initialization failed\n");
        return NULL;
    }
    return sem;
}

// Function to release a permit from the semaphore
void release_permit(Semaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    if (--sem->value < 0) {
        printf("Semaphore underflow: Permit not available\n");
    } else {
        pthread_cond_signal(&sem->cond_var);
    }
    pthread_mutex_unlock(&sem->mutex);
}

// Function to request a permit from the semaphore
void* request_permit(Semaphore* sem, int timeout) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        // Wait for a permit or timeout
        if (pthread_cond_timedwait(&sem->cond_var, &sem->mutex, &timeout)) {
            printf("Semaphore timeout: No permits available\n");
            return NULL;
        }
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
    return NULL;
}

// Function to clean up the semaphore and its resources
void cleanup_semaphore(Semaphore* sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond_var);
    free(sem);
}
