#include <forward_list>
#include <string>
#include <logger.h>

void insertOrUpdateItem(std::forward_list<std::string>& list,
                         const std::string& target,
                         const std::string& replacement,
                         bool logErrors) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            list.insert_after(it, replacement);
            return;
        }
        ++it;
    }

    // Target string not found
    if (logErrors) {
        logger.log_error("Target string '%s' not found.", target.c_str());
    } else {
        char buffer[1024];
        snprintf(buffer, 1023, "Target string '%s' not found.");
        logger.log_info(buffer, target);
    }
}
