package com.example.sandeshclient;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.logging.Level;
import java.util.logging.Logger;

import org.apache.commons.configuration.ConfigurationException;
import org.apache.commons.configuration.XMLConfiguration;

public class SandeshClient {

    private static final Logger LOGGER = Logger.getLogger(SandeshClient.class.getName());

    private XMLConfiguration config;

    private ExecutorService executorService;

    public SandeshClient(XMLConfiguration config) {
        this.config = config;
        this.executorService = Executors.newFixedThreadPool(5);
    }

    public void startMonitoring() {
        try {
            // Initialize API client
            ApiClient apiClient = new ApiClient(config.getString("api.url"));

            // Start sending periodic GET requests
            executorService.submit(() -> {
                while (true) {
                    try {
                        apiClient.sendGetRequest();

                        // Adjust request frequency based on current load and system capacity
                        Thread.sleep(Integer.parseInt(config.getString("request.interval")));
                    } catch (InterruptedException e) {
                        LOGGER.log(Level.SEVERE, "Monitoring interrupted", e);
                        return;
                    }
                }
            });

        } catch (ConfigurationException e) {
            LOGGER.log(Level.SEVERE, "Configuration error", e);
        }

    }

    public static void main(String[] args) throws ConfigurationException {
        XMLConfiguration config = new XMLConfiguration("config.xml");
        SandeshClient client = new SandeshClient(config);
        client.startMonitoring();
    }
}

