class MersenneTwisterRNG {
public:
    enum SeedSource { USER_PROVIDED, SYSTEM_TIME, HARDWARE_ENTROPY };

    MersenneTwisterRNG(SeedSource seedSource = USER_PROVIDED)
        : mt_(new std::mt19937_64(std::chrono::high_resolution_clock::now().time_since_epoch().count())),
          seedStatus_(false) {
        if (seedSource == SYSTEM_TIME) {
            *mt_ = std::mt19937_64(std::chrono::high_resolution_clock::now().time_since_epoch().count());
        } else if (seedSource == HARDWARE_ENTROPY) {
            // Implement hardware-based entropy generation
        }
    }

    ~MersenneTwisterRNG() { delete mt_; }

    void seed(uint32_t seedValue, SeedSource source = USER_PROVIDED) {
        *mt_ = std::mt19937_64(seedValue);
        seedStatus_ = true;
    }

    template <typename T>
    T generateRandom(T min, T max) const {
        if (min > max) {
            throw std::invalid_argument("Invalid range");
        }
        return T(min + (max - min) * static_cast<T>(rand() / static_cast<double>(RAND_MAX)));
    }

    template <typename T>
    T generateRandom(T min, T max, uint32_t seedValue) const {
        if (!seedStatus_) {
            throw std::runtime_error("Seed not set");
        }
        *mt_ = std::mt19937_64(seedValue);
        return generateRandom<T>(min, max);
    }

    bool getSeedStatus() const { return seedStatus_; }

private:
    mutable std::unique_ptr<std::mt19937_64> mt_;
    bool seedStatus_;
};

std::ostream& operator<<(std::ostream& os, const MersenneTwisterRNG& rng) {
    os << "Mersenne Twister RNG Seed Status: " << (rng.getSeedStatus() ? "Set" : "Not Set");
    return os;
}

int main() {
    MersenneTwisterRNG rng;

    // Example usage:
    uint32_t seedValue = 12345;
    rng.seed(seedValue, MersenneTwisterRNG::USER_PROVIDED);

    int randomInt = rng.generateRandom<int>(1, 100);
    float randomFloat = rng.generateRandom<float>(0.0f, 10.0f);

    std::cout << "Generated Random Int: " << randomInt << std::endl;
    std::cout << "Generated Random Float: " << randomFloat << std::endl;

    return 0;
}

