public class DatabaseExecutor
{
    private readonly int _maxRetries = 3;
    private readonly TimeSpan _retryInterval = TimeSpan.FromMilliseconds(100);
    private readonly ILogger _logger;
    private readonly IConfigurationManager _configManager;

    public DatabaseExecutor(ILogger logger, IConfigurationManager configManager)
    {
        _logger = logger;
        _configManager = configManager;
    }

    public async Task ExecuteDatabaseOperationAsync(string connectionString, string sqlCommand, SqlParameter[] parameters, Func<IDataReader, Task> callback = null)
    {
        if (string.IsNullOrEmpty(connectionString))
            throw new ArgumentException("Connection string is required");

        using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync();

        try
        {
            using var command = new SqlCommand(sqlCommand, connection, true);
            foreach (var parameter in parameters)
                command.Parameters.Add(parameter);

            using var reader = await command.ExecuteReaderAsync();
            if (callback != null)
                await callback(reader);
        }
        catch (SqlException ex) when (IsTransientFailure(ex))
        {
            _logger.LogWarning("Transient failure occurred. Retrying the operation.");
            await ExecuteDatabaseOperationAsync(connectionString, sqlCommand, parameters, callback, maxRetries: _maxRetries - 1, retryInterval: _retryInterval);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex.Message);
            // Handle other failure modes (e.g., connection timeouts, authentication failures) as needed
        }
    }

    private bool IsTransientFailure(SqlException ex)
    {
        // Implement your custom transient error detection logic here
        return false;
    }
}

