using System;
using System.Xml;
using System.Data.SqlClient;
using System.Threading;

namespace XmlParsingLibrary
{
    public class XmlParser
    {
        private readonly XmlDocument _xmlDoc;
        private readonly SqlConnection _dbConn;
        private readonly CacheManager _cacheManager;
        private readonly int _maxCacheSize;
        private readonly object _lock = new object();

        public XmlParser(SqlConnection dbConn, int maxCacheSize)
        {
            _xmlDoc = new XmlDocument();
            _dbConn = dbConn;
            _cacheManager = new CacheManager(maxCacheSize);
            _maxCacheSize = maxCacheSize;
        }

        public XmlNode RetrieveXmlNode(string xpathQuery, string namespaceUri)
        {
            lock (_lock)
            {
                // Check cache for existing result
                XmlNode cachedNode = _cacheManager.Get(xpathQuery);
                if (cachedNode != null) return cachedNode;

                // Parse XML document
                _xmlDoc.LoadXml(GetLargeXmlDocument());

