                // Cache result
                if (nodeList.Count > 0) _cacheManager.Set(xpathQuery, nodeList[0]);

                return nodeList.Count == 1 ? nodeList[0] : nodeList;
            }
        }

        private void LogOperationMetadata(string query, string namespaceUri, int resultCount)
        {
            using (SqlCommand cmd = new SqlCommand("INSERT INTO XmlQueryLog (Timestamp, Query, Namespace, ResultCount) VALUES (@Timestamp, @Query, @Namespace, @ResultCount)", _dbConn))
            {
                cmd.Parameters.AddWithValue("@Timestamp", DateTime.Now);
                cmd.Parameters.AddWithValue("@Query", query);
                cmd.Parameters.AddWithValue("@Namespace", namespaceUri);
                cmd.Parameters.AddWithValue("@ResultCount", resultCount);

                _dbConn.Open();
                cmd.ExecuteNonQuery();
                _dbConn.Close();
            }
