            return "Your Large XML Document";
        }
    }

    public class CacheManager
    {
        private readonly int _maxCacheSize;
        private readonly Dictionary<string, XmlNode> _cache = new Dictionary<string, XmlNode>();

        public CacheManager(int maxCacheSize)
        {
            _maxCacheSize = maxCacheSize;
        }

        public void Set(string key, XmlNode value)
        {
            lock (_lock)
            {
                if (_cache.ContainsKey(key)) _cache[key] = value;
                else
                {
                    // Evict least recently used item when cache is full
                    if (_cache.Count >= _maxCacheSize) RemoveLeastRecentlyUsed();
                    _cache.Add(key, value);
                }
            }
        }

        public XmlNode Get(string key)
        {
            lock (_lock)
            {
                return _cache.ContainsKey(key) ? _cache[key] : null;
            }
