<?php

namespace UserAccountManager;

class UserController {
    private $db;
    private $logger;

    public function __construct($db, $logger) {
        $this->db = $db;
        $this->logger = $logger;
    }

    public function createUser(array $data): int {
        if (!isset($data['username'], $data['email'], $data['password'])) {
            throw new \Exception('Invalid user data');
        }

        // Validate username and email
        if (!preg_match('/^[a-zA-Z0-9_]+$/', $data['username']) || !filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            throw new \Exception('Invalid username or email');
        }

        // Hash password
        $hashedPassword = password_hash($data['password'], PASSWORD_DEFAULT);

        // Insert user into database
        $query = "INSERT INTO users (username, email, password) VALUES (:username, :email, :password)";
        $stmt = $this->db->prepare($query);
        $stmt->execute([':username' => $data['username'], ':email' => $data['email'], ':password' => $hashedPassword]);

        // Log user creation
        $this->logger->log(LogLevel::INFO, 'User created with username %s and email %s', [$data['username'], $data['email']]);

        return (int)$this->db->lastInsertId();
    }

    public function updateUser(int $id, array $data): bool {
        if (!isset($data['username'], $data['email'])) {
            throw new \Exception('Invalid user data');
        }

        // Validate username and email
        if (!preg_match('/^[a-zA-Z0-9_]+$/', $data['username']) || !filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            throw new \Exception('Invalid username or email');
        }

        // Update user in database
        $query = "UPDATE users SET username = :username, email = :email WHERE id = :id";
        $stmt = $this->db->prepare($query);
        $stmt->execute([':id' => $id, ':username' => $data['username'], ':email' => $data['email']]);

        // Log user update
        $this->logger->log(LogLevel::INFO, 'User updated with ID %s', [$id]);

        return true;
    }

    public function deleteUser(int $id): bool {
        // Delete user from database
        $query = "DELETE FROM users WHERE id = :id";
        $stmt = $this->db->prepare($query);
        $stmt->execute([':id' => $id]);

        // Log user deletion
        $this->logger->log(LogLevel::INFO, 'User deleted with ID %s', [$id]);

        return true;
    }

    public function getUser(int $id): array {
        // Retrieve user from database
        $query = "SELECT * FROM users WHERE id = :id";
        $stmt = $this->db->prepare($query);
        $stmt->execute([':id' => $id]);

        return $stmt->fetch();
    }
}

abstract class LogLevel {
    const DEBUG = 1;
    const INFO = 2;
    const WARNING = 3;
    const ERROR = 4;
}

class Logger {
    private $logLevels;
    private $services;

    public function __construct() {
        $this->logLevels = [];
        $this->services = [];
    }

    public function log(LogLevel::Level $level, string $message, array $args): void {
        // Validate log level
        if (!in_array($level, $this->logLevels)) {
            throw new \Exception('Invalid log level');
        }

        // Format message with variable arguments
        $formattedMessage = vsprintf($message, $args);

        // Send log entry to services
        foreach ($this->services as $service) {
            if (!is_callable($service)) {
                throw new \Exception('Service is not callable');
            }

            call_user_func($service, $level, $formattedMessage);
        }
    }

    public function addLogService(callable $service): void {
        $this->services[] = $service;
    }
}

class Database {
    private $connection;

    public function __construct() {
        // Establish database connection
    }

    public function prepare(string $query): PDOStatement {
        return new PDOStatement($this->connection, $query);
    }

    public function lastInsertId(): int {
        // Return last inserted ID
    }
}
