function runTests(moduleName, testCases, blueslipMock, externalDataSource, timeout) {
  const start = Date.now();
  let passedCount = 0;
  let failedCount = 0;
  let skippedCount = 0;
  let errorStacks = [];

  try {
    // Load module
    const module = require(moduleName);
  } catch (error) {
    console.error(`Error loading ${moduleName}: ${error.stack}`);
    return { passed: 0, failed: 1, skipped: 0, errors: [error] };
  }

  for (const testCase of testCases) {
    try {
      // Log current test
      console.log(`Running test case "${testCase.name}"...`);

      // Perform test
      const result = await Promise.all([
        ...Array(testCase.args.length).fill().map((_, i) => externalDataSource.get(testCase.args[i])),
        testCase.fn(blueslipMock, ...testCase.args.map(arg => arg.value))
      ]);

      if (result.every(r => r)) {
        passedCount++;
      } else if (result.some(r => r === null)) {
        skippedCount++;
      } else {
        failedCount++;
      }

      // Reset mocks and data sources
      blueslipMock.reset();
      externalDataSource.clearCache();

    } catch (error) {
      errorStacks.push({ testCase, error });
      console.error(`Error in test case "${testCase.name}": ${error.stack}`);
    }
  }

  const end = Date.now();
  const totalDuration = end - start;
  const moduleLoadingTime = start;
  let externalDataSourceTime = 0;
  let executionTime = 0;

  try {
    // Measure and log times
    const moduleLoadEnd = process.hrtime.bigint();
    externalDataSourceTime += process.hrtime.bigint() - moduleLoadEnd;
    for (const testCase of testCases) {
      const testCaseEnd = process.hrtime.bigint();
      executionTime += testCaseEnd - moduleLoadEnd;
      moduleLoadEnd = testCaseEnd;
    }
  } catch (error) {
    console.error(`Error measuring times: ${error.stack}`);
  }

  // Log summary
  if (failedCount > 0) {
    console.log(`Tests failed: ${failedCount}`);
  }
  if (skippedCount > 0) {
    console.log(`Tests skipped: ${skippedCount}`);
  }
  console.log(`Total duration: ${totalDuration}ms`);
  console.log(`Module loading time: ${(moduleLoadingTime / 1000000).toFixed(2)}ms`);
  console.log(`External data source time: ${(externalDataSourceTime / 1000000).toFixed(2)}ms`);
  console.log(`Execution time: ${(executionTime / 1000000).toFixed(2)}ms`);

  // Return result
  return {
    passed: passedCount,
    failed: failedCount,
    skipped: skippedCount,
    errors: errorStacks,
    performanceMetrics: { totalDuration, moduleLoadingTime, externalDataSourceTime, executionTime }
  };
}']

