function renderFooterScripts(scripts) {
  const footer = document.createElement('footer');
  const scriptBuffer = '';

  function fetchScript(src) {
    return new Promise((resolve, reject) => {
      const cachedResponse = cache.get(src);
      if (cachedResponse) {
        resolve(cachedResponse.text());
      } else {
        fetch(src)
          .then(response => response.text())
          .then(text => {
            cache.set(src, text);
            resolve(text);
          })
          .catch(error => {
            console.error(`Failed to fetch script ${src}:`, error);
            const maxRetries = 3;
            let retries = 0;
            setTimeout(() => {
              if (retries < maxRetries) {
                fetchScript(src).then(resolve, reject);
                retries++;
              } else {
                reject(new Error(`Failed to fetch script ${src} after ${maxRetries} retries`));
              }
            }, 500);
          });
      }
    });
  }

  function renderScript(script) {
    const scriptTag = document.createElement('script');
    if (script.type === 'module' || script.type === 'text/javascript') {
      scriptTag.type = script.type;
      if (script.defer) scriptTag.defer = '';
    } else throw new Error(`Invalid script type: ${script.type}`);
    if (script.src) {
      fetchScript(script.src).then(text => {
        scriptTag.innerHTML = text;
      }).catch(error => console.error('Error rendering script:', error));
    } else scriptTag.innerHTML = script.content;
    footer.appendChild(scriptTag);
  }

  scripts.forEach(script => renderScript(script));

  if (scriptBuffer.length > 10000) {
    alert(`Warning: Combined size of scripts exceeds 10KB. Truncating content.`);
    const truncatedScripts = scriptBuffer.slice(0, 10000).trim();
    footer.innerHTML = truncatedScripts;
  } else footer.innerHTML = scriptBuffer;

  return footer;
}
