const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const axios = require('axios');

class ModuleLoader {
  constructor(rootDir) {
    this.rootDir = rootDir;
    this.moduleCache = {};
  }

  async loadModule(moduleName, dependencies = []) {
    const modulePath = path.join(this.rootDir, `${moduleName}.js`);
    if (!fs.existsSync(modulePath)) return null;

    try {
      const contents = await fs Promises.readFile(modulePath, 'utf8');
      const code = new Function(contents);
      this.moduleCache[moduleName] = code;
      await Promise.all(dependencies.map((dep) => this.loadModule(dep)));
      return code();
    } catch (err) {
      console.error(`Error loading module ${moduleName}: ${err}`);
      return null;
    }
  }

  async loadModulesFromDir(dirPath, dependencies = []) {
    const dirContents = await fs Promises.readdir(dirPath);
    for (const file of dirContents) {
      if (!file.endsWith('.js')) continue;

      try {
        const moduleName = file.replace('.js', '');
        await this.loadModule(moduleName, [...dependencies, moduleName]);
      } catch (err) {
        console.error(`Error loading module ${file}: ${err}`);
      }
    }
  }

  async loadExternalModules() {
    const apiResponse = await axios.get('https://api.example.com/modules');
    for (const module of apiResponse.data) {
      try {
        await this.loadModule(module.name, [...module.dependencies]);
      } catch (err) {
        console.error(`Error loading external module ${module.name}: ${err}`);
      }
    }
  }

  async loadAllModules() {
    await Promise.all([
      this.loadModulesFromDir('path/to/local/modules'),
      this.loadExternalModules(),
    ]);
  }

  async runModule(moduleName) {
    if (!this.moduleCache[moduleName]) return null;

    try {
      const module = this.moduleCache[moduleName];
      const childProcess = spawn('node', [modulePath]);
      childProcess.stdout.on('data', (data) => console.log(`stdout: ${data.toString()}`);
      childProcess.stderr.on('data', (data) => console.error(`stderr: ${data.toString()}`);
      await new Promise((resolve, reject) => {
        childProcess.once('close', () => resolve());
        childProcess.once('error', (err) => reject(err));
      });
    } catch (err) {
      console.error(`Error running module ${moduleName}: ${err}`);
    }
  }

  async runAllModules() {
    await Promise.all(Object.keys(this.moduleCache).map((moduleName) => this.runModule(moduleName)));
  }

  async init() {
    try {
      await this.loadAllModules();
    } catch (err) {
      console.error(`Error initializing module loader: ${err}`);
    }
  }
}

const moduleLoader = new ModuleLoader('path/to/modules');

module.exports = moduleLoader;
