import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionHandler;

public class BackgroundProcessingSystem {
    private ExecutorService executor = Executors.newCachedThreadPool();
    private WorkerPool workerPool;

    public BackgroundProcessingSystem(int initialPoolSize) {
        workerPool = new WorkerPool(initialPoolSize);
        executor.setRejectedExecutionHandler(new RejectedExecutionHandler() {
            @Override
            public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                // Handle rejections and failures by sending the task to a dead-letter queue or logging
                System.out.println("Task rejected due to high load: " + r);
            }
        });
    }

    public void startProcessing() {
        // Start processing tasks in parallel with the configured pool size
        workerPool.startWorkers();
    }

    public void stopProcessing() {
        // Stop all workers and shutdown the executor service
        workerPool.stopWorkers();
        executor.shutdown();
    }

    public class WorkerPool {
        private List<Worker> workers;
        private int poolSize;

        public WorkerPool(int initialPoolSize) {
            this.poolSize = initialPoolSize;
            this.workers = new ArrayList<>();
        }

        public void startWorkers() {
            for (int i = 0; i < poolSize; i++) {
                Worker worker = new Worker();
                workers.add(worker);
                executor.submit(worker);
            }
        }

        public void stopWorkers() {
            // Stop all workers and release system resources
            for (Worker worker : workers) {
                worker.stop();
            }
        }
    }

    public class Worker implements Runnable {
        private boolean isRunning = true;

        @Override
        public void run() {
            while (isRunning) {
                try {
                    // Process data from external sources, handling potential latency and failures
                    processData();
                } catch (Exception e) {
                    // Log the failure for auditing purposes
                    System.out.println("Worker encountered an error: " + e);
                    isRunning = false;
                }
            }
        }

        public void stop() {
            isRunning = false;
        }

        private void processData() {
            // Implementation of data processing logic goes here
        }
    }

    public class RestAPI {
        private Server server;

        public void startServer() {
            server = new Server();
            server.start();
        }

        public void stopServer() {
            server.stop();
        }
    }

    public static void main(String[] args) {
        BackgroundProcessingSystem system = new BackgroundProcessingSystem(5);
        system.startProcessing();

        // Start the REST API to monitor worker status
        RestAPI api = new RestAPI();
        api.startServer();
    }
}
