extern crate hyper;
extern crate log;
use std::default::Default;
use std::collections::HashMap;
use hyper::{Client, RequestBuilder, Body};
use log::{info, error};

pub struct HttpClient {
    client: Client<hyper::client::HttpConnector<hyper::proto::http::HttpMethods>>,
    config: HashMap<String, String>,
    logging_service_url: String,
}

impl Default for HttpClient {
    fn default() -> Self {
        let mut client = hyper::Client::new(hyper::client::HttpConnector::new(hyper::proto::http::HttpMethods));
        let mut config = HashMap::new();
        // default configuration
        let mut logging_service_url = "https://example.com/logs";
        HttpClient { client, config, logging_service_url }
    }
}

impl HttpClient {
    pub fn new() -> Self {
        Default::default()
    }

    pub async fn get(&self, url: &str) -> Result<hyper::response::Body<String>, hyper::error::Error> {
        let request = self.client.get(url).header("Accept", "text/json").body(Body::from(""))?;
        let response = request.send().await?;
        if !response.status().is_success() {
            error!("Failed to retrieve {}: {}", url, response.status());
            return Err(response.into_body().await.unwrap_err());
        }
        let body = response.await?.into_string()?;
        info!("Retrieved {} from {}: {}", body, url);
        Ok(body)
    }

    pub async fn post(&self, url: &str, data: &str) -> Result<hyper::response::Body<String>, hyper::error::Error> {
        let request = self.client.post(url).header("Content-Type", "text/json").body(Body::from(data))?;
        let response = request.send().await?;
        if !response.status().is_success() {
            error!("Failed to post to {}: {}", url, response.status());
            return Err(response.into_body().await.unwrap_err());
        }
        let body = response.await?.into_string()?;
        info!("Posted {} to {}: {}", data, url);
        Ok(body)
    }

    pub async fn retry_on_failure(&self, f: Box<dyn Fn() -> Result<(), hyper::error::Error>> + Send) {
        loop {
            match (*f)().await {
                Ok(()) => return,
                Err(e) => {
                    info!("Transient failure occurred. Retrying in 1 second.");
                    tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                }
            }
        }
    }

    pub async fn fallback(&self, primary_api: &str, alternative_api: &str) -> Result<String, hyper::error::Error> {
        match self.get(primary_api).await {
            Ok(_) => Ok(self.get(primary_api).await?.into_string()?),
            Err(_) => self.get(alternative_api).await,
        }
    }

    pub async fn log_request(&self, request: &str) {
        let req = format!("{} {}", "Request:", request);
        let resp = format!("{} {}", "Response:", "...");
        tokio::time::sleep(std::time::Duration::from_secs(1)).await;
