struct Compiler {
    dir: String,
    compile_with_optimizations: Vec<bool>,
}

impl Compiler {
    fn new(dir: &str) -> Self {
        Compiler {
            dir: dir.to_string(),
            compile_with_optimizations: vec![],
        }
    }

    fn add_file(&mut self, file: &Path, compile_with_optimizations: bool) {
        self.compile_with_optimizations.push(compile_with_optimizations);
    }

    fn compile_files(&self) -> Vec<.CompileResult> {
        let mut results = vec![];
        for (i, file) in self.compile_with_optimizations.iter().enumerate() {
            if *file {
                // Compile with optimizations
                let start = std::time::Instant::now();
                let _ = fs::copy(file, &Path::new(&format!("{}/optimized_{}", &self.dir, i)));
                let end = std::time::Instant::now();
                results.push(CompileResult {
                    compile_time: (end - start).as_secs_f64(),
                    success: true,
                });
            } else {
                // Compile without optimizations
                let start = std::time::Instant::now();
                let _ = fs::copy(file, &Path::new(&format!("{}/unoptimized_{}", &self.dir, i)));
                let end = std::time::Instant::now();
                results.push(CompileResult {
                    compile_time: (end - start).as_secs_f64(),
                    success: true,
                });
            }
        }
        results
    }
}

