```php
<?php

// Include the C-based semaphore management library
include 'semaphore_c_wrapper.php';

// Initialize the semaphore manager
$semaphoreManager = new SemaphoreManager();

// Define the database connection parameters
$db_host = 'localhost';
$db_username = 'root';
$db_password = '';
$db_name = 'clinic_status_db';

// Establish the database connection
$conn = mysqli_connect($db_host, $db_username, $db_password, $db_name);

// Check for database connection errors
if (!$conn) {
    die('Failed to connect to MySQL: ' . mysqli_error($conn));
}

// Define the API endpoint for updating clinic status records
function updateClinicStatus() {
    global $semaphoreManager, $conn;

    // Get the HTTP request data
    $data = json_decode(file_get_contents('php://input'), true);

    // Validate the request data
    if (!isset($data['clinic_id']) || !isset($data['status'])) {
        http_response_code(400);
        echo 'Invalid request data';
        return;
    }

    // Acquire the semaphore to ensure thread-safe access to shared resources
    $semaphoreManager->acquireSemaphore();

    try {
        // Update the clinic status record in the database
        $sql = "UPDATE clinic_status SET status=?, last_modified_ip=?, timestamp=? WHERE id=?";
        $stmt = mysqli_prepare($conn, $sql);
        mysqli_stmt_bind_param($stmt, 'sssi', $data['status'], $data['last_modified_ip'], time(), $data['clinic_id']);
        mysqli_stmt_execute($stmt);

        // Release the semaphore
        $semaphoreManager->releaseSemaphore();
    } catch (Exception $e) {
        // Handle database errors and release the semaphore
        http_response_code(500);
        echo 'Error updating clinic status: ' . $e->getMessage();
        $semaphoreManager->releaseSemaphore();
    }
}

// Start the API endpoint
updateClinicStatus();

?>
