**C-based Semaphore Management Component ( semaphore_c_wrapper.c )**

```c
#include <semaphore.h>
#include <pthread.h>

// Define the semaphore manager class
typedef struct {
    sem_t *semaphore;
} SemaphoreManager;

// Function to initialize the semaphore manager
SemaphoreManager* initSemaphoreManager() {
    SemaphoreManager* manager = malloc(sizeof(SemaphoreManager));
    manager->semaphore = sem_open("/my_semaphore", O_CREAT, 0644, 1);
    return manager;
}

// Function to acquire the semaphore
void acquireSemaphore(SemaphoreManager* manager) {
    sem_wait(manager->semaphore);
}

// Function to release the semaphore
void releaseSemaphore(SemaphoreManager* manager) {
    sem_post(manager->semaphore);
}

// Free the semaphore manager resources
void freeSemaphoreManager(SemaphoreManager* manager) {
    sem_close(manager->semaphore);
    free(manager);
}
```

