CREATE PROCEDURE sp_GetEmployeeDetails
    @SupervisorID INT,
    @DepartmentID INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EmployeeDetails TABLE (Name NVARCHAR(50), City NVARCHAR(30), Address NVARCHAR(100));

    BEGIN TRY
        -- Retrieve employee details from database
        INSERT INTO @EmployeeDetails
        SELECT E.Name, E.City, E.Address
        FROM Employees E
        WHERE E.SupervisorID = @SupervisorID;

        -- Fetch department-specific data from external API
        DECLARE @APIResponse XML;
        SET @APIResponse = EXEC('https://api.departmentdata.com/departments/' + CONVERT(NVARCHAR(10), @DepartmentID) + '?token=YOUR_API_TOKEN');

        BEGIN TRANSACTION;

            -- Update employee details with API response
            UPDATE E
            SET E.City = @APIResponse.value('(/root/City)[1]', 'NVARCHAR(30)'),
                E.Address = @APIResponse.value('(/root/Address)[1]', 'NVARCHAR(100)')
            FROM Employees E
            INNER JOIN @EmployeeDetails ED ON E.ID = ED.Name;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        DECLARE @ErrorMessage NVARCHAR(MAX);
        SET @ErrorMessage = 'Error occurred at ' + CONVERT(NVARCHAR, GETDATE()) + ': ' + ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1);
    END CATCH;

    -- Implement caching strategy for repeated data fetches
    DECLARE @Cache TABLE (DepartmentID INT, CacheData XML);

    IF NOT EXISTS (SELECT 1 FROM @Cache WHERE DepartmentID = @DepartmentID)
    BEGIN
        INSERT INTO @Cache (DepartmentID, CacheData)
        VALUES (@DepartmentID, @APIResponse);
    END

    -- Optimize repeated data fetches by using cache
    SELECT E.Name, E.City, E.Address
    FROM Employees E
    WHERE E.SupervisorID = @SupervisorID AND E.DepartmentID = @DepartmentID;
END;

CREATE TABLE #logs (
    ID INT,
    Timestamp DATETIME,
    Message NVARCHAR(MAX),
    Severity INT
);

-- Securely manage database credentials and implement robust logging for all operations
EXEC sp_GetEmployeeDetails 123, 456;
