<?php

declare(strict_types=1);

namespace SecureToken;

use DateTimeImmutable;
use Exception;
use JsonWebToken\JWK\Keyset;
use League\Flysystem\FilesystemInterface;
use Lcobucci\JWT\Signer\Rsa;
use Lcobucci\JWT\TokenBuilder;
use Monolog\Loggers\NullLogger;
use Monolog\Utils\DateTimeIntrospection;
use Ramsey\Uuid\Uuid;

class SecureToken
{
    private $secretKeyset;
    private $signer;
    private $logger;
    private $filesystem;
    private $maxAttempts = 5;

    public function __construct(FilesystemInterface $filesystem, string $vaultUrl)
    {
        $this->filesystem = $filesystem;
        $this->logger = new NullLogger();
        $this->secretKeyset = new Keyset($vaultUrl);
        $this->signer = new Rsa($this->secretKeyset->getPublicKey());
    }

    public function generateToken(string $subject, int $expiresIn): string
    {
        try {
            $tokenBuilder = (new TokenBuilder())
                ->identifiedBy('myuniqueidentifier')
                ->issuedAt(DateTimeImmutable::now())
                ->expiresAt(new DateTimeImmutable('+1 hour'))
                ->withClaim('sub', Uuid::uuid4()->toString());
            if ($expiresIn > 0) {
                $tokenBuilder->expiresAt(
                    new DateTimeImmutable('+ ' . $expiresIn . ' seconds')
                );
            }
            $token = $tokenBuilder
                ->withClaim('iss', 'myissuer')
                ->withClaim('aud', 'myaudience')
                ->getToken($this->signer);
            return (string) $token;
        } catch (Exception $e) {
            $this->logger->critical('Token generation failed:', ['exception' => $e]);
            if ($this->maxAttempts > 0) {
                usleep(100000); // wait before retry
                --$this->maxAttempts;
                return $this->generateToken($subject, $expiresIn);
            }
            throw new Exception('Maximum attempts exceeded');
        }
    }

    public function generateJwt(string $subject, int $expiresIn): string
    {
        try {
            $token = (new Lcobucci\JWT\Builder())
                ->issuedBy('myissuer')
                ->permittedFor('myaudience')
                ->identifiedBy(Uuid::uuid4()->toString())
                ->withClaim('sub', $subject)
                ->expiresAt(new DateTimeImmutable('+ ' . $expiresIn . ' seconds'))
                ->sign($this->signer);
            return (string) $token;
        } catch (Exception $e) {
            $this->logger->critical('JWT generation failed:', ['exception' => $e]);
            if ($this->maxAttempts > 0) {
                usleep(100000); // wait before retry
                --$this->maxAttempts;
                return $this->generateJwt($subject, $expiresIn);
            }
            throw new Exception('Maximum attempts exceeded');
        }
    }
}
