class RegistryManager:
    def __init__(self):
        self.registry = {}

    def add_factory_function(self, id, factory_func):
        self.registry[id] = factory_func

    def get_factory_function(self, id):
        return self.registry.get(id)

class FileHandler:
    def __init__(self, registry_manager):
        self.registry_manager = registry_manager
        self.json_parser = None

    def read_file(self, file_path, file_format='json'):
        if file_format == 'csv':
            with open(file_path, 'r') as f:
                return [row for row in csv.reader(f)]
        elif file_format == 'json':
            with open(file_path, 'r') as f:
                self.json_parser = json.load(f)
                return self.json_parser
        else:
            raise ValueError("Unsupported file format")

    def write_file(self, data, file_path, file_format='json'):
        if file_format == 'csv':
            with open(file_path, 'w', newline='') as f:
                writer = csv.writer(f)
                writer.writerows(data)
        elif file_format == 'json':
            with open(file_path, 'w') as f:
                json.dump(data, f)

    def extract_sequence_numbers(self, data):
        sequence_numbers = []
        for row in data:
            if isinstance(row['sequence_number'], int):
                sequence_numbers.append(row['sequence_number'])
        return sequence_numbers

class JSONParser:
