        return json.loads(json_data)

class DataProcessor:
    def __init__(self, registry_manager):
        self.registry_manager = registry_manager
        self.file_handler = FileHandler(registry_manager)
        self.json_parser = JSONParser()

    def process_data(self, file_path, file_format='json'):
        data = self.file_handler.read_file(file_path, file_format)
        if file_format == 'json':
            data = self.json_parser.parse_json(data)

        # Perform data processing tasks here
        print("Processed data:", data)

        return data

    def integrate_with_third_party_api(self, api_url):
        try:
            response = requests.get(api_url)
            response.raise_for_status()
            enriched_data = json.loads(response.content)
            return enriched_data
        except requests.exceptions.RequestException as e:
            print(f"Error integrating with API: {e}")
            return None

    def handle_errors(self, exception):
        if isinstance(exception, requests.exceptions.RequestException):
            # Retry logic for transient failures
            try:
                self.integrate_with_third_party_api(api_url)
            except Exception as e:
                print(f"Error retrying: {e}")
        else:
            raise exception

if __name__ == "__main__":
    registry_manager = RegistryManager()
    data_processor = DataProcessor(registry_manager)

    # Example usage
