// Define the structure for state node
typedef struct {
    int id;
    char *name;
    // Add more fields as needed
} StateNode;

// Define the linked list of states
typedef struct {
    StateNode *head;
    int count;
} StateList;

// Function to create a new state node
StateNode* createStateNode(int id, char *name) {
    StateNode *node = (StateNode *)malloc(sizeof(StateNode));
    if (!node) return NULL;
    node->id = id;
    node->name = name;
    // Add more fields as needed
    return node;
}

// Function to add a state node to the linked list
void addState(StateList *list, StateNode *node) {
    if (!list->head) {
        list->head = node;
    } else {
        StateNode *current = list->head;
        while (current->next) current = current->next;
        current->next = node;
    }
    list->count++;
}

// Function to remove a state node from the linked list
void removeState(StateList *list, int id) {
    if (!list->head) return;
    StateNode *current = list->head;
    StateNode *previous = NULL;
    while (current && current->id != id) {
        previous = current;
        current = current->next;
    }
    if (current) {
        if (previous) previous->next = current->next;
        else list->head = current->next;
        free(current);
        list->count--;
    }
}

// Function to retrieve a state node from the linked list
StateNode* getState(StateList *list, int id) {
    StateNode *current = list->head;
    while (current && current->id != id) current = current->next;
    return current;
}

// Function to free all allocated memory
void freeMemory(StateList *list) {
    StateNode *current = list->head;
    StateNode *previous = NULL;
    while (current) {
        previous = current;
        current = current->next;
        free(previous);
    }
    list->count = 0;
    list->head = NULL;
}

