    private readonly IExternalService _externalService;
    private readonly object _lock = new object();
    private double _lowerBound;
    private double _upperBound;
    private DateTime _lastUpdate;

    public DynamicRangeRandomValueGenerator(IExternalService externalService)
    {
        _externalService = externalService;
        UpdateRangesAsync().Wait(); // Initialize with the latest range values
    }

    public async Task<double> GenerateRandomValue()
    {
        while (true)
        {
            try
            {
                await Task.Delay(10); // Simulate a random delay for performance
                return new Random().NextDouble() * (_upperBound - _lowerBound) + _lowerBound;
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }
    }

    public async Task UpdateRangesAsync()
    {
        try
        {
            var rangeParams = await _externalService.GetLatestRangeParametersAsync();
            lock (_lock)
            {
                _lowerBound = rangeParams.LowerBound;
                _upperBound = rangeParams.UpperBound;
                _lastUpdate = DateTime.Now;
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
        }
    }

    public override string ToString()
    {
        return $"Current Range: {(_lowerBound)..{_upperBound}}\nLast Update: {_lastUpdate}\nService Status: {(GetExternalServiceStatus() ? "Available" : "Unavailable")}";
    }

