        if (strlen(strings[i]) >= config.max_size) {
            // Log the exceeded size
            char log_message[LOG_BUFFER_SIZE];
            sprintf(log_message, "String %s exceeds size limit: %d bytes", strings[i], strlen(strings[i]));
