            // Discard the string and decrement the count
            free(strings[i]);
            strings[i] = NULL;
            (*count)--;
        } else {
            char *new_string = (char *)malloc(strlen(strings[i]) + strlen(".done") + 1);
            strcpy(new_string, strings[i]);
            strcat(new_string, ".done");
            // Update the original string
            free(strings[i]);
            strings[i] = new_string;
        }
    }
}

void monitor_pipeline(int *dropped_count, size_t *total_memory_used) {
    // Monitor and update metrics here
    printf("Dropped strings: %d\n", *dropped_count);
    printf("Total memory used: %zu bytes\n", *total_memory_used);
}

int main() {
    int count = 0;
    char **strings = NULL;

    // Initialize the configuration
    config.max_size = MAX_STRING_SIZE; // Default size limit

    while (1) {
        // Process strings here...
        if (process_strings()) {
            break;
        }

        // Update metrics and monitor the pipeline
        int dropped_count = 0;
        size_t total_memory_used = 0;
        monitor_pipeline(&dropped_count, &total_memory_used);
    }

    // Clean up memory
    for (int i = 0; i < count; i++) {
        free(strings[i]);
    }
    free(strings);

    return 0;
}

