#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>

class AES256CBCService {
public:
    AES256CBCService() : iv_(AES_BLOCK_SIZE, 0) {}

    std::string encrypt(const std::string& plaintext, const std::string& password) {
        // Derive the key from the password using PBKDF2
        unsigned char* derivedKey = new unsigned char[AES_KEY_LENGTH];
        int ret = PBKDF2(password.data(), password.size(), derivedKey, AES_KEY_LENGTH, 1000);
        if (ret != 1) {
            std::cerr << "Error deriving key: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return "";
        }

        // Generate a secure random salt and IV
        unsigned char* salt = new unsigned char[AES_BLOCK_SIZE];
        RAND_bytes(salt, AES_BLOCK_SIZE);
        unsigned char* ivCopy = new unsigned char[AES_BLOCK_SIZE];
        memcpy(ivCopy, &iv_, AES_BLOCK_SIZE);

        // Encrypt the plaintext using AES-256-CBC
        unsigned char* ciphertext = new unsigned char[plaintext.size()];
        int encryptedSize = AES_cbc_encrypt(plaintext.data(), ciphertext, plaintext.size(), derivedKey, ivCopy, 1);
        if (encryptedSize != plaintext.size()) {
            std::cerr << "Error encrypting data: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return "";
        }

        // Free memory and return the encrypted data
        delete[] salt;
        delete[] ivCopy;
        delete[] derivedKey;
        delete[] ciphertext;

        return std::string((char*)ciphertext, encryptedSize);
    }

    std::string decrypt(const std::string& ciphertext, const std::string& password) {
        // Derive the key from the password using PBKDF2
        unsigned char* derivedKey = new unsigned char[AES_KEY_LENGTH];
        int ret = PBKDF2(password.data(), password.size(), derivedKey, AES_KEY_LENGTH, 1000);
        if (ret != 1) {
            std::cerr << "Error deriving key: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return "";
        }

        // Decrypt the ciphertext using AES-256-CBC
        unsigned char* decrypted = new unsigned char[ciphertext.size()];
        int decryptedSize = AES_cbc_decrypt(ciphertext.data(), decrypted, ciphertext.size(), derivedKey, &iv_, 1);
        if (decryptedSize != ciphertext.size()) {
            std::cerr << "Error decrypting data: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return "";
        }

        // Free memory and return the decrypted plaintext
        delete[] derivedKey;
        delete[] decrypted;

        return std::string((char*)decrypted, decryptedSize);
    }

private:
    unsigned char iv_[AES_BLOCK_SIZE];
};

int main() {
    AES256CBCService service;
    std::string password = "my_secret_password";
    std::string plaintext = "Hello, World!";
    std::string ciphertext = service.encrypt(plaintext, password);
    std::string decrypted = service.decrypt(ciphertext, password);

    // Verify the decryption
    if (decrypted != plaintext) {
        std::cerr << "Decryption failed!" << std::endl;
    } else {
        std::cout << "Decryption successful!" << std::endl;
    }

    return 0;
}

