#include <filesystem>
#include <thread>
#include "third_party_library.h"
#include "zlib.h"

int process_images(const std::vector<std::string>& image_filenames,
                    const std::string& output_dir) {
    if (!std::filesystem::exists(output_dir)) {
        std::filesystem::create_directory(output_dir);
    }

    std::thread threads[4]; // Define a thread pool with 4 worker threads
    int failed_count = 0;

    for (const auto& filename : image_filenames) {
        try {
            // Load the image using the third-party library
            third_party_library::Image image = load_image(filename);

            // Convert the image to PNG format and compress it
            std::string png_data;
            zlib::compress(png_data, image.to_png());

            // Write the compressed PNG data to a temporary file
            std::filesystem::path temp_file_path =
                output_dir / (filename + "_compressed.png");
            std::ofstream temp_file(temp_file_path);
            temp_file.write(png_data.data(), png_data.size());
            temp_file.close();

            // Add the temporary file to the ZIP archive
            {
                std::lock_guard<std::mutex> lock(archive_mutex_);
                zip_.write_file(temp_file_path, "image_" + filename);
            }

        } catch (const std::exception& e) {
            failed_count++;
            log_error("Failed to process image: " + filename +
                       ", error message: " + e.what());
        }
    }

    // Wait for all worker threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    return failed_count ? 1 : 0; // Return failure status if any images failed
}
