#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <json-c/json.h>

// Function to validate the OAuth2 access token response
void validate_oauth_token(const char* json_string) {
    // Parse the JSON string
    json_object *token_json = json_object_from_string(json_string);

    if (!token_json) {
        printf("Invalid JSON object\n");
        return;
    }

    // Check for required fields: access_token, expires_in, and token_type
    const char* access_token = json_object_get_string(token_json, "access_token");
    int expires_in = json_object_get_int(token_json, "expires_in");
    const char* token_type = json_object_get_string(token_json, "token_type");

    if (!access_token || strlen(access_token) == 0 || expires_in < 1 || strcmp(token_type, "Bearer") != 0) {
        printf("Invalid or missing required field(s)\n");
        return;
    }

    // Check for optional fields: refresh_token and scope
    const char* refresh_token = json_object_get_string(token_json, "refresh_token");
    const char* scope = json_object_get_string(token_json, "scope");

    if (refresh_token && strlen(refresh_token) > 0 || scope && strlen(scope) > 0) {
        // Verify the token's validity asynchronously using an external authentication service
        int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in serv_addr;
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(8080);
        inet_pton(AF_INET, "127.0.0.1", &(serv_addr.sin_addr));
        connect(socket_fd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));

        // Send the token verification request
        char* request = (char*)malloc(1024);
        sprintf(request, "{\"access_token\": \"%s\", \"expires_in\": %d}", access_token, expires_in);
        send(socket_fd, request, strlen(request), 0);

        free(request);

        close(socket_fd);
    }
}
