        private readonly TimeSpan _backoffDuration;

        public RetryPolicy(int maxAttempts, TimeSpan backoffDuration)
        {
            _maxAttempts = maxAttempts;
            _backoffDuration = backoffDuration;
        }

        public async Task ProcessAsync(byte[] data)
        {
            // Implement retry logic here with exponential backoff
            for (int attempt = 1; attempt <= _maxAttempts; attempt++)
            {
                try
                {
                    await NextProcessor.ProcessAsync(data);
                    break;
                }
                catch (Exception ex) when IsTransientError(ex))
                {
                    Console.WriteLine($"Retrying transmission ({attempt} / {_maxAttempts})...");
                    await Task.Delay(_backoffDuration);
                }
            }
        }
    }

    public class Pipeline
    {
        private readonly IDataProcessor[] _processors;

        public Pipeline(params IDataProcessor[] processors)
        {
            _processors = processors;
        }

        public async Task ProcessAsync(byte[] data)
        {
            foreach (var processor in _processors)
            {
                await processor.ProcessAsync(data);
            }
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var pipeline = new Pipeline(new ChecksumValidator(), new Encryptor("AES"), new TLSTransmitter(new TcpClient()), new DatabaseWriter("Server=localhost;Database=mydatabase"));
            await pipeline.ProcessAsync(new byte[1024]);
        }
    }
