['Here is the C# code block for securely managing user authentication credentials:

```csharp
using System;
using System.Security.Cryptography;
using System.Data.SqlClient;

public class SecureAuthManager
{
    private readonly string _primaryAlgorithm;
    private readonly int _saltLength;
    private readonly int _iterationCount;
    private readonly string _secondaryAlgorithm;

    public SecureAuthManager(IConfiguration config)
    {
        _primaryAlgorithm = "SHA-256";
        _secondaryAlgorithm = "MD5";
        _saltLength = 16;
        _iterationCount = 1000;

        // Initialize database connection
        using (var dbConnection = new SqlConnection("Data Source=<database_source>;Initial Catalog=<catalog_name>;User ID=<username>;Password=<password>;"))
        {
            dbConnection.Open();
        }
    }

    public void GenerateCredentials(string password, int userId)
    {
        // Generate random salt
        var rng = RandomNumberGenerator.Create();
        var saltBytes = new byte[_saltLength];
        rng.GetBytes(saltBytes);

        // Generate primary hash using SHA-256
        using (var sha256 = SHA256.Create())
        {
            var passwordBytes = Encoding.UTF8.GetBytes(password);
            var hashedPasswordBytes = sha256.ComputeHash(passwordBytes, 0, passwordBytes.Length);
            var primaryHash = BitConverter.ToString(hashedPasswordBytes).Replace("-", "");

            // Generate secondary hash using MD5 (fallback)
            using (var md5 = MD5.Create())
            {
                var secondaryHashBytes = md5.ComputeHash(passwordBytes, 0, passwordBytes.Length);
                var secondaryHash = BitConverter.ToString(secondaryHashBytes).Replace("-", "");
            }
        }

        // Store metadata in database
        using (var dbConnection = new SqlConnection("Data Source=<database_source>;Initial Catalog=<catalog_name>;User ID=<username>;Password=<password>;"))
        {
            dbConnection.Open();

            var command = new SqlCommand("INSERT INTO UserMetadata (UserId, Algorithm, Salt, PrimaryHash, SecondaryHash) VALUES (@UserId, @Algorithm, @Salt, @PrimaryHash, @SecondaryHash)", dbConnection);
            command.Parameters.AddWithValue("@UserId", userId);
            command.Parameters.AddWithValue("@Algorithm", _primaryAlgorithm);
            command.Parameters.AddWithValue("@Salt", BitConverter.ToString(saltBytes).Replace("-", ""));
            command.Parameters.AddWithValue("@PrimaryHash", primaryHash);
            command.Parameters.AddWithValue("@SecondaryHash", secondaryHash);

            command.ExecuteNonQuery();
        }
    }

    public bool VerifyPassword(string password, int userId)
    {
        // Retrieve stored metadata from database
        using (var dbConnection = new SqlConnection("Data Source=<database_source>;Initial Catalog=<catalog_name>;User ID=<username>;Password=<password>;"))
        {
            dbConnection.Open();

            var command = new SqlCommand("SELECT Algorithm, Salt, PrimaryHash FROM UserMetadata WHERE UserId = @UserId", dbConnection);
            command.Parameters.AddWithValue("@UserId", userId);

            using (var reader = command.ExecuteReader())
            {
                if (!reader.Read())
                {
                    return false; // User not found
                }

                var algorithm = reader["Algorithm"].ToString();
                var saltBytes = Convert.FromBase64String(reader["Salt"].ToString());
                var primaryHash = reader["PrimaryHash"].ToString();

                try
                {
                    if (algorithm == _primaryAlgorithm)
                    {
                        using (var sha256 = SHA256.Create())
                        {
                            var passwordBytes = Encoding.UTF8.GetBytes(password);
                            var hashedPasswordBytes = sha256.ComputeHash(passwordBytes, 0, passwordBytes.Length);

                            // Verify primary hash
                            if (BitConverter.ToString(hashedPasswordBytes).Replace("-", "") == primaryHash)
                            {
                                return true;
                            }
                            else
                            {
                                // Fall back to secondary algorithm (MD5) for legacy systems
                                using (var md5 = MD5.Create())
                                {
                                    var secondaryHashBytes = md5.ComputeHash(passwordBytes, 0, passwordBytes.Length);
                                    var secondaryHash = BitConverter.ToString(secondaryHashBytes).Replace("-", "");

                                    if (secondaryHash == reader["SecondaryHash"].ToString())
                                    {
                                        return true;
                                    }
                                    else
                                    {
                                        // Log failed verification attempt
                                        using (var logWriter = File.CreateText("auth_log.txt"))
                                        {
                                            logWriter.WriteLine($"Verification failed for user {userId} with password {password}");
                                        }

                                        return false; // Verification failed
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        // Legacy system: use MD5 as primary algorithm and secondary hash as fallback
                        using (var md5 = MD5.Create())
                        {
                            var passwordBytes = Encoding.UTF8.GetBytes(password);
                            var hashedPasswordBytes = md5.ComputeHash(passwordBytes, 0, passwordBytes.Length);

                            if (BitConverter.ToString(hashedPasswordBytes).Replace("-", "") == reader["PrimaryHash"].ToString())
                            {
                                return true;
                            }
                            else
                            {
                                // Log failed verification attempt
                                using (var logWriter = File.CreateText("auth_log.txt"))
                                {
                                    logWriter.WriteLine($"Verification failed for user {userId} with password {password}");
                                }

                                return false; // Verification failed
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    // Log error and rethrow exception
                    using (var logWriter = File.CreateText("auth_log.txt"))
                    {
                        logWriter.WriteLine($"Error occurred during verification for user {userId}: {ex.Message}");
                    }

                    throw;
                }
            }
        }
    }
}
