using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using Newtonsoft.Json;

public class EncryptedDataProcessor
{
    public async Task<CustomDataStructure> ProcessEncryptedFileAsync(string fileUrl, string encryptionKey, byte[] iv, CustomDataStructure dataStructure)
    {
        try
        {
            using var httpClient = new HttpClient();
            using var request = new HttpRequestMessage(HttpMethod.Get, fileUrl);

            // Download the encrypted file asynchronously
            using var response = await httpClient.SendAsync(request);
            if (!response.IsSuccessStatusCode)
                throw new Exception($"Failed to download file: {response.StatusCode}");

            var encryptedFileContent = await response.Content.ReadAsByteArrayAsync();
            if (encryptedFileContent == null || encryptedFileContent.Length == 0)
                throw new Exception("Invalid or empty file content");

            // Decrypt the file content using AES-CBC with the specified key and IV
            using var aes = Aes.Create();
            aes.Key = encryptionKey.GetBytes(aes.KeySize / 8);
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using var decryptor = aes.CreateDecryptor();
            using var memoryStream = new MemoryStream(encryptedFileContent);
            using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);

            byte[] decryptedData = new byte[cryptoStream.Length];
            await cryptoStream.ReadAsync(decryptedData.AsMemory(), 0, decryptedData.Length);

            // Deserialize the decrypted byte array into the custom data structure
            string deserializedData;
            try
            {
                deserializedData = JsonConvert.SerializeObject(new MemoryStream(decryptedData));
            }
            catch (Exception ex)
            {
                throw new Exception("Failed to deserialize data: " + ex.Message);
            }

            return JsonConvert.DeserializeObject<CustomDataStructure>(deserializedData);
        }
        catch (HttpRequestException ex)
        {
            // Log the error and provide a user-friendly message
            Console.WriteLine($"Error downloading file: {ex.Message}");
            throw new Exception("Failed to download file");
        }
        catch (CryptographicException ex)
        {
            // Log the error and provide a user-friendly message
            Console.WriteLine($"Error decrypting data: {ex.Message}");
            throw new Exception("Invalid or corrupted encryption key");
        }
    }
}
