import java.io.*;
import java.lang.reflect.*;
import java.util.concurrent.*;

public class ObjectDeserializerService {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Logger logger = LoggerFactory.getLogger(ObjectDeserializerService.class);
    private final boolean failOnException;
    private final Class<?>[] supportedClasses;

    public ObjectDeserializerService(boolean failOnException, Class<?>... supportedClasses) {
        this.failOnException = failOnException;
        this.supportedClasses = supportedClasses;
    }

    public <T> List<T> deserialize(byte[][] input) throws Exception {
        List<T> result = new ArrayList<>();
        for (byte[] bytes : input) {
            try {
                T obj = deserialize(bytes);
                result.add(obj);
            } catch (StreamCorruptedException e) {
                logger.error("Error deserializing byte array: {}", e.getMessage());
            }
        }
        return result;
    }

    public <T> T deserialize(byte[] bytes) throws Exception {
        try {
            ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes));
            T obj = (T) in.readObject();
            in.close();
            return obj;
        } catch (ClassNotFoundException e) {
            throw new CustomException("Unsupported class: " + e.getMessage(), e);
        } catch (IOException e) {
            if (failOnException) {
                throw new Exception(e.getMessage());
            }
            return null; // Return default value
        }
    }

    public void shutdown() {
        executor.shutdown();
    }

    private static class CustomException extends RuntimeException {
        public CustomException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
