const AWS = require('aws-sdk');
const { GCS } = require('@google-cloud/storage');
const { rateLimit } = require('express-rate-limit');
const axios = require('axios');

function uploadFile(url, callback) {
  const allowedExtensions = ['jpg', 'jpeg', 'png', 'pdf'];
  const filePath = url.split('/').pop();
  const fileExt = filePath.split('.').pop().toLowerCase();

  if (!allowedExtensions.includes(fileExt)) {
    return callback(new Error(`Unsupported file type: ${fileExt}`));
  }

  const s3 = new AWS.S3({ region: 'your-region' });
  const gcs = new GCS({
    projectId: 'your-project-id',
  });

  async function uploadToS3() {
    try {
      const params = { Bucket: 'your-bucket', Key: filePath, Body: await axios.get(url) };
      s3.upload(params).send((err) => {
        if (err) {
          callback(new Error(`Upload to S3 failed: ${err}`));
        } else {
          console.log(`File uploaded successfully to S3: ${filePath}`);
          callback(null);
        }
      });
    } catch (error) {
      callback(error);
    }
  }

  async function uploadToGCS() {
    try {
      const bucket = gcs.bucket('your-bucket');
      const fileStream = await axios.get(url, { responseType: 'stream' });
      bucket.upload({
        destination: filePath,
        source: fileStream.data,
        metadata: { contentType: fileExt === 'jpg' ? 'image/jpeg' : 'application/pdf' },
      }, (err) => {
        if (err) {
          callback(new Error(`Upload to GCS failed: ${err}`));
        } else {
          console.log(`File uploaded successfully to GCS: ${filePath}`);
          callback(null);
        }
      });
    } catch (error) {
      callback(error);
    }
  }

  const uploadQueue = [];
  async function upload() {
    if (!uploadQueue.length) return;

    const fileToUpload = uploadQueue.shift();
    await (fileToUpload === 'S3' ? uploadToS3() : uploadToGCS());
    setTimeout(upload, 1000); // Retry every second
  }

  rateLimit({
    windowMs: 30 * 60 * 1000,
    max: 5,
    delayAfter: 3,
  })(async () => {
    uploadQueue.push('S3');
    uploadQueue.push('GCS');
    upload();

    process.on('exit', () => {
      uploadQueue.forEach((service) => {
        if (service === 'S3') {
          await s3.listObjects({ Bucket: 'your-bucket' }).send();
        } else if (service === 'GCS') {
          const bucket = gcs.bucket('your-bucket');
          await bucket.getFiles().then((files) => console.log(files));
        }
      });
    });

    process.on('SIGTERM', () => {
      uploadQueue.forEach((service) => {
        if (service === 'S3') {
          await s3.listObjects({ Bucket: 'your-bucket' }).send();
        } else if (service === 'GCS') {
          const bucket = gcs.bucket('your-bucket');
          await bucket.getFiles().then((files) => console.log(files));
        }
      });
    });
  });

  uploadQueue.push('S3');
  uploadQueue.push('GCS');

  process.on('SIGINT', () => {
    process.exit();
  });

  setTimeout(() => {
    console.log('Uploads in progress. Please wait...');
  }, 1000);

  if (callback) callback(null);
}

module.exports = uploadFile;
