// kickstart-config-service.js
const { readFileSync, writeFileSync } = require('fs');
const { join } = require('path');
const crypto = require('crypto');
const axios = require('axios');

class KickstartConfigService {
  async modifyConfig(configFile, placeholders, password) {
    const config = JSON.parse(readFileSync(configFile, 'utf8'));
    for (const [placeholder, value] of Object.entries(placeholders)) {
      config[placeholder] = value;
    }
    try {
      const encryptedConfig = await this.encryptConfig(config, password);
      writeFileSync(configFile, JSON.stringify(encryptedConfig), 'utf8');
    } catch (err) {
      console.error(`Error modifying config file: ${err.message}`);
    }
  }

  async encryptConfig(config, password) {
    const encryptionKey = await this.getEncryptionKey();
    const encryptedData = crypto.createCipher('aes-256-cbc', encryptionKey).update(JSON.stringify(config), 'utf8', 'hex');
    return { ...config, encrypted: encryptedData };
  }

  async getEncryptionKey() {
    try {
      const response = await axios.post('https://encryption-service.com/issue-key', { user: 'your-username' });
      return response.data.key;
    } catch (err) {
      console.error(`Error obtaining encryption key: ${err.message}`);
      throw err;
    }
  }

  async checkConfigChanges(configFile, password) {
    try {
      const config = JSON.parse(readFileSync(configFile, 'utf8'));
      const encryptedConfig = await this.encryptConfig(config, password);
      writeFileSync(configFile, JSON.stringify(encryptedConfig), 'utf8');
    } catch (err) {
      console.error(`Error updating config file: ${err.message}`);
    }
  }

  async startService(port) {
    const server = http.createServer((req, res) => {
      if (req.method === 'POST') {
        try {
          const { configFile, placeholders, password } = JSON.parse(req.body);
          await this.modifyConfig(join(__dirname, '..', configFile), placeholders, password);
          res.writeHead(201, {'Content-Type': 'application/json'});
          res.end(JSON.stringify({ message: 'Configuration updated successfully' }));
        } catch (err) {
          res.writeHead(500, {'Content-Type': 'text/plain'});
          res.end(`Error updating config file: ${err.message}`);
        }
      } else if (req.method === 'GET') {
        try {
          const { configFile } = JSON.parse(req.query);
          await this.checkConfigChanges(join(__dirname, '..', configFile), 'your-password');
          res.writeHead(200, {'Content-Type': 'application/json'});
          res.end(JSON.stringify({ message: 'Configuration updated successfully' }));
        } catch (err) {
          res.writeHead(500, {'Content-Type': 'text/plain'});
          res.end(`Error updating config file: ${err.message}`);
        }
      } else {
        res.writeHead(405, {'Content-Type': 'text/plain'});
        res.end('Method not allowed');
      }
    });

    server.listen(port, () => {
      console.log(`Kickstart Config Service listening on port ${port}`);
    });
  }
}

const service = new KickstartConfigService();
service.startService(3000);
