['```rust
use async_std::task;
use tokio::{time::sleep, runtime::Runtime};

struct Task {
    id: u32,
    priority: u8,
    name: String,
}

impl Task {
    fn new(id: u32, name: String) -> Self {
        Task { id, priority: 0, name }
    }
}

async fn execute_task(task: &Task) {
    println!("Executing task {} with priority {}", task.id, task.priority);
    // Simulate task execution
    sleep(std::time::Duration::from_millis(1000)).await;
    println!("Task {} completed", task.id);
}

struct ServiceManager {
    tasks: Vec<Task>,
    max_concurrent_tasks: u32,
    current_load: f64,
    cpu_usage: f64,
    memory_usage: f64,
    network_usage: f64,
}

impl ServiceManager {
    async fn new() -> Self {
        ServiceManager {
            tasks: vec![],
            max_concurrent_tasks: 20,
            current_load: 0.0,
            cpu_usage: 0.0,
            memory_usage: 0.0,
            network_usage: 0.0,
        }
    }

    async fn add_task(&mut self, task: Task) {
        self.tasks.push(task);
        if self.tasks.len() > self.max_concurrent_tasks {
            // Adjust max concurrent tasks based on current load
            self.max_concurrent_tasks = (self.current_load * 2.0).round() as u32;
        }
    }

    async fn run(&mut self) {
        let mut runtime = Runtime::new().unwrap();
        while let Some(task) = self.tasks.pop() {
            task.execute(runtime).await.unwrap_or_else(|e| {
                eprintln!("Error executing task {}: {}", task.id, e);
            });
        }
    }

    async fn monitor_resources(&mut self) {
        // Monitor CPU, memory, and network usage
        // Adjust max concurrent tasks based on current load
        self.current_load = 0.5;
        self.cpu_usage = 0.8;
        self.memory_usage = 0.6;
        self.network_usage = 0.4;
    }
}

#[tokio::main]
async fn main() {
    let mut service_manager = ServiceManager::new().await;
    while true {
        // Handle command-line input
        match std::io::stdin().read_line(&mut String::new()) {
            Ok(line) => {
                if line.trim() == "exit" {
                    break;
                }
                let task_name = line.trim();
                let task = Task::new(1, task_name.to_string());
                service_manager.add_task(task).await;
            }
            Err(_) => {}
        }
    }
    service_manager.run().await;
}
