class JsonParser(ABC):
    @abstractmethod
    def parse(self, json_string: str) -> dict:
        pass

class Registry:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register(cls, id: str, parser_class: type) -> None:
        with cls._lock:
            cls._registry[id] = parser_class

    @classmethod
    def get_parser(cls, id: str, json_string: str) -> JsonParser:
