    if (expires_in <= 0) {
        // Handle error: invalid or missing expires_in field
    }
}

// Add a new packet to the dynamic array and update the packet count
void addPacket(PacketManager* manager, CellularPacket* packet) {
    if (manager->packetCount >= RESIZE_THRESHOLD && manager->packets[0].phyFrame != NULL) {
        // Resize the dynamic array
        CellularPacket* newPackets = (CellularPacket*)realloc(manager->packets, sizeof(CellularPacket) * MAX_PACKETS * 2);
        memcpy(newPackets, manager->packets, sizeof(CellularPacket) * manager->packetCount);
        free(manager->packets);
        manager->packets = newPackets;
    }
    manager->packets[manager->packetCount] = *packet;
    manager->packetCount++;
}

// Get the current packet count
size_t getPacketCount(PacketManager* manager) {
    return manager->packetCount;
}

// Access an individual packet by index
CellularPacket* getPacket(PacketManager* manager, size_t index) {
    if (index >= manager->packetCount) {
        // Handle error: out-of-range packet index
    }
    return &manager->packets[index];
}

void packetManagerDestroy(PacketManager* manager) {
    free(manager->packets);
    json_object_put(manager->obj);
    free(manager);
}
