void init_logging_framework(LoggingFramework* framework) {
    // Initialize thread-safe lock and buffers
    pthread_mutex_init(&framework->mutex, NULL);
    framework->log_buffer = (LogEntry**)malloc(1000 * sizeof(LogEntry*));
    framework->log_buffer_size = 1000;
    framework->log_buffer_used = 0;
}

// Function to log an entry with variable arguments
void log(LoggingFramework* framework, enum { DEBUG, INFO, WARNING, ERROR } level, const char* message, ...) {
    // Acquire thread-safe lock
    pthread_mutex_lock(&framework->mutex);

    // Create a new log entry with variable arguments
