        // Handle overflow by dropping oldest entries or increasing buffer size
    }

    // Release thread-safe lock
    pthread_mutex_unlock(&framework->mutex);
}

// Function to flush the logging buffer (e.g., send log entries to external services)
void flush(LoggingFramework* framework) {
    // Acquire thread-safe lock
    pthread_mutex_lock(&framework->mutex);

    // Send log entries to current active service
    for (int i = 0; i < framework->log_buffer_used; i++) {
        LogEntry* entry = framework->log_buffer[i];
        // ...
    }

    // Clear the logging buffer
    framework->log_buffer_used = 0;

    // Release thread-safe lock
