    sprintf(new_file_name, "%s-%d-%ld.txt", original_file_name, version, timestamp);
    return new_file_name;
}

// Concurrent renaming and metadata fetching with fallbacks
void* rename_and_fetch_mime_type(void* arg) {
    pthread_arg* thread_arg = (pthread_arg*)arg;
    char* file_path = thread_arg->file_path;
    int version = thread_arg->version;
    time_t timestamp = thread_arg->timestamp;

    // Fetch MIME type with fallback for network timeouts and service downtime
    if (fetch_mime_type(file_path, &thread_arg->mime_type) != 0) {
        // Handle metadata service unavailability or timeouts
        printf("Error fetching MIME type: %s\n", file_path);
        return NULL;
    }

    char* new_file_name = generate_versioned_filename(thread_arg->original_file_name,
                                                       thread_arg->version,
                                                       timestamp);

    if (rename(file_path, new_file_name) != 0) {
        // Handle file renaming failures
        printf("Error renaming file: %s\n", file_path);
        free(new_file_name);
        return NULL;
    }

    pthread_mutex_lock(&file_lock);
    current_version = thread_arg->version + 1;  // Update version for concurrent access management
    pthread_mutex_unlock(&file_lock);

    free(thread_arg);
    return NULL;
}

// Library initialization and configuration
int lib_init(struct config* conf) {
    if (pthread_mutex_init(&file_lock, NULL) != 0) {
        // Handle lock initialization failures
        printf("Error initializing file lock\n");
        return -1;
    }

    return 0;
}

int lib_free() {
    pthread_mutex_destroy(&file_lock);
    return 0;
}
