    struct dirent *ent;
    int file_count = 0;

    // Open the directory
    dir = opendir(directory_path);
    if (dir == NULL) {
        // Handle directory access failure
        printf("Error opening directory: %s\n", strerror(errno));
        return;
    }

    // Iterate through the files in the directory
    while ((ent = readdir(dir)) != NULL) {
        char file_path[MAX_FILENAME_LENGTH];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        // Get the MIME type for the file (if available)
        metadata_cache_t *metadata = get_mime_type(file_path);
        if (metadata == NULL || !metadata->is_valid) {
            // Handle invalid or missing MIME type
            printf("Warning: Unable to retrieve MIME type for file '%s'\n", ent->d_name);
        } else {
            // Generate a unique identifier based on the file name and timestamp
            char *identifier = generate_identifier(ent->d_name, time(NULL));

            // Create the new file name with the version number, timestamp, and hash-based identifier
            char new_file_name[MAX_FILENAME_LENGTH];
            sprintf(new_file_name, "%s_v%d_%d_%x", ent->d_name, file_count++, (int)time(NULL), (unsigned int)hash(identifier));

            // Rename the file
            if (rename(file_path, new_file_name) == -1) {
                // Handle renaming failure
                printf("Error renaming file: %s\n", strerror(errno));
            }
        }
    }

    // Close the directory
    closedir(dir);
}
