using System;
using System.Collections.Generic;
using System.Threading;

namespace DynamicRangeRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly Dictionary<int, (int, int)> _ranges = new();
        private readonly object _lock = new object();
        private readonly SemaphoreSlim _semaphore = new(5);

        public void UpdateRanges(Dictionary<int, (int, int)> ranges)
        {
            lock (_lock)
            {
                foreach (var range in ranges)
                {
                    if (!_ranges.ContainsKey(range.Key))
                    {
                        _ranges.Add(range.Key, range.Value);
                    }
                    else
                    {
                        // optimistic concurrency control: check for conflicts before updating
                        var existingRange = _ranges[range.Key];
                        if (existingRange.Item1 < range.Value.Item1 || existingRange.Item2 > range.Value.Item2)
                        {
                            throw new InvalidOperationException("Conflict detected while updating range");
                        }
                        else
                        {
                            _ranges[range.Key] = range.Value;
                        }
                    }
                }
            }
        }

        public int GetRandomValue(int rangeId, int seed)
        {
            if (!_ranges.ContainsKey(rangeId))
            {
                throw new ArgumentException("Range not found", nameof(rangeId));
            }

            var (min, max) = _ranges[rangeId];
            var randomValue = new Random(seed);
            return randomValue.Next(min, max + 1);
        }
    }
}
