class RandomNumberGenerator {
public:
    using Distribution = std::uniform_real_distribution<double>;

    RandomNumberGenerator(size_t seed, size_t maxThreads) :
        mSeed(seed),
        mMaxThreads(maxThreads),
        mThreadId(0),
        mRandEngines(),
        mLock()
    {}

    double generateRandomDouble(double min, double max) {
        return mRandEngines[mThreadId % mMaxThreads](std::uniform_real_distribution<double>(min, max));
    }

    int generateRandomInt(int min, int max) {
        std::uniform_int_distribution<int> distribution(min, max);
        return distribution(mRandEngines[mThreadId % mMaxThreads]);
    }

    void updateSeed() {
        mSeed++;
    }

private:
    size_t mSeed;
    size_t mMaxThreads;
    size_t mThreadId;
    std::vector<std::mt19937> mRandEngines;
    std::mutex mLock;

    RandomNumberGenerator(const RandomNumberGenerator&) = delete;
    RandomNumberGenerator& operator=(const RandomNumberGenerator&) = delete;
};

