    char* str;
    bool has_suffix;
} ProcessedString;

// Function to append a suffix to a string
ProcessedString appendSuffix(const char* input_str, const char* suffix) {
    int len = strlen(input_str);
    int new_len = len + strlen(suffix);
    char* output_str = (char*)malloc((new_len+1)*sizeof(char));
    strcpy(output_str, input_str);
    strcat(output_str, suffix);
    return (ProcessedString){output_str, true};
}

