// Global linked list head
Node* head = NULL;

// Lock for thread-safe operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to process input string
void process_string(char* str) {
    // Check if string length exceeds threshold
    if (strlen(str) > THRESHOLD) return;

    // Add suffix to the string
    char* result = malloc(strlen(str) + strlen(SUFFIX) + 1);
    strcpy(result, str);
    strcat(result, SUFFIX);

    // Add node to linked list
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = result;
    new_node->next = head;
    pthread_mutex_lock(&lock);
    head = new_node;
    pthread_mutex_unlock(&lock);
}

// Thread function for processing input strings
void* process_strings(void* arg) {
    // Process input strings
    while (1) {
        char* str = ...; // Receive input string from external source
        process_string(str);
