class FileRenamer:
    def __init__(self):
        self.config = {}
        self.metadata_service = None
        self.logger = logging.getLogger(__name__)

    def set_config(self, config: dict):
        self.config = config

    def fetch_mime_type(self, file_path: str) -> str:
        if not self.metadata_service:
            return "unknown"
        try:
            mime_type = self.metadata_service.get_mime_type(file_path)
            return mime_type
        except Exception as e:
            self.logger.error(f"Failed to fetch MIME type for {file_path}: {e}")
            return "unknown"

    def rename_file(self, file_path: str) -> (str, str):
        version = 0
        while True:
            new_name = f"{os.path.splitext(file_path)[0]}_{version}_{int(time.time())}{os.path.splitext(file_path)[1]}"
            if not os.path.exists(new_name):
                break
            version += 1

        try:
            os.rename(file_path, new_name)
            return file_path, new_name
        except Exception as e:
            self.logger.error(f"Failed to rename {file_path} to {new_name}: {e}")
            return None

    def run(self, directory: str):
        with ThreadPoolExecutor() as executor:
            for root, dirs, files in os.walk(directory):
                for file in files:
                    file_path = os.path.join(root, file)
                    if self.config.get("rename_files"):
                        file_path, new_name = self.rename_file(file_path)
                        if new_name:
                            logging.info(f"Renamed {file_path} to {new_name}")

