typedef struct {
    CellularPacket** packets;
    size_t capacity;
    size_t count;
} PacketArray;

// Initialize the packet array with a given initial capacity
void initPacketArray(PacketArray* arr, size_t capacity) {
    arr->packets = (CellularPacket**)malloc(capacity * sizeof(CellularPacket*));
    arr->capacity = capacity;
    arr->count = 0;
}

// Resize the packet array when necessary
void resizePacketArray(PacketArray* arr, size_t newCapacity) {
    CellularPacket** newPackets = (CellularPacket**)realloc(arr->packets, newCapacity * sizeof(CellularPacket*));
    if (!newPackets) {
        printf("Failed to allocate memory for packet array.\n");
        exit(1);
    }
    arr->packets = newPackets;
    arr->capacity = newCapacity;
}

// Add a new packet to the array
void addPacket(PacketArray* arr, CellularPacket* packet) {
    if (arr->count >= arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        resizePacketArray(arr, newCapacity);
    }
    arr->packets[arr->count] = packet;
    arr->count++;
}

// Retrieve a packet from the array
CellularPacket* getPacket(PacketArray* arr, int index) {
    if (index >= arr->count || index < 0) {
        printf("Index out of bounds.\n");
        return NULL;
    }
    return arr->packets[index];
}

