    if (data->numReports >= 100000) {
        data->reports = realloc(data->reports, sizeof(MeasurementReport*) * (data->numReports + 1));
    }

    // Add the report to the array
    data->reports[data->numReports] = report;
    data->numReports++;

    pthread_mutex_unlock(&data->lock);
