// Function to remove a measurement report from the library
void removeReport(LibraryData *data, uint8_t reportId) {
    pthread_mutex_lock(&data->lock);

    for (int i = 0; i < data->numReports; i++) {
        if (data->reports[i]->reportId == reportId) {
            // Shift down the remaining reports
            for (int j = i; j < data->numReports - 1; j++) {
                data->reports[j] = data->reports[j + 1];
            }
            data->numReports--;
            free(data->reports[i]);
            break;
        }
    }

    pthread_mutex_unlock(&data->lock);
}

