    if (arr->size >= arr->capacity) {
        cellular_array_resize(arr, arr->size * 2);
    }
    arr->packets[arr->size++] = packet;
}

// Function to delete a CellularPacket from the array
void cellular_array_delete(CellularArray* arr, int index) {
    // Shift remaining packets after deletion
    for (int i = index; i < arr->size - 1; i++) {
        arr->packets[i] = arr->packets[i + 1];
    }
    arr->size--;
}

// Define the CellularArray structure and related functions
