    public:
        explicit EventProcessor(size_t numThreads) : stopped(false), threads(numThreads) {
            for (size_t i = 0; i < numThreads; ++i) {
                threads.emplace_back([this, i]() {
                    processEvents();
                });
            }
        }

        ~EventProcessor() {
            {
                std::unique_lock<std::mutex> lock(mutex);
                stopped = true;
            }
            cv.notify_one();
            for (auto& t : threads) {
                t.join();
            }
        }

        void processEvents() {
            while (!stopped) {
                std::unique_lock<std::mutex> lock(mutex);
                if (cv.wait_for(lock, std::chrono::milliseconds(1), [this]() { return stopped; }) ==
                    std::cv_status::timeout)
                {
                    // Process events
                    for (const auto& event : events) {
                        processEvent(event);
                    }
                }
            }
