typedef struct {
    int max_retries;
    int min_delay;
    int max_delay;
    LogLevel log_level;
} Config;

void config_init(Config* config, const char* file) {
    json_object* json = json_object_from_file(file);
    if (!json) {
        // handle error
        return;
    }
    config->max_retries = json_object_get_int(json, "max_retries");
    config->min_delay = json_object_get_int(json, "min_delay");
    config->max_delay = json_object_get_int(json, "max_delay");
    config->log_level = (LogLevel)json_object_get_int(json, "log_level");
}

void log_message(LogLevel level, const char* message) {
    // implement logging logic here
    printf("%s: %s\n", log_level_to_string(level), message);
}

char* log_level_to_string(LogLevel level) {
    switch (level) {
        case INFO:
            return "INFO";
        case WARNING:
            return "WARNING";
        case ERROR:
            return "ERROR";
        default:
            return "Unknown";
    }
}

int main() {
    Config config;
    config_init(&config, "logging.json");

    log_message(INFO, "This is an info message");
    log_message(WARNING, "This is a warning message");
    log_message(ERROR, "This is an error message");

    return 0;
}
