using System;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicRangeRandomValueGenerator
{
    public class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly IRandomValueService _randomValueService;
        private readonly IRangeParameterProvider _rangeParameterProvider;
        private readonly ICaching Mechanism _cachingMechanism;

        public RandomValueGenerator(IRandomValueService randomValueService, IRangeParameterProvider rangeParameterProvider, ICachingMechanism cachingMechanism)
        {
            _randomValueService = randomValueService;
            _rangeParameterProvider = rangeParameterProvider;
            _cachingMechanism = cachingMechanism;
        }

        public async Task<decimal> GenerateRandomValueAsync()
        {
            decimal randomValue;

            try
            {
                var rangeParameters = await _rangeParameterProvider.GetRangeParametersAsync();
                if (rangeParameters == null)
                    throw new Exception("Range parameters are not available.");

                // Check for cached value and return it if present.
                if (_cachingMechanism.TryGetValue(out var cachedRandomValue, out var cacheExpiration))
                {
                    if (DateTime.Now < cacheExpiration)
                        return cachedRandomValue;
                }

                // Generate random value within the range.
                decimal minValue = rangeParameters.MinValue;
                decimal maxValue = rangeParameters.MaxValue;

                try
                {
                    randomValue = _randomValueService.GenerateRandomValue(minValue, maxValue);
                }
                catch (Exception ex)
                {
                    // Handle service outages and delays.
                    await Task.Delay(TimeSpan.FromSeconds(5));
                    return GenerateRandomValueAsync();
                }

                // Cache the generated value for future use.
                await _cachingMechanism.SetAndExpireAsync(randomValue, TimeSpan.FromHours(1));

                return randomValue;
            }
            catch (Exception ex)
            {
                // Handle errors and retry with jittered exponential backoff.
                if (!exHandled)
                {
                    await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retryCount++)));
                    return GenerateRandomValueAsync();
                }

                throw;
            }
        }
    }

    public interface IRandomValueGenerator
    {
        Task<decimal> GenerateRandomValueAsync();
    }

    public interface IRangeParameterProvider
    {
        Task<RangeParameters> GetRangeParametersAsync();
    }

    public class RangeParameters
    {
        public decimal MinValue { get; set; }
        public decimal MaxValue { get; set; }
    }

    public interface ICachingMechanism
    {
        Task SetAndExpireAsync(object value, TimeSpan expiration);
        bool TryGetValue(out object value, out DateTime expiration);
    }
}
