#include <mutex>
#include <condition_variable>
#include <chrono>

class RandomNumberGenerator {
public:
    // Constructor
    RandomNumberGenerator();

    // Generate a random integer within the given range
    int generateRandomInt(int min, int max);

    // Generate a random float between 0.0 and 1.0
    float generateRandomFloat();

private:
    std::mutex mutex_;
    std::condition_variable cv_;

    unsigned long long seed_ = 0;
};

RandomNumberGenerator::RandomNumberGenerator() {
    // Initialize the seed using the system time and a random value
    auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
    seed_ += (static_cast<unsigned long long>(std::chrono::steady_clock::now().time_since_epoch().count()) << 1) | (now & 0x01);
}

int RandomNumberGenerator::generateRandomInt(int min, int max) {
    std::unique_lock<std::mutex> lock(mutex_);

    // Calculate the maximum value based on the given range
    auto maxValue = static_cast<unsigned long long>(max);

    // Generate a random integer within the given range using the current seed
    auto randomInt = (seed_ * 1103515245 + 12345) % (maxValue - min + 1) + min;

    lock.unlock();
    return randomInt;
}

float RandomNumberGenerator::generateRandomFloat() {
    // Convert the generated integer to a float value between 0.0 and 1.0
    auto randomFloat = static_cast<float>(seed_ % (1 << 32)) / (static_cast<float>(1) << 32);

    return randomFloat;
}

int main() {
    RandomNumberGenerator rng;

    // Test the RNG with some example values
    std::cout << "Random int: " << rng.generateRandomInt(0, 100) << std::endl;
    std::cout << "Random float: " << rng.generateRandomFloat() << std::endl;

    return 0;
}
