LogData* LoadAndDeserializeBinaryFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL; // Handle error
    }

    LogData* logData;
    int size = sizeof(LogData);
    fread(&logData, size, 1, file);

    fclose(file);
    return logData;
}

int main() {
    const char* filename = "log.bin"; // Binary file to load and deserialize
    LogData* logData = LoadAndDeserializeBinaryFile(filename);

    if (logData != NULL) {
        printf("Log ID: %d\n", logData->id);
        printf("Source: %s\n", logData->source);
        printf("Message: %s\n", logData->message);

        free(logData); // Free allocated memory
    }

    return 0;
}

