    void enqueueFileOperation(const std::string& operation, const std::string& filePath) {
        // Enqueue the file operation request and handle it asynchronously
        operations_.emplace_back(operation, filePath);
    }

private:
    struct Operation {
        std::string operation;
        std::string filePath;
    };

    std::vector<Operation> operations_;
};

class AsyncFileOperator {
public:
    void operate(const std::shared_ptr<FileOperationManager>& manager) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !operations_.empty(); });

            auto operation = operations_.front();
            operations_.pop_front();

            // Perform the file operation asynchronously
            performOperation(operation.operation, operation.filePath);

            lock.unlock();
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    std::vector<Operation> operations_;
