import time
from collections import defaultdict
from logging.config import dictConfigFromDict
from logging import Logger
import json
import requests
import hashlib
import base64

class ConfigService:
    def __init__(self):
        self.config = {}
        self.metadata_service_url = "https://metadata-service.com"
        self.logger = Logger("config-service")

    def set_config(self, config_file_path):
        try:
            with open(config_file_path) as f:
                self.config = json.load(f)
        except FileNotFoundError:
            pass

    def get_mime_type(self, file_name):
        try:
            response = requests.get(f"{self.metadata_service_url}/mime-types/{file_name}")
            if response.status_code == 200:
                return response.json()["mime_type"]
            else:
                return None
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to retrieve MIME type for {file_name}: {e}")

    def modify_config_file(self, file_path, placeholders, values):
        try:
            with open(file_path) as f:
                contents = f.read()

            modified_contents = contents.replace("{" + " ".join(placeholders) + "}", "{" + " ".join([str(value) for value in values]) + "}")

            subprocess.run(["sed", "-i", "s/{" + " ".join(placeholders) + "}/{" + " ".join([str(value) for value in values]) + "}/g", file_path], check=True)

        except FileNotFoundError:
            self.logger.error(f"File not found: {file_path}")
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Failed to modify file: {e}")

    def rename_file(self, original_file_path):
        try:
            original_name = os.path.basename(original_file_path)
            version_number = str(int(time.time()))
            timestamp = time.strftime("%Y%m%d%H%M%S")

            new_name = f"{original_name}-{version_number}-{timestamp}"

            while os.path.exists(new_name):
                version_number = str(int(version_number) + 1)

            new_name = f"{new_name}-{version_number}-{timestamp}"
            os.rename(original_file_path, new_name)

        except FileNotFoundError:
            self.logger.error(f"File not found: {original_file_path}")
        except Exception as e:
            self.logger.error(f"Failed to rename file: {e}")

    def encrypt_password(self, password):
        return base64.b64encode(hashlib.sha256(password.encode()).digest()).decode()

    def set_metadata_service_url(self, url):
        self.metadata_service_url = url

    def get_config(self):
        return self.config

# Example usage
config_service = ConfigService()
config_service.set_config("config.json")
config_service.modify_config_file("example.conf", ["${ Placeholders }"], ["Values"])
config_service.rename_file("/path/to/example.conf")
print(config_service.encrypt_password("password"))
