class CryptoFunction(abc.ABC):
    @abc.abstractmethod
    def encrypt(self, data: bytes) -> bytes:
        pass

    @abc.abstractmethod
    def decrypt(self, data: bytes) -> bytes:
        pass


class HardwareAcceleratedCrypto(CryptoFunction):
    def __init__(self, hardware_accelerator_path: str):
        self.hardware_accelerator_path = hardware_accelerator_path

    def encrypt(self, data: bytes) -> bytes:
        # Use the hardware accelerator to perform encryption
        return os.popen(f"{self.hardware_accelerator_path} -e {data.decode()}", "r").read().encode()

    def decrypt(self, data: bytes) -> bytes:
        # Use the hardware accelerator to perform decryption
        return os.popen(f"{self.hardware_accelerator_path} -d {data.decode()}", "r").read().encode()


class SoftwareBasedCrypto(CryptoFunction):
    def __init__(self, software_crypto_library_path: str):
        self.software_crypto_library_path = software_crypto_library_path

    def encrypt(self, data: bytes) -> bytes:
        # Use the software-based crypto library to perform encryption
        return subprocess.run([f"{self.software_crypto_library_path}", "encrypt", data.decode()], capture_output=True).stdout.encode()

    def decrypt(self, data: bytes) -> bytes:
        # Use the software-based crypto library to perform decryption
        return subprocess.run([f"{self.software_crypto_library_path}", "decrypt", data.decode()], capture_output=True).stdout.encode()


