        SandeshClient client = new SandeshClient(config);

        // Start monitoring network health
        startMonitoring(client);
    }

    private static void startMonitoring(SandeshClient client) {
        // Define a schedule for monitoring requests (e.g., every 5 minutes)
        Duration interval = Duration.ofMinutes(5);
        Instant lastRun = Instant.now();

        while (true) {
            // Check if it's time to send the next request
            if (Instant.now().minus(interval).isAfter(lastRun)) {
                lastRun = Instant.now();
                // Send monitoring requests using sandesh client
                List<MonitoringRequest> requests = new ArrayList<>();
                // Add monitoring requests for different environments (cloud, on-premise, hybrid)
                requests.add(new MonitoringRequest("cloud", "instance-1"));
                requests.add(new MonitoringRequest("on-premise", "server-1"));
                requests.add(new MonitoringRequest("hybrid", "edge-node-1"));

                client.sendMonitoringRequests(requests);
