using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Configuration;
using ThirdPartyTextProcessor;

namespace TextProcessorService
{
    public class TextProcessorService : ITextProcessorService
    {
        private readonly ILogger<TextProcessorService> _logger;
        private readonly IConfiguration _config;
        private readonly int _maxRetries;
        private readonly int _networkRetryTimeout;
        private readonly int _dbConnectionRetryTimeout;

        public TextProcessorService(ILogger<TextProcessorService> logger, IConfiguration config)
        {
            _logger = logger;
            _config = config;
            _maxRetries = int.Parse(config["MaxRetries"]);
            _networkRetryTimeout = int.Parse(config["NetworkRetryTimeout"]);
            _dbConnectionRetryTimeout = int.Parse(config["DbConnectionRetryTimeout"]);
        }

        public async Task ProcessTextAsync(string text)
        {
            if (string.IsNullOrEmpty(text))
                throw new ArgumentNullException(nameof(text));

            await Task.Run(() =>
            {
                try
                {
                    // Process text using third-party library
                    var processedText = ThirdPartyTextProcessor.ProcessText(text);

                    // Append special delimiter when appropriate
                    processedText += "#";

                    // Validate and log output
                    _logger.LogInformation($"Processed text: {processedText}");
                }
                catch (Exception ex)
                {
                    // Handle errors and retries
                    if (IsTransientFailure(ex))
                    {
                        await RetryOperationAsync(ex);
                    }
                    else
                    {
                        _logger.LogError(ex, "Error processing text");
                    }
                }
            });
        }

        private bool IsTransientFailure(Exception ex) =>
            ex is SocketException || ex is HttpRequestException || ex is DbConnectionException;

        private async Task RetryOperationAsync(Exception ex)
        {
            int retries = 0;
            while (retries < _maxRetries)
            {
                try
                {
                    await ProcessTextAsync(ex.Message);
                    return;
                }
                catch (Exception innerEx) when (IsTransientFailure(innerEx))
                {
                    await Task.Delay(_networkRetryTimeout, _dbConnectionRetryTimeout);
                    retries++;
                }
            }

            // Fallback strategy for API calls that fail due to network latency or quota limits
            _logger.LogError(ex, "Maximum retries exceeded");
        }
    }
}
