class TenantAccountManager {
    private $tenants;

    public function __construct() {
        $this->tenants = [];
    }

    public function createTenant($tenantId) {
        if (!isset($this->tenants[$tenantId])) {
            $this->tenants[$tenantId] = new Tenant();
        }
    }

    public function getTenantUsers($tenantId) {
        return $this->tenants[$tenantId]->getUsers();
    }

    public function createUser($tenantId, $username, $email) {
        $this->createTenant($tenantId);
        $this->tenants[$tenantId]->addUser(new User($username, $email));
    }

    public function deleteUser($tenantId, $userId) {
        if (isset($this->tenants[$tenantId])) {
            $this->tenants[$tenantId]->removeUser($userId);
        }
    }
}

