['Here is the Java code for the `NetworkConnectionManager` utility class:

```java
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import javax.net.ssl.SSLContext;
import javax.ws.rs.client.ClientBuilder;
import javax.ws.rs.client.WebTarget;
import javax.ws.rs.core.Response;
import javax.xml.bind.JAXBException;

import org.apache.commons.pool2.impl.GenericObjectPoolConfig;
import org.glassfish.jersey.client.ClientProperties;
import org.glassfish.jersey.client.HttpUrlConnector;
import org.glassfish.jersey.client.spi.Connector;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class NetworkConnectionManager {

    private static final Logger logger = LoggerFactory.getLogger(NetworkConnectionManager.class);
    private static final int MAX_CONCURRENT_REQUESTS = 10;

    private WebTarget client;
    private GenericObjectPoolConfig<HttpUrlConnector> connectorPool;

    public NetworkConnectionManager() {
        client = ClientBuilder.newClient();
        connectorPool = new GenericObjectPoolConfig<>();
        connectorPool.setMaxActive(50);
        connectorPool.setMinIdle(MAX_CONCURRENT_REQUESTS);
    }

    public <T> Future<T> sendAsyncRequest(String url, T body) {
        return client.target(url).request().async().post(Entity.json(body));
    }

    public Response sendRequestSync(String url, Object body) throws Exception {
        try {
            return client.target(url).request().post(Entity.json(body), Response.class);
        } catch (Exception e) {
            handleException(e);
            throw new Exception("Failed to process the request", e);
        }
    }

    private void handleException(Exception e) {
        logger.error("Error processing the request: {}", e.getMessage(), e);
    }

    public void close() {
        connectorPool.close();
    }
}
