function runTests(moduleName, testCases, blueslipMock, externalDataSource, timeout, environmentConfig) {
  const { retries, backoffFactor } = environmentConfig;
  let moduleLoaded = false;

  async function loadModule() {
    for (let i = 0; i < retries; i++) {
      try {
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 500));
        return require(moduleName);
      } catch (err) {
        if (i === retries - 1) throw err;
      }
    }
    throw new Error(`Failed to load module '${moduleName}' after ${retries} attempts`);
  }

  async function executeTestCase(testCase) {
    await resetBlueslipMock();
    const externalData = await getExternalData(testCase, environmentConfig);
    try {
      await testCase(externalData);
    } catch (err) {
      if (!moduleLoaded) await loadModule();
      throw err;
    }
  }

  async function runTestSuite() {
    const concurrencyLimit = environmentConfig.concurrencyLimit || 5;
    let concurrencyCount = 0;
    let errors = [];
    let results = { passed: 0, failed: 0, skipped: 0 };

    await Promise.all(testCases.map((testCase, i) => {
      if (concurrencyCount >= concurrencyLimit) {
        await new Promise(resolve => setTimeout(resolve, 100));
        concurrencyCount = 0;
      }
      try {
        await executeTestCase(testCase);
        results.passed++;
      } catch (err) {
        errors.push(err);
        results.failed++;
      }
    }));

