// API Reliability (Robust Retry Mechanisms and Fallback Strategies)
package com.productreviews.reliability;

import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.web.client.RestTemplate;

public class RobustRetryMechanisms {

    private final int MAX_RETRIES = 3;
    private final int DELAY_BETWEEN_RETries = 1000; // in milliseconds

    public void execute(RestTemplate restTemplate, String url) {
        AtomicInteger retries = new AtomicInteger(0);
        while (retries.getAndIncrement() <= MAX_RETRIES) {
            try {
                restTemplate.getForObject(url, String.class);
                return;
            } catch (Exception e) {
                if (retries.get() < MAX_RETRIES) {
                    try {
                        Thread.sleep(DELAY_BETWEEN_RETries);
                    } catch (InterruptedException ex) {
                        Thread.currentThread().interrupt();
                    }
                } else {
                    // Fallback strategy: Use alternative API or data source
                    restTemplate.getForObject("alternative-api-url", String.class);
                }
            }
        }
    }
}

