package com.productreviews.caching;

import java.util.concurrent.atomic.AtomicInteger;
org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;

@EnableCaching
public class MultiTierCaching {

    private final int MAX_CACHE_TIER = 3;

    @Bean
    public CacheManager cacheManager() {
        return new CustomCacheManager();
    }

    private class CustomCacheManager implements CacheManager {

        @Override
        public void put(String key, Object value) {
            // Distribute cache across multiple tiers and nodes
            for (int i = 0; i < MAX_CACHE_TIER; i++) {
                try {
                    Thread.sleep(1000); // Simulate distributed caching delay
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
                // Store value in the cache tier
                storeInCacheTier(i, key, value);
            }
        }

        @Override
        public void invalidate(String key) {
            // Invalidate cache across multiple tiers and nodes
            for (int i = 0; i < MAX_CACHE_TIER; i++) {
                try {
                    Thread.sleep(1000); // Simulate distributed caching delay
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
                // Remove value from the cache tier
                removeFromCacheTier(i, key);
            }
        }
    }
}

