function renderFooterScripts(scripts) {
  const footerHTML = '<footer>';
  let totalSize = 0;

  scripts.forEach((script) => {
    const scriptHTML = `<script${script.type === 'module' ? ' type="module"' : script.type === 'text/javascript' ? ' type="text/javascript"' : ''}>`;

    if (script.src) {
      fetchScript(script.src)
        .then((response) => response.text())
        .then((content) => {
          scriptHTML += `${content}`;
          totalSize += content.length;
        })
        .catch((error) => {
          console.error('Failed to load script:', error);
          footerHTML += scriptHTML + '</script>';
        });
    } else {
      scriptHTML += ` innerHTML="${script.innerHTML}" defer`;
      totalSize += script.innerHTML.length;
    }

    if (totalSize > 10000) {
      console.warn('Script collection exceeds size limit. Consider deferring some scripts.');
      const deferredScripts = [];
      let remainingSize = totalSize;

      while (remainingSize > 10000) {
        const scriptToDeferral = scripts.shift();
        deferredScripts.push(scriptToDeferral);
        remainingSize -= scriptToDeferral.src ? fetchScript(scriptToDeferral.src).then((response) => response.size) : scriptToDeferral.innerHTML.length;
      }

      if (deferredScripts.length > 0) {
        console.log('Defered scripts:', deferredScripts.map((script) => script.id));
        footerHTML += '<noscript>';
        deferredScripts.forEach((script) =>
          footerHTML += `<script${script.type === 'module' ? ' type="module"' : script.type === 'text/javascript' ? ' type="text/javascript"' : ''} src="${script.src}"></script>`
        );
        footerHTML += '</noscript>';
      }
    } else {
      footerHTML += scriptHTML + '</script>';
    }
  });

  footerHTML += '</footer>';

  return footerHTML;
}

async function fetchScript(src) {
  const response = await fetch(src, {
    cache: 'force-cache',
    headers: { 'Max-Age': '86400' },
  });

  if (!response.ok) {
    console.error('Failed to load script:', src);
    throw new Error(`Failed to load script: ${src}`);
  }

  const cachedResponse = await response.clone();
  cachedResponse.headers.set('Content-Type', 'text/javascript');

  return { text: () => cachedResponse.text(), size: () => cachedResponse.bodyUsed ? cachedResponse.size : null };
}
