// selectAttack function in C++
#include <iostream>
#include <string>
#include <vector>
#include <curl/curl.h>

class AttackDatabase {
public:
  std::vector<std::pair<std::string, int>> fetchAvailableAttacks() {
    CURL *curl;
    CURLcode res;

    std::string readBuffer;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
      curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/attacks");
      curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeMemoryCallback);
      curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
      res = curl_easy_perform(curl);

      std::vector<std::pair<std::string, int>> attacks;
      for (const auto& line : readBuffer) {
        size_t pos = line.find(":");
        if (pos != std::string::npos) {
          attacks.push_back({line.substr(0, pos), std::stoi(line.substr(pos + 1))});
        }
      }

      curl_easy_cleanup(curl);
      curl_global_cleanup();
      return attacks;
    } else {
      return {};
    }
  }

private:
  static size_t writeMemoryCallback(void *ptr, size_t size, size_t nmemb, void *data) {
    std::string &readBuffer = *(std::string *)data;
    readBuffer.assign((char*)ptr, size*nmemb);
    return size*nmemb;
  }
};

int main() {
  AttackDatabase db;
  auto attacks = db.fetchAvailableAttacks();
  for (const auto& attack : attacks) {
    std::cout << "Attack: " << attack.first << ", Cooldown: " << attack.second << "\n";
  }

  return 0;
}

