      user: PG_USER,
      host: PG_HOST,
      port: PG_PORT,
      password: PG_PASSWORD,
      database: 'mydatabase'
    });
    await pool.query(`INSERT INTO mytable (data) VALUES ($1)`, [data]);
  }
}

// Define integration and security
