// Define main pipeline flow
async function main() {
  try {
    const kafkaClient = new Kafka({ brokers: [KAFKA_BROKER] });
    const messageConsumer = await kafkaClient.consumer({
      groupId: 'my-group'
    });

    messageConsumer.on('message', async (message) => {
      try {
        // Process the message
        await processor.processMessage(message.value);
      } catch (err) {
        // Handle errors and retries
