import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.Executors;

public class SecureMicroservice {

    private AsynchronousSocketChannel channel;
    private ExecutorService executor = Executors.newFixedThreadPool(10);

    public void connect(String host, int port) {
        try {
            channel = AsynchronousSocketChannel.open();
            channel.connect(new InetSocketAddress(host, port), new CompletionHandler() {
                @Override
                public void completed(AsynchronousSocketChannel ch, Object attachment) {
                    System.out.println("Connected to " + host + ":" + port);
                }

                @Override
                public void failed(Throwable exc, AsynchronousSocketChannel ch) {
                    System.out.println("Failed to connect to " + host + ":" + port);
                    // Reconnect logic here
                }
            });
        } catch (IOException e) {
            System.out.println("Error connecting: " + e.getMessage());
        }
    }

    public void sendMessage(String message) {
        channel.write(message.getBytes(), new CompletionHandler() {
            @Override
            public void completed(AsynchronousSocketChannel ch, Object attachment) {
                System.out.println("Message sent successfully");
            }

            @Override
            public void failed(Throwable exc, AsynchronousSocketChannel ch) {
                System.out.println("Failed to send message: " + exc.getMessage());
            }
        });
    }

    public void receiveMessage() {
        channel.read(new CompletionHandler() {
            @Override
            public void completed(AsynchronousSocketChannel ch, Object attachment) {
                byte[] data = new byte[attachment.readInt()];
                ch.read(data);
                System.out.println("Received message: " + new String(data));
            }

            @Override
            public void failed(Throwable exc, AsynchronousSocketChannel ch) {
                System.out.println("Failed to receive message: " + exc.getMessage());
            }
        });
    }
}
