class OAuthLoginManager:
    def __init__(self):
        self.oauth_clients = []

    def add_oauth_client(self, client_id, client_secret, redirect_uri):
        oauth_client = OAuth(client_id=client_id, client_secret=client_secret, redirect_uri=redirect_uri)
        self.oauth_clients.append(oauth_client)

    def handle_oauth_request(self, request):
        for client in self.oauth_clients:
            if client.authorize(request):
                return client.get_access_token()

app.config['OAUTH_LOGIN_MANAGER'] = OAuthLoginManager()
OAuthLoginManager = app.config['OAUTH_LOGIN_MANAGER']

