@SpringBootApplication
@RestController
public class FileAggregationService extends FlinkFunctionAdapter {

    private static final String S3_BUCKET = "my-bucket";
    private static final String GCS_BUCKET = "my-gcs-bucket";

    @PostMapping("/aggregate")
    public ResponseEntity<Map<String, Object>> aggregateFiles(@RequestBody Map<String, Object> payload) throws Exception {
        List<String> filePaths = (List<String>) payload.get("filePaths");
        Map<String, Object> result = new HashMap<>();

        for (String filePath : filePaths) {
            String bucket;
            if (filePath.startsWith(S3_BUCKET)) {
                bucket = S3_BUCKET;
            } else if (filePath.startsWith(GCS_BUCKET)) {
                bucket = GCS_BUCKET;
            } else {
                throw new Exception("Unsupported cloud storage provider");
            }

            URI uri = new URI(filePath);
            String key = uri.getPath().substring(1);

            // Download file from cloud storage
            byte[] fileBytes = downloadFile(bucket, key);

            // Add file to ZIP archive
            try (ZipOutputStream zip = new ZipOutputStream(new ByteArrayOutputStream())) {
                zip.putNextEntry(new ZipEntry(key));
                zip.write(fileBytes);
            }
        }

        return ResponseEntity.status(HttpStatus.OK).body(result);
    }

