// Function to encrypt data using AES-256-CBC
int encrypt_data(const unsigned char* plaintext, int len, const unsigned char* key, const unsigned char* iv,
                  unsigned char** ciphertext, int* c_len) {
    // Create an AES context
    AES_CTX* aes_ctx = AES_CTX_new();
    if (!aes_ctx) return 1;

    // Set the encryption parameters
    AES_set_encrypt_key(key, len, &aes_ctx->key);
    AES_set_iv(iv, len, &aes_ctx->iv);

    // Encrypt the data
    int bytes_written = AES_cbc_encrypt(plaintext, *ciphertext, len, aes_ctx, 1);
    if (bytes_written < 0) return 2;

    // Update the ciphertext length
    *c_len = bytes_written;
    return 0;
}

// Function to decrypt data using AES-256-CBC
int decrypt_data(const unsigned char* ciphertext, int c_len, const unsigned char* key, const unsigned char* iv,
                  unsigned char** plaintext, int* p_len) {
    // Create an AES context
    AES_CTX* aes_ctx = AES_CTX_new();
    if (!aes_ctx) return 1;

    // Set the decryption parameters
    AES_set_decrypt_key(key, c_len, &aes_ctx->key);
    AES_set_iv(iv, c_len, &aes_ctx->iv);

    // Decrypt the data
    int bytes_written = AES_cbc_decrypt(ciphertext, *plaintext, c_len, aes_ctx, 1);
    if (bytes_written < 0) return 2;

    // Update the plaintext length
    *p_len = bytes_written;
    return 0;
}

// Function to encrypt data using Camellia-256-CBC
int cam_encrypt_data(const unsigned char* plaintext, int len, const unsigned char* key, const unsigned char* iv,
                      unsigned char** ciphertext, int* c_len) {
    // Create a Camellia context
    CAM_CTX* cam_ctx = CAM_CTX_new();
    if (!cam_ctx) return 1;

    // Set the encryption parameters
    CAM_set_encrypt_key(key, len, &cam_ctx->key);
    CAM_set_iv(iv, len, &cam_ctx->iv);

    // Encrypt the data
    int bytes_written = CAM_cbc_encrypt(plaintext, *ciphertext, len, cam_ctx, 1);
    if (bytes_written < 0) return 2;

    // Update the ciphertext length
    *c_len = bytes_written;
    return 0;
}

// Function to decrypt data using Camellia-256-CBC
int cam_decrypt_data(const unsigned char* ciphertext, int c_len, const unsigned char* key, const unsigned char* iv,
                      unsigned char** plaintext, int* p_len) {
    // Create a Camellia context
    CAM_CTX* cam_ctx = CAM_CTX_new();
    if (!cam_ctx) return 1;

    // Set the decryption parameters
    CAM_set_decrypt_key(key, c_len, &cam_ctx->key);
    CAM_set_iv(iv, c_len, &cam_ctx->iv);

    // Decrypt the data
    int bytes_written = CAM_cbc_decrypt(ciphertext, *plaintext, c_len, cam_ctx, 1);
    if (bytes_written < 0) return 2;

    // Update the plaintext length
    *p_len = bytes_written;
    return 0;
}

// Function to compute a SHA-256 hash
int sha256_hash(const unsigned char* data, int len, unsigned char** hash, int* h_len) {
    // Create a SHA context
    SHA_CTX* sha_ctx = SHA_CTX_new();
    if (!sha_ctx) return 1;

    // Update the SHA context with the data
    SHA_update(sha_ctx, data, len);

    // Get the hash values
    unsigned char hash_val[SHA256_DIGEST_LENGTH];
    int bytes_written = SHA_final(sha_ctx, hash_val);
    if (bytes_written < 0) return 2;

    // Update the hash length and value
    *h_len = bytes_written;
    *hash = hash_val;
    return 0;
}

// Function to compute a MD5 hash
int md5_hash(const unsigned char* data, int len, unsigned char** hash, int* h_len) {
    // Create an MD5 context
    MD5_CTX* md5_ctx = MD5_CTX_new();
    if (!md5_ctx) return 1;

    // Update the MD5 context with the data
    MD5_update(md5_ctx, data, len);

    // Get the hash values
    unsigned char hash_val[MD5_DIGEST_LENGTH];
    int bytes_written = MD5_final(md5_ctx, hash_val);
    if (bytes_written < 0) return 2;

    // Update the hash length and value
    *h_len = bytes_written;
    *hash = hash_val;
    return 0;
}
