package com.example.encryptionService;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.State;
import com.google.common.primitives.Bytes;

public class EncryptionService {

    private final int iterations = 1000;
    private final String algorithm = "PBKDF2WithHmacSHA1";
    private final String saltAlgorithm = "UTF-8";
    private final String ivAlgorithm = "AES/CBC/NoPadding";

    public byte[] encrypt(byte[] data, String password) throws Exception {
        // derive key from password using PBKDF2
        SecretKeySpec keySpec = new SecretKeySpec(getKey(password), "AES");
        IvParameterSpec ivSpec = getIv();

        Cipher cipher = Cipher.getInstance(ivAlgorithm);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

        return Bytes.concat(cipher.doFinal(data), Base64.getUrlEncoder().encodeToString(cipher.getIV()).getBytes(saltAlgorithm));
    }

    public byte[] decrypt(byte[] data, String password) throws Exception {
        // derive key from password using PBKDF2
        SecretKeySpec keySpec = new SecretKeySpec(getKey(password), "AES");
        IvParameterSpec ivSpec = getIv();

        Cipher cipher = Cipher.getInstance(ivAlgorithm);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

        return Bytes.concat(cipher.doFinal(Base64.getUrlDecoder().decodeToString(new String(data).substring(0, data.length - Base64 getUrlEncoder().encodeBound() + 1), saltAlgorithm)), cipher.getIV());
    }

    private byte[] getKey(String password) throws Exception {
        // derive key from password using PBKDF2
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(password.getBytes(saltAlgorithm));
        return md.digest();
    }

    private IvParameterSpec getIv() {
        // generate secure random IV
        byte[] iv = new byte[16];
        java.security.SecureRandom sr = new SecureRandom();
        sr.nextBytes(iv);
        return new IvParameterSpec(iv);
    }
}
