using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Azure.Storage;
using System.Security.Cryptography;
using System.Text;

namespace DistributedService
{
    public class MessageProcessor : IDisposable
    {
        private readonly ILogger _logger;
        private readonly CloudStorageAccount _storageAccount;
        private readonly IKeyManagementService _keyManager;
        private readonly IMessageBroker _messageBroker;
        private readonly Dictionary<string, TripleDES> _keys = new();
        private readonly SemaphoreSlim _messageBufferLock = new(1);
        private readonly Queue<Message> _messageBuffer = new();

        public MessageProcessor(ILogger<MessageProcessor> logger, CloudStorageAccount storageAccount, IKeyManagementService keyManager, IMessageBroker messageBroker)
        {
            _logger = logger;
            _storageAccount = storageAccount;
            _keyManager = keyManager;
            _messageBroker = messageBroker;

            Task.Run(GetKeysAsync);
        }

        private async Task GetKeysAsync()
        {
            while (true)
            {
                try
                {
                    var keysResponse = await _keyManager.GetKeysAsync();
                    foreach (var key in keysResponse.Keys)
                    {
                        _keys.Add(key.Id, new TripleDES(key.Key, key.IV));
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error retrieving keys");
                }

                await Task.Delay(TimeSpan.FromMinutes(10)); // Retriever keys every 10 minutes
            }
        }

        public async Task ProcessMessageAsync(Message message)
        {
            try
            {
                if (_keys.TryGetValue(message.UserId, out var key))
                {
                    byte[] decryptedBytes = DecryptBase64(message.EncryptedData, key.Key, key.IV);
                    Message processedMessage = new Message(message.UserId, Encoding.UTF8.GetString(decryptedBytes));
                    _messageBufferLock.Wait();
                    try
                    {
                        _messageBuffer.Enqueue(processedMessage);
                    }
                    finally
                    {
                        _messageBufferLock.Release();
                    }

                    await ProcessMessageBufferAsync();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing message");
            }
        }

        private async Task ProcessMessageBufferAsync()
        {
            while (true)
            {
                try
                {
                    if (_messageBuffer.Count > 0)
                    {
                        var messages = new List<Message>(_messageBuffer.Take(100)); // Process a batch of messages at a time
                        _messageBufferLock.Wait();
                        try
                        {
                            foreach (var message in messages)
                            {
                                await ProcessMessageAsync(message);
                            }
                        }
                        finally
                        {
                            _messageBufferLock.Release();
                        }

                        await ArchiveMessagesAsync(); // Periodically archive messages older than 7 days
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing message buffer");
                }

                await Task.Delay(TimeSpan.FromMilliseconds(500)); // Process the buffer every 500ms
            }
        }

        private byte[] DecryptBase64(string base64EncodedData, byte[] key, byte[] iv)
        {
            using (var tripleDES = TripleDESCryptoServiceProvider.Create())
            {
                tripleDES.Key = key;
                tripleDES.IV = iv;

                return tripleDES.TransformFinalBlock(Convert.FromBase64String(base64EncodedData), 0, base64EncodedData.Length);
            }
        }

        public void Dispose()
        {
            _keys?.Clear();
            _messageBuffer?.Clear();

            GC.SuppressFinalize(this);
        }
    }
}
