public class UserAuthenticationService
{
    private readonly CosmosDatabase _database;
    private readonly IdentityProvider _identityProvider;
    private readonly HashingAlgorithmFactory _hashingAlgorithmFactory;

    public UserAuthenticationService(CosmosDatabase database, IdentityProvider identityProvider)
    {
        _database = database;
        _identityProvider = identityProvider;
        _hashingAlgorithmFactory = new HashingAlgorithmFactory();
    }

    public async Task AuthenticateUser(string username, string password)
    {
        if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
            throw new ArgumentException("Username and password are required");

        var user = await GetUserFromDatabase(username);
        if (user == null)
            throw new InvalidOperationException("User not found");

        var hashingAlgorithm = _hashingAlgorithmFactory.GetHashingAlgorithm();
        var hashedPassword = hashingAlgorithm.HashPassword(password, user.Salt, user.IterationCount);

        if (!VerifyPassword(hashedPassword, user))
            throw new UnauthorizedAccessException("Invalid password");

        await _identityProvider.VerifyUser(username);
    }

    private async Task<User> GetUserFromDatabase(string username)
    {
        try
        {
            return await _database.Users.GetItemAsync(username);
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new InvalidOperationException("User not found");
        }
    }

    private bool VerifyPassword(byte[] hashedPassword, User user)
    {
        var hashingAlgorithm = _hashingAlgorithmFactory.GetHashingAlgorithm();
        return hashingAlgorithm.VerifyPassword(hashedPassword, user.Hash);
    }
}

