                            throw new Exception("Failed to retrieve data");
                        }
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error occurred while retrieving data");
                        throw;
                    }
                }
            }
            _logger.LogError("Invalid API key provided");
            throw new ArgumentException("Invalid API key", nameof(apiKey));
