// Payment Gateway Service
@RestController
@RequestMapping("/payment")
public class PaymentGatewayService {

  private final Map<String, PaymentGateway> paymentGateways;
  private final RabbitMQConnector rabbitMQConnector;
  private final TransactionDB transactionDB;

  public PaymentGatewayService(Map<String, PaymentGateway> paymentGateways,
                                RabbitMQConnector rabbitMQConnector,
                                TransactionDB transactionDB) {
    this.paymentGateways = paymentGateways;
    this.rabbitMQConnector = rabbitMQConnector;
    this.transactionDB = transactionDB;
  }

  @PostMapping("/process-payment")
  public ResponseEntity<PaymentResult> processPayment(@RequestBody PaymentRequest paymentRequest) {
    // Validate payment details against provided schema
    if (!validatePayment(paymentRequest)) {
      return ResponseEntity.badRequest().build();
    }

    // Check for rate limiting and API call limits
    if (isRateLimited(paymentRequest.getCustomerIp())) {
      return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
    }

    // Create a distributed task to process the payment
    DistributedTask task = rabbitMQConnector.sendTask(PaymentProcessingTask.class, paymentRequest);

    // Return a response indicating that the payment is being processed
    return ResponseEntity.accepted().build();

  }

  @PostMapping("/get-transaction-status")
  public ResponseEntity<TransactionStatus> getTransactionStatus(@RequestBody TransactionId transactionId) {
    // Get the transaction status from the database
    TransactionStatus transactionStatus = transactionDB.getTransactionStatus(transactionId);

    // If the transaction is not found, return a 404 error
    if (transactionStatus == null) {
      return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
    }

    // Return the transaction status
    return ResponseEntity.ok(transactionStatus);
  }
}

