from concurrent.futures import ThreadPoolExecutor, as_completed
from redis import StrictRedis
import json
import logging
import requests

class LogProcessor:
    def __init__(self):
        self.redis_client = StrictRedis(host='localhost', port=6379, db=0)
        self.analytics_service_url = 'https://example-analytics-service.com'
        self.metrics_dashboard_url = 'https://example-metrics-dashboard.com'

    def process_logs(self, logs):
        with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
            futures = []
            for log in logs:
                future = executor.submit(self.process_log, log)
                futures.append(future)

            for future in as_completed(futures):
                future.result()

    def process_log(self, log):
        try:
            parsed_log = json.loads(log)
            if parsed_log['event_type'] == 'ERROR':
                self.redis_client.rpush('error_logs', log)
            else:
                self.redis_client.rpush('info_logs', log)

            # Export summary statistics to analytics service
            stats = {'timestamp': parsed_log['timestamp'], 'user_id': parsed_log['user_id']}
            requests.post(self.analytics_service_url + '/logs', json=stats)

        except Exception as e:
            logging.error(f"Error processing log: {str(e)}")

    def start_processing(self):
        while True:
            try:
                logs = self.redis_client.brpop('logs_queue')
                if logs:
                    self.process_logs(logs[0].decode('utf-8').splitlines())
                else:
                    time.sleep(1)
            except Exception as e:
                logging.error(f"Error processing logs: {str(e)}")

if __name__ == '__main__':
    log_processor = LogProcessor()
    log_processor.start_processing()
