redis_client = StrictRedis(host='localhost', port=6379, db=0)

def log_handler(event):
    if event['event_type'] == 'INFO':
        logging.info(f"Received info-level event: {event}")
    elif event['event_type'] == 'ERROR':
        logging.error(f"Received error-level event: {event}")

@app.route('/log', methods=['POST'])
def process_log():
    data = request.get_json()
    for event in data:
        log_handler(event)
        redis_client.rpush('logs', str(event))
    return jsonify({'status': 'ok'})

@celery_app.task
def export_stats():
    try:
        # Call external analytics service API to export summarized statistics
        response = requests.post('https://analytics.example.com/export', json={'data': redis_client.lrange('logs', 0, -1)})
        if response.status_code == 200:
            print(f"Exported {len(response.json())} statistics to analytics service")
    except Exception as e:
        logging.error(f"Error exporting statistics: {e}")

if __name__ == '__main__':
    app.run(debug=True)
