#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define LOG_LEVELS 5
#define MAX_LOG_SIZE 1024

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    FATAL
} LogLevel;

typedef struct _LogMessage {
    char message[MAX_LOG_SIZE];
    time_t timestamp;
    LogLevel level;
    int requestId;
    int userId;
} LogMessage;

typedef struct _Logger {
    LogMessage* logBuffer;
    int bufferSize;
    int maxBufferSize;
    int logCount;
} Logger;

void initializeLogger(Logger* logger, int maxBufferSize);
void logMessage(Logger* logger, LogMessage* message);
int isValidLogLevel(LogLevel level);
void processLogMessages(Logger* logger);

int main() {
    // Initialize the logger
    Logger logger;
    initializeLogger(&logger, 1024);

    // Generate some log messages
    LogMessage messages[5];
    for (int i = 0; i < 5; i++) {
        time_t timestamp = time(NULL);
        LogLevel level = DEBUG + rand() % LOG_LEVELS;
        int requestId = rand();
        int userId = rand();

        sprintf(messages[i].message, "Log message with request ID %d and user ID %d at %s", requestId, userId, ctime(&timestamp));
        messages[i].timestamp = timestamp;
        messages[i].level = level;
        messages[i].requestId = requestId;
        messages[i].userId = userId;

        // Log the messages
        logMessage(&logger, &messages[i]);
    }

    // Process the log messages
    processLogMessages(&logger);

    return 0;
}

void initializeLogger(Logger* logger, int maxBufferSize) {
    logger->logBuffer = (LogMessage*)malloc(maxBufferSize * sizeof(LogMessage));
    logger->bufferSize = 0;
    logger->maxBufferSize = maxBufferSize;
    logger->logCount = 0;
}

void logMessage(Logger* logger, LogMessage* message) {
    // Check if the buffer is full
    if (logger->bufferSize >= logger->maxBufferSize) {
        // Flush the buffer and reset it
        processLogMessages(logger);
        logger->bufferSize = 0;
    }

    // Add the new log message to the buffer
    strcpy(logger->logBuffer[logger->bufferSize].message, message->message);
    logger->logBuffer[logger->bufferSize].timestamp = message->timestamp;
    logger->logBuffer[logger->bufferSize].level = message->level;
    logger->logBuffer[logger->bufferSize].requestId = message->requestId;
    logger->logBuffer[logger->bufferSize].userId = message->userId;
    logger->bufferSize++;
    logger->logCount++;
}

int isValidLogLevel(LogLevel level) {
    return level >= DEBUG && level <= FATAL;
}

void processLogMessages(Logger* logger) {
    // Process the log messages
    for (int i = 0; i < logger->bufferSize; i++) {
        LogMessage message = logger->logBuffer[i];
        printf("Log level: %d, Request ID: %d, User ID: %d, Timestamp: %s, Message: %s\n", message.level, message.requestId, message.userId, ctime(&message.timestamp), message.message);
    }

    // Reset the buffer
    logger->bufferSize = 0;
}
