using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using MongoDB.Bson;
using MongoDB.Driver;
using Redis.Extensions;

namespace FinancialTransactionProcessor
{
    public class TransactionProcessor
    {
        private readonly ILogger _logger;
        private readonly IRuleEngine _ruleEngine;
        private readonly IFinancialMarketDataFeedClient _marketDataFeedClient;
        private readonly ICachingLayer _cachingLayer;
        private readonly IDatabase _database;

        public TransactionProcessor(ILogger logger, IRuleEngine ruleEngine, 
            IFinancialMarketDataFeedClient marketDataFeedClient, ICachingLayer cachingLayer, IDatabase database)
        {
            _logger = logger;
            _ruleEngine = ruleEngine;
            _marketDataFeedClient = marketDataFeedClient;
            _cachingLayer = cachingLayer;
            _database = database;
        }

        public async Task ProcessTransactionsAsync()
        {
            // Ingest and process real-time transactions
            await ProcessRealTimeTransactions();

            // Process historical CSV archives in batches
            await ProcessBatchedTransactions();
        }

        private async Task ProcessRealTimeTransactions()
        {
            // Subscribe to WebSocket stream for real-time market data
            using var webSocket = _marketDataFeedClient.GetWebSocketStream();
            while (webSocket.Connected)
            {
                var transaction = await webSocket.ReceiveAsync();
                if (transaction != null)
                {
                    // Apply business logic using rule engine
                    _ruleEngine.ApplyRules(transaction);

                    // Cache and store real-time transactions
                    await _cachingLayer.SetTransactionAsync(transaction);
                    await _database.InsertTransactionAsync(transaction);
                }
            }
        }

        private async Task ProcessBatchedTransactions()
        {
            // Read historical CSV archives
            foreach (var file in Directory.GetFiles("path/to/archives"))
            {
                using var stream = File.OpenRead(file);
                var transactions = CsvReader.ReadTransactions(stream);
                foreach (var transaction in transactions)
                {
                    // Apply business logic using rule engine
                    _ruleEngine.ApplyRules(transaction);

                    // Cache and store batched transactions
                    await _cachingLayer.SetTransactionAsync(transaction);
                    await _database.InsertTransactionAsync(transaction);
                }
            }
        }

        private async Task HandleErrorAsync(Exception exception)
        {
            // Log error information
            _logger.LogError(exception, "Error processing transaction");

            // Retry failed transactions
            if (exception is TransactionFailedException)
            {
                await _marketDataFeedClient.RetryTransactionAsync();
            }
        }
    }
}
