    public class RandomValueGenerator
    {
        private readonly RNGCryptoServiceProvider _rng = new RNGCryptoServiceProvider();
        private long _seed;

        public RandomValueGenerator(long seed = 0)
        {
            SetSeed(seed);
        }

        public void SetSeed(long seed)
        {
            _seed = seed;
        }

        // Thread-safe method for generating random integer
        public int GetRandomInt(int min, int max, bool inclusive)
        {
            byte[] buffer = new byte[4];
            _rng.GetBytes(buffer);

            uint randomValue = BitConverter.ToUInt32(buffer, 0);
            if (_seed > 0) randomValue += (uint)_seed;

            int value;
            if (!inclusive)
                value = randomValue % ((max - min + 1) * 2) + max - (int)(randomValue / ((uint.MaxValue - _seed) / ((max - min + 1) * 2)));
            else
                value = randomValue % ((max - min + 1));

            return value;
        }

        // Thread-safe method for generating random float
        public float GetRandomFloat(float min, float max, bool inclusive)
        {
            byte[] buffer = new byte[4];
            _rng.GetBytes(buffer);

            uint randomValue = BitConverter.ToUInt32(buffer, 0);
            if (_seed > 0) randomValue += (uint)_seed;

            float value;
            if (!inclusive)
                value = (float)(((randomValue % ((int)((max - min) * 2e9f))) + max - (min)) / (max - min));
            else
                value = (float)(randomValue % ((int)((max - min) * 1.0f)));

            return value;
        }

        // Thread-safe method for generating random double
        public double GetRandomDouble(double min, double max, bool inclusive)
        {
            byte[] buffer = new byte[8];
            _rng.GetBytes(buffer);

            ulong randomValue = BitConverter.ToUInt64(buffer, 0);
            if (_seed > 0) randomValue += (ulong)_seed;

            double value;
            if (!inclusive)
                value = (double)(((randomValue % ((long)((max - min) * 1.0e12))) + max - (min)) / (max - min));
            else
                value = (double)(randomValue % ((long)((max - min) * 1.0)));

            return value;
        }
    }
}
