#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <json-c/json.h>

// Structure to represent a cellular packet
typedef struct {
    int TransmissionTimingOffset;
    int TimingAdvance;
    void* PHYFrame;
} CellularPacket;

// Function to validate the JSON token and return an error if invalid
int validate_token(const char* json_string) {
    // Parse the JSON string into a JSON object
    json_object* json = json_object_from_string(json_string);

    // Check if the token_type is 'Bearer'
    const char* token_type = json_object_get_string(json, "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        return -1; // Invalid token type
    }

    // Check if expires_in is a positive integer
    int expires_in = json_object_get_int(json, "expires_in");
    if (expires_in <= 0) {
        return -1; // Invalid expires_in value
    }

    // Check for missing or invalid fields
    const char* access_token = json_object_get_string(json, "access_token");
    if (!access_token || strlen(access_token) == 0) {
        return -1; // Missing access token
    }
    const char* refresh_token = json_object_get_string(json, "refresh_token");
    if (refresh_token && strlen(refresh_token) > 0) {
        // Token has a refresh token, validate it too
        json_object* refresh_json = json_object_from_string(refresh_token);
        const char* refresh_token_type = json_object_get_string(refresh_json, "token_type");
        if (strcmp(refresh_token_type, "Bearer") != 0) {
            return -1; // Invalid token type in refresh token
        }
    }

    return 0; // Valid token
}

// Function to initialize a CellularPacket structure from the JSON token response
CellularPacket* init_cellular_packet(const char* json_string) {
    // Parse the JSON string into a JSON object
    json_object* json = json_object_from_string(json_string);

    // Create and initialize the cellular packet structure
    CellularPacket* packet = (CellularPacket*)malloc(sizeof(CellularPacket));
    packet->TransmissionTimingOffset = json_object_get_int(json, "TTO");
    packet->TimingAdvance = json_object_get_int(json, "TA");
    packet->PHYFrame = NULL; // Initialize PHYFrame pointer to NULL

    return packet;
}

// Dynamic array of cellular packets
typedef struct {
    CellularPacket* packets;
    int size;
} PacketArray;

// Function to create and initialize a packet array
PacketArray* init_packet_array(int initial_size) {
    PacketArray* array = (PacketArray*)malloc(sizeof(PacketArray));
    array->packets = (CellularPacket*)calloc(initial_size, sizeof(CellularPacket));
    array->size = initial_size;
    return array;
}

// Function to resize the packet array when the number of packets exceeds a specified threshold
void resize_packet_array(PacketArray* array, int new_size) {
    // Calculate the minimum size needed to accommodate all packets
    int min_size = (array->packets != NULL ? array->size : 0);

    // Allocate memory for the new packet array
    PacketArray* new_array = (PacketArray*)malloc(sizeof(PacketArray));
    new_array->packets = (CellularPacket*)calloc(new_size, sizeof(CellularPacket));

    // Copy packets from old to new array
    int i;
    for (i = 0; i < min_size && i < new_size; i++) {
        new_array->packets[i] = array->packets[i];
    }

    // Free the old packet array and update the reference
    free(array);
    array = new_array;

    // Update the size of the packet array
    array->size = new_size;
}

// Function to retrieve a cellular packet by index from the packet array
CellularPacket* get_cellular_packet(PacketArray* array, int index) {
    if (index >= array->size || index < 0) {
        return NULL; // Packet not found
    }
    return &array->packets[index];
}

// Function to generate a certificate in PEM format from the OAuth request
void generate_certificate(const char* json_string, const char* output_file) {
    // Parse the JSON string into a JSON object
    json_object* json = json_object_from_string(json_string);

    // Fetch the private key and certificate from the specified location
    const char* private_key_file = json_object_get_string(json, "private_key_file");
    const char* certificate_file = json_object_get_string(json, "certificate_file");

    // Read the private key and certificate files into strings
    FILE* private_key_fd = fopen(private_key_file, "r");
    if (!private_key_fd) {
        // Handle error: unable to read private key file
        return;
    }
    char* private_key_str = NULL;
    fseek(private_key_fd, 0, SEEK_END);
    long private_key_size = ftell(private_key_fd);
    rewind(private_key_fd);
    private_key_str = (char*)malloc(private_key_size + 1);
    fread(private_key_str, 1, private_key_size, private_key_fd);
    fclose(private_key_fd);

    FILE* certificate_fd = fopen(certificate_file, "r");
    if (!certificate_fd) {
        // Handle error: unable to read certificate file
        return;
    }
    char* certificate_str = NULL;
    fseek(certificate_fd, 0, SEEK_END);
    long certificate_size = ftell(certificate_fd);
    rewind(certificate_fd);
    certificate_str = (char*)malloc(certificate_size + 1);
    fread(certificate_str, 1, certificate_size, certificate_fd);
    fclose(certificate_fd);

    // Concatenate the private key and certificate into a single PEM file
    FILE* pem_fd = fopen(output_file, "w");
    if (!pem_fd) {
        // Handle error: unable to write PEM file
        return;
    }
    fprintf(pem_fd, "%s\n", private_key_str);
    fprintf(pem_fd, "%s", certificate_str);
    fclose(pem_fd);

    free(private_key_str);
    free(certificate_str);
}
