} OAuth2TokenResponse;

void validateOAuthToken(OAuth2TokenResponse *token) {
    if (strlen(token->access_token) == 0 || strlen(token->token_type) == 0) {
        printf("Error: Missing access_token or token_type\n");
        exit(1);
    }
    if (token->expires_in <= 0) {
        printf("Error: expires_in is not a positive integer\n");
        exit(1);
    }
}

void* CellularPacket_New(char *json_string) {
    json_object *jobj = json_object_from_json((const char*)json_string);
    if (!jobj) return NULL;

    OAuth2TokenResponse token;
    strcpy(token.access_token, json_object_get_string(json_object_object_get(jobj, "access_token")));
    token.expires_in = json_object_get_int(json_object_object_get(jobj, "expires_in"));
    strcpy(token.token_type, json_object_get_string(json_object_object_get(jobj, "token_type")));
    if (json_object_object_get(jobj, "refresh_token")) {
        strcpy(token.refresh_token, json_object_get_string(json_object_object_get(jobj, "refresh_token")));
    }

    validateOAuthToken(&token);

    CellularPacket *packet = malloc(sizeof(CellularPacket));
    packet->TTO = 0;
    packet->TimingAdvance = 1;
    packet->PHYFrame = NULL; // Initialize PHYFrame pointer

    json_object_put(jobj); // Free the JSON object
    return (void*)packet;
}

int main() {
