void cellular_packet_array_destroy(CellularPacketArray* array) {
    if (!array) return;
    free(array->packets);
    json_object_free(array->json);
    free(array);
}

int cellular_packet_array_validate_token(json_object* json, CellularPacketArray* array) {
    if (json == NULL || !json_object_is_type(json, json_type_object)) return -1;
    if (!json_object_object_get_ex(json, "token_type", &json)) return -2;
    const char* token_type = json_object_get_string(json);
    if (strcmp(token_type, "Bearer") != 0) return -3;
    if (!json_object_object_get_ex(json, "expires_in", &json)) return -4;
    int expires_in = json_object_get_int(json);
    if (expires_in <= 0) return -5;
    return 0;
}

