// Define the structure for a graph node
typedef struct {
    int id;
    char *name;
    struct {
        int source;
        int target;
    } edges[10];
} GraphNode;

// Function to create a new graph node
GraphNode* create_node(int id, char *name) {
    GraphNode *node = (GraphNode*) malloc(sizeof(GraphNode));
    node->id = id;
    node->name = name;
    return node;
}

// Function to add an edge between two nodes
void add_edge(GraphNode *from, int target_id) {
    from->edges[from->id % 10].target = target_id;
}

// Function to print the graph
void print_graph(GraphNode *node) {
    printf("Graph Node: %d - %s\n", node->id, node->name);
    for (int i = 0; i < node->id % 10; i++) {
        printf("Edge %d -> %d\n", node->edges[i].source, node->edges[i].target);
    }
}

// Function to create a new graph
GraphNode* create_graph() {
    srand(time(NULL));
    GraphNode *node = (GraphNode*) malloc(sizeof(GraphNode));
    for (int i = 0; i < 10; i++) {
        int id = rand() % 100;
        char name[20];
        sprintf(name, "Node %d", id);
        node->id = id;
        node->name = name;
        add_edge(node, rand() % 100);
    }
    return node;
}

int main() {
    // Create a new graph
    GraphNode *graph = create_graph();

    // Print the graph
    print_graph(graph);

    // Free the memory allocated for the graph nodes
    free(graph);

    return 0;
}
