#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <hash.h>

// Function to dynamically rename files in a directory
char* dynamic_rename_file(const char* file_name, int size_limit) {
    // Generate version number and timestamp
    time_t current_time = time(NULL);
    struct tm* time_info = localtime(&current_time);
    char* version_number = malloc(20);
    strftime(version_number, 20, "%Y%m%d%H%M%S", time_info);

    // Generate hash-based identifier
    unsigned long int file_hash = crc32(file_name);
    char* hash_identifier = malloc(10);
    sprintf(hash_identifier, "%lu", file_hash);

    // Append version number and timestamp to file name
    char* new_file_name = malloc(size_limit + strlen(version_number) + strlen(hash_identifier) + 1);
    if (new_file_name == NULL || version_number == NULL || hash_identifier == NULL) {
        free(new_file_name);
        free(version_number);
        free(hash_identifier);
        return NULL;
    }
    sprintf(new_file_name, "%s-%s/%s", file_name, version_number, hash_identifier);

    // Free allocated memory
    free(version_number);
    free(hash_identifier);

    return new_file_name;
}
