    int TimingAdvance;
    void* PHYFrame;  // pointer to JSON string
} CellularPacket;

// Define structure for DynamicRangeRandomValueGenerator
typedef struct {
    int size;  // current array size
    CellularPacket** packets;  // dynamic array of packets
    pthread_mutex_t mutex;  // lock for thread-safe access
} DynamicRangeRandomValueGenerator;

// Function to initialize the library
DynamicRangeRandomValueGenerator* init_DynamicRangeRandomValueGenerator(int initial_size) {
    DynamicRangeRandomValueGenerator* generator = malloc(sizeof(DynamicRangeRandomValueGenerator));
    generator->size = initial_size;
    generator->packets = malloc(generator->size * sizeof(CellularPacket*));
    for (int i = 0; i < generator->size; i++) {
        generator->packets[i] = NULL;
    }
    pthread_mutex_init(&generator->mutex, NULL);
    return generator;
}

// Function to add a packet to the dynamic array
void add_packet(DynamicRangeRandomValueGenerator* generator, CellularPacket* packet) {
    pthread_mutex_lock(&generator->mutex);
    // Check if the array needs resizing
    if (generator->size == 0 || generator->packets[generator->size - 1] != NULL) {
        resize_array(generator);
    }
    generator->packets[generator->size++] = packet;
    pthread_mutex_unlock(&generator->mutex);
}

// Function to remove a packet from the dynamic array
void remove_packet(DynamicRangeRandomValueGenerator* generator, int index) {
    pthread_mutex_lock(&generator->mutex);
    // Check if the index is within bounds
    if (index >= 0 && index < generator->size) {
        for (int i = index; i < generator->size - 1; i++) {
            generator->packets[i] = generator->packets[i + 1];
        }
        free(generator->packets[generator->size]);
        generator->size--;
    }
    pthread_mutex_unlock(&generator->mutex);
}

// Function to resize the dynamic array
void resize_array(DynamicRangeRandomValueGenerator* generator) {
    int new_size = generator->size * 2;
    CellularPacket** new_packets = realloc(generator->packets, new_size * sizeof(CellularPacket*));
    for (int i = generator->size; i < new_size; i++) {
        new_packets[i] = NULL;
    }
    generator->packets = new_packets;
    generator->size = new_size;
}

