// Function to initialize the array
void init_array() {
    pthread_mutex_init(&lock, NULL);
    memset(array, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * NMAX);
}

// Function to add a new structure to the array
void add_structure(NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&lock);
    // Check for available space in the array
    if (array[0] == NULL || array[1] == NULL) {
        // If no space is available, allocate a new block of memory
        NFAPI_CRC_INDICATION_PDU_T *new_block = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);
        if (array[0] != NULL)
            memcpy(new_block, array[0], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (int i = 1; i < NMAX && i <= 9; i++) {
            new_block[i] = array[i];
        }
        free(array[0]);
        array[0] = new_block;
    }
    // Add the new structure to the end of the array
    for (int i = 0; i < NMAX; i++) {
        if (array[i] == NULL) {
            array[i] = new_struct;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Function to remove a structure from the array
void remove_structure(int index) {
    pthread_mutex_lock(&lock);
    // Check if the index is within valid bounds
    if (index >= 0 && index < NMAX) {
        // Shift all structures after the one being removed up by one position
        for (int i = index; i < NMAX - 1; i++) {
            array[i] = array[i + 1];
        }
        // Set the last element to NULL to mark it as removed
        array[NMAX - 1] = NULL;
    }
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a structure from the array
NFAPI_CRC_INDICATION_PDU_T *get_structure(int index) {
    pthread_mutex_lock(&lock);
    // Check if the index is within valid bounds
    if (index >= 0 && index < NMAX) {
        return array[index];
    }
    pthread_mutex_unlock(&lock);
