```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

class Transaction {
public:
    std::string sender;
    std::string recipient;
    double amount;
    int timestamp;
    int priority;
    std::map<std::string, std::any> metadata;

    Transaction(std::string sender, std::string recipient, double amount, int timestamp, int priority, std::map<std::string, std::any> metadata)
        : sender(sender), recipient(recipient), amount(amount), timestamp(timestamp), priority(priority), metadata(metadata) {}
};

class LedgerEngine {
public:
    using Queue = std::priority_queue<Transaction*, std::vector<Transaction*>, decltype([](const Transaction* a, const Transaction* b) { return a->priority > b->priority; })>;

    void addTransaction(Transaction* transaction);
    void processTransactions();
    int getTransactionCount();

private:
    std::mutex mtx;
    std::condition_variable cv;
