        arr->capacity *= 2;
        arr->pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->pdus, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    arr->pdus[arr->size++] = pdu;
}

