#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <atomic>
#include <memory>

class AudioFrame {
public:
    int id;
    std::string data;
};

class NetworkPacket {
public:
    int id;
    std::string data;
};

class PacketManager {
public:
    using Ptr = std::shared_ptr<NetworkPacket>;
    using Vec = std::vector<Ptr>;

    static const size_t MAX_PACKETS = 1000;

    PacketManager() : packets_(Vec(MAX_PACKETS)), concurrentAccess_(false) {}

    void addPacket(Ptr packet) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (packets_.size() >= MAX_PACKETS) {
                // Handle full buffer
                return;
            }
        }

        {
            std::unique_lock<std::mutex> lock(mutex_);
            packets_.push_back(packet);
            cv_.notify_one(); // Notify waiting threads
        }
    }

    void processPackets() {
        while (true) {
            Ptr packet = getPacket();
            if (!packet) break;

            processPacket(*packet);

            {
                std::lock_guard<std::mutex> lock(mutex_);
                packets_.erase(packets_.begin());
            }
        }
    }

private:
    Vec packets_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool concurrentAccess_;

    Ptr getPacket() {
        while (true) {
            // Wait for new packet
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !packets_.empty(); });
            }

            if (!concurrentAccess_) {
                concurrentAccess_ = true;
                break; // Take packet while holding the lock
            }
        }

        Ptr packet = packets_.front();
        packets_.pop_front();
        return packet;
    }

    void processPacket(NetworkPacket& packet) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
};

class AudioManager {
public:
    using Ptr = std::shared_ptr<AudioFrame>;
    using Vec = std::vector<Ptr>;

    static const size_t MAX_FRAMES = 5000;

    AudioManager() : frames_(Vec(MAX_FRAMES)), concurrentAccess_(false) {}

    void addFrame(Ptr frame) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (frames_.size() >= MAX_FRAMES) {
                // Handle full buffer
                return;
            }
        }

        {
            std::unique_lock<std::mutex> lock(mutex_);
            frames_.push_back(frame);
            cv_.notify_one(); // Notify waiting threads
        }
    }

    void processFrames() {
        while (true) {
            Ptr frame = getFrame();
            if (!frame) break;

            processFrame(*frame);

            {
                std::lock_guard<std::mutex> lock(mutex_);
                frames_.erase(frames_.begin());
            }
        }
    }

private:
    Vec frames_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool concurrentAccess_;

    Ptr getFrame() {
        while (true) {
            // Wait for new frame
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !frames_.empty(); });
            }

            if (!concurrentAccess_) {
                concurrentAccess_ = true;
                break; // Take frame while holding the lock
            }
        }

        Ptr frame = frames_.front();
        frames_.pop_front();
        return frame;
    }

    void processFrame(AudioFrame& frame) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
};

class Manager {
public:
    PacketManager packetManager_;
    AudioManager audioManager_;

    Manager() {
        std::thread packetThread([this] { packetManager_.processPackets(); });
        std::thread audioThread([this] { audioManager_.processFrames(); });

        packetThread.detach();
        audioThread.detach();
    }
};

int main() {
    Manager manager;
    return 0;
}
