    json_object_object_update(config->device_config, "frequency", json_integer_value(json_object_get(json, "frequency")));
    json_object_object_update(config->device_config, "bandwidth", json_integer_value(json_object_get(json, "bandwidth")));

    // Save updated JSON data to file
    json_object_to_file(filename, config->device_config);
