    void setEncryptionKey(const std::string& key) { encryptionKey_ = key; }

    template<typename... Args>
    void log(LogLevel level, const char* messageFormat, Args... args) {
        std::stringstream ss;
        ss << messageFormat << " " << std::boolalpha;
        (std::apply([&](auto&&... a) {
            ((ss << ... << a), void());
        })(args...) << " ";
        std::string logMessage = ss.str();
        compressAndEncrypt(logMessage, level);
    }

private:
    void compressAndEncrypt(const std::string& message, LogLevel level) {
        if (compressionLevel_ > 0.5f) {
            // Implement compression algorithm
            message.resize(message.size() * 2); // Compressed size is approximately twice the original size
        }
        if (encryptionKey_.size() > 0) {
            // Implement encryption algorithm
            message = encrypt(message, encryptionKey_);
        }
    }

    std::string encrypt(const std::string& message, const std::string& key) {
        // Implement encryption algorithm using the provided key
        return message;
    }

    void writeLog(const std::string& logMessage, LogLevel level) {
        // Open and write to log file based on log level
        std::ofstream logFile(logPath_.c_str(), std::ios_base::app);
        if (logFile.is_open()) {
            switch (level) {
                case DEBUG:
                    logFile << "[DEBUG] " << logMessage << "\n";
                    break;
                case INFO:
