            LOG.error("Error reading state file", e);
            return null;
        }
    }

    private boolean isValidAccessToken(String accessToken) throws Exception {
        String[] parts = accessToken.split("\\.");
        if (!parts[0].equals("Bearer") || !isPositiveInteger(parts[1])) {
            throw new OAuthTokenValidationException("Invalid token type or expires_in");
        }
        // Additional validation logic here
    }

    private boolean isPositiveInteger(String s) {
        try {
            int i = Integer.parseInt(s);
            return i > 0;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public static class OAuthTokenValidationException extends Exception {
        public OAuthTokenValidationException(String message) {
            super(message);
        }
    }
}
