// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_ARRAY_T;

// Function to create a new dynamic array
NFAPI_CRC_INDICATION_ARRAY_T*
nfaapi_crc_indication_array_create(int initial_capacity) {
    NFAPI_CRC_INDICATION_ARRAY_T* arr = (NFAPI_CRC_INDICATION_ARRAY_T*)malloc(sizeof(NFAPI_CRC_INDICATION_ARRAY_T));
    arr->size = 0;
    arr->capacity = initial_capacity;
    arr->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Function to add a new pdu to the dynamic array
int
nfaapi_crc_indication_array_add(NFAPI_CRC_INDICATION_ARRAY_T* arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (arr->size == arr->capacity) {
        // Dynamically resize the array if full
        int new_capacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_pdus, arr->pdus, arr->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(arr->pdus);
        arr->pdus = new_pdus;
        arr->capacity = new_capacity;
    }
    pthread_mutex_lock(&arr->lock);
    arr->pdus[arr->size] = pdu;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Function to get the size of the dynamic array
int
nfaapi_crc_indication_array_get_size(NFAPI_CRC_INDICATION_ARRAY_T* arr) {
    int size;
    pthread_mutex_lock(&arr->lock);
    size = arr->size;
    pthread_mutex_unlock(&arr->lock);
    return size;
}

// Function to get the pdu at a specific index
NFAPI_CRC_INDICATION_PDU_T*
nfaapi_crc_indication_array_get_pdu(NFAPI_CRC_INDICATION_ARRAY_T* arr, int index) {
    if (index < 0 || index >= arr->size) {
        return NULL;
    }
    pthread_mutex_lock(&arr->lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = &arr->pdus[index];
    pthread_mutex_unlock(&arr->lock);
    return pdu;
}

// Function to free the dynamic array
void
nfaapi_crc_indication_array_free(NFAPI_CRC_INDICATION_ARRAY_T* arr) {
    if (arr != NULL) {
        free(arr->pdus);
        free(arr);
    }
}

// Example usage:
int main() {
    NFAPI_CRC_INDICATION_ARRAY_T* arr = nfaapi_crc_indication_array_create(10);

    // Add some pdus to the array
    for (int i = 0; i < 5; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize pdu structure...
        nfaapi_crc_indication_array_add(arr, pdu);
    }

    // Get the size of the array
    int size = nfaapi_crc_indication_array_get_size(arr);
    printf("Array size: %d\n", size);

    // Get a pdu from the array
    NFAPI_CRC_INDICATION_PDU_T* pdu = nfaapi_crc_indication_array_get_pdu(arr, 2);
    if (pdu != NULL) {
        printf("PDU at index 2: %x %x %x\n", pdu->rx_ue_info, pdu->rnti, pdu->crc_ind_rel8_tag);
    } else {
        printf("Invalid index\n");
    }

    // Free the array
    nfaapi_crc_indication_array_free(arr);

    return 0;
}
