// Custom allocator to optimize memory usage and ensure thread safety
void* custom_malloc(size_t size) {
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Linked list structure with custom allocator
typedef struct _node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)custom_malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void free_list(Node* head) {
    while (head != NULL) {
        Node* next = head->next;
        custom_free(head);
        head = next;
    }
}

// Serialization mechanism to store the linked list in a binary format
void serialize_list(Node* head, FILE* file) {
    fwrite(&head, sizeof(Node), 1, file);
    while (head != NULL) {
        fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        head = head->next;
    }
}

// Deserialization mechanism to restore the linked list from a binary format
Node* deserialize_list(FILE* file) {
    Node* head = NULL;
    while (fread(&head, sizeof(Node), 1, file) == 1) {
        Node* node = create_node(head->data);
        node->next = head;
        head = node;
    }
