    private final ExecutorService executor = Executors.newFixedThreadPool(100);
    private final DistributedCache<String, String> cache = new HazelcastInstance().getMap("transactions");
    private final MemoryPoolAllocator memoryAllocator = new ConcurrentMemoryPool();
    private final CircuitBreaker circuitBreaker = new FallbackCircuitBreaker();

    public void processTransaction(Transaction transaction) {
        try {
            String result = cache.get(transaction.getTransactionId());
            if (result == null || !result.equals("success")) {
                // Send request to payment gateway
                Response response = sendRequestToPaymentGateway(transaction);
                if (response.getStatusCode() == 200) {
                    cache.put(transaction.getTransactionId(), "success");
                    memoryAllocator.memoryWrite(new TransactionRecord(transaction, response));
                } else {
                    circuitBreaker.open();
                    try {
                        // Retry with exponential backoff
                        int retryCount = 0;
                        while (!circuitBreaker.isOpen() && retryCount < 5) {
                            response = sendRequestToPaymentGateway(transaction);
                            if (response.getStatusCode() == 200) {
                                cache.put(transaction.getTransactionId(), "success");
                                memoryAllocator.memoryWrite(new TransactionRecord(transaction, response));
                                break;
                            }
                            retryCount++;
                            Thread.sleep((int) Math.pow(2, retryCount - 1) * 1000);
                        }
                    } catch (InterruptedException e) {
                        // Handle interrupted exception
                    }
                }
            }
        } catch (Exception e) {
            logError(e);
        } finally {
            executor.shutdown();
