// Metadata service client library
#include "metadata_service_client.h"

// Configuration struct
typedef struct {
    int max_file_name_length;
    char* notification_method;
} config_t;

// Function to rename files with version number and timestamp
int rename_files(const char* directory_path, const char* metadata_service_url, config_t* config) {
    DIR* dir = opendir(directory_path);
    if (!dir) {
        // Directory access failure
        return -1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir))) {
        char file_path[256];
        sprintf(file_path, "%s/%s", directory_path, entry->d_name);

        // Fetch metadata and checksum for the file
        metadata_service_client_t client;
        metadata_service_client_init(&client, metadata_service_url);
        int checksum = metadata_service_client_get_checksum(&client, file_path);
        if (checksum < 0) {
            // Metadata service unavailable
            return -1;
        }

        // Validate checksum and skip renaming if invalid
        FILE* file = fopen(file_path, "rb");
        fseek(file, 0, SEEK_END);
        long file_size = ftell(file);
        rewind(file);
        unsigned char buffer[file_size];
        fread(buffer, sizeof(unsigned char), file_size, file);
        fclose(file);
        int calculated_checksum = calculate_checksum(buffer, file_size);
        if (checksum != calculated_checksum) {
            // Checksum mismatch
            return -1;
        }

        // Renaming strategy: append version number and timestamp to filename
        time_t now = time(NULL);
        char new_file_name[256];
        sprintf(new_file_name, "%s_v%d_%ld", entry->d_name, config->max_file_name_length / 4, (long)now);

        // Perform renaming operation
        int ret = rename(file_path, new_file_name);
        if (ret < 0) {
            // Renaming failed
            return -1;
        }

        // Log renaming success or failure
        FILE* log_file = fopen("rename_log.txt", "a");
        fprintf(log_file, "%s renamed to %s\n", entry->d_name, new_file_name);
        fclose(log_file);

        metadata_service_client_close(&client);
    }
    closedir(dir);
}

int main() {
    config_t config;
    config.max_file_name_length = 128;
    config.notification_method = "email";

    rename_files("/path/to/directory", "https://metadata-service.com/api", &config);

    return 0;
}
