// Function to allocate a memory buffer with adjustable size
MemoryBuffer* alloc_memory(size_t size) {
    MemoryBuffer* buffer = (MemoryBuffer*)malloc(sizeof(MemoryBuffer));
    buffer->ptr = malloc(size);
    buffer->size = size;
    return buffer;
}

// Function to free allocated memory buffers
void free_memory(MemoryBuffer* buffer) {
    if(buffer != NULL) {
        free(buffer->ptr);
        free(buffer);
    }
}

// Thread function for processing file segments concurrently
void* process_segment(void* arg) {
    // Get the segment and configuration from the argument
