    }

    // Wait for all threads to finish before exiting
    for (int i = 0; i < num_processes; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    return 0;
}

// Define a struct for storing segment configuration options
struct SegmentConfig {
    int start_offset;
    size_t buffer_size;
};
```

