    NFCCRCService(const std::string& logConfig, const int concurrentRequests) 
        : logger_(logConfig), crcGenerator_(), concurrentRequests_(concurrentRequests), 
          pdusGenerated_(0), pdusFailed_(0) {}

    void generatePDU() {
        // Generate RX UE information tags
        std::string rnti = getRandomRNTI();
        // Generate CRC indication (randomly)
        bool crcFlag = crcGenerator_();
        // Create PDU and add it to the queue
