        pdus_.push(pdu);

        if (pdusGenerated_++ % 100 == 0) {
            logger_.log("Generated PDU " + std::to_string(pdusGenerated_));
        }
    }

    void handlePDU() {
        // Dequeue a PDU and process it
        NFCCRCIndication pdu = pdus_.front();
        pdus_.pop();

        if (!pdu.isValid()) {
            ++pdusFailed_;
            logger_.log("Failed to process PDU " + std::to_string(pdusGenerated_));
