  async executeFilter(filter, image) {
    try {
      const executionContext = await this.threadPool.acquire();
      if (executionContext.gpuAvailable) {
        // GPU-accelerated filtering
        return await filter.executeGPU(image);
      } else {
        // CPU-based filtering
