from PIL import Image
from functools import lru_cache
from typing import List
from queue import PriorityQueue
from threading import Lock, Condition
from time import sleep
from requests.exceptions import RequestException
from abc import ABC, abstractmethod

class Transformation(ABC):
    @abstractmethod
    def apply(self, image: io.BytesIO) -> io.BytesIO:
        pass

class Resizer(Transformation):
    def __init__(self, width: int, height: int):
        self.width = width
        self.height = height

    def apply(self, image: io.BytesIO) -> io.BytesIO:
        img = Image.open(image)
        img.thumbnail((self.width, self.height))
        return io.BytesIO(img.tobytes())

class Cropper(Transformation):
    def __init__(self, x: int, y: int, width: int, height: int):
        self.x = x
        self.y = y
        self.width = width
        self.height = height

    def apply(self, image: io.BytesIO) -> io.BytesIO:
        img = Image.open(image)
        return io.BytesIO(img.crop((self.x, self.y, self.x + self.width, self.y + self.height)).tobytes())

class QualityAdjuster(Transformation):
    def __init__(self, quality: int):
        self.quality = quality

    def apply(self, image: io.BytesIO) -> io.BytesIO:
        img = Image.open(image)
        return io.BytesIO(img.convert('RGB').convert('P', palette=Image.ADAPTIVE, colors=self.quality).tobytes())

