// Custom Memory Allocator Code
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    void* ptr;
    size_t size;
} memory_block;

memory_block* blocks = NULL;
int block_count = 0;

void* alloc(size_t size) {
    memory_block* new_block = (memory_block*)malloc(sizeof(memory_block));
    new_block->ptr = malloc(size);
    new_block->size = size;
    if (!new_block->ptr || !new_block->size) {
        free(new_block);
        return NULL;
    }
    blocks = realloc(blocks, (block_count + 1) * sizeof(memory_block));
    blocks[block_count] = *new_block;
    block_count++;
    return new_block->ptr;
}

void dealloc(void* ptr) {
    for (int i = 0; i < block_count; i++) {
        if (blocks[i].ptr == ptr) {
            free(ptr);
            blocks[i].ptr = NULL;
            blocks[i].size = 0;
            return;
        }
    }
}

