using System;
using System.Threading.Tasks;
using Serilog;
using Apache.Kafka;
using AWS.Kinesis;
using Microsoft.Extensions.Logging;

namespace IoTDataSimulator
{
    public class Simulator
    {
        private readonly ILogger _logger;
        private readonly long _seed;
        private Random _random = new Random();

        public Simulator(long seed = 1)
        {
            _seed = seed;
            _logger = Log.Logger;
        }

        public void SetSeed(long seed)
        {
            _seed = seed;
            _random = new Random(seed);
        }
    }

    public class DataGenerator
    {
        private readonly Simulator _simulator;

        public DataGenerator(Simulator simulator)
        {
            _simulator = simulator;
        }

        public async Task<Stream> GenerateData(int deviceId, int samplingRate)
        {
            // Generate synthetic data for the device
            var stream = new Stream();
            await foreach (var data in GenerateDataInternal(deviceId, samplingRate))
            {
                stream.Add(data);
            }
            return stream;
        }

        private async IAsyncEnumerable<DeviceData> GenerateDataInternal(int deviceId, int samplingRate)
        {
            // Simulate sensor readings
            for (int i = 0; i < 10000; i++)
            {
                var data = new DeviceData { Id = deviceId, Reading = _simulator._random.NextDouble() };
                yield return data;
                await Task.Delay(TimeSpan.FromMilliseconds(samplingRate));
            }
        }
    }

    public class Stream
    {
        private readonly List<DeviceData> _data = new List<DeviceData>();

        public void Add(DeviceData data)
        {
            _data.Add(data);
        }

        public IEnumerable<DeviceData> GetStream()
        {
            return _data;
        }
    }

    public class DeviceData
    {
        public int Id { get; set; }
        public double Reading { get; set; }
    }
}
