```java
import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.google.common.util.concurrent.UncheckedExecutionException;

import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DistributedCache {
    private static final Logger logger = Logger.getLogger(DistributedCache.class.getName());
    private Cache<String, String> cache;

    public DistributedCache() {
        cache = CacheBuilder.newBuilder()
                .concurrencyLevel(16) // adjust to your needs
                .initialCapacity(1000)
                .maximumSize(10000)
                .expireAfterAccess(10, TimeUnit.MINUTES)
                .removalListener((key, value) -> logger.log(Level.FINE, "Removed: {0} = {1}", key, value))
                .build();
    }

    public void put(String key, String value) {
        try {
            cache.put(key, value);
        } catch (ExecutionException e) {
            logger.log(Level.SEVERE, "Error putting key-value pair", e);
        }
    }

    public String get(String key) {
        try {
            return cache.getIfPresent(key).orElseThrow(() -> new NullPointerException("Key not found"));
        } catch (UncheckedExecutionException e) {
            logger.log(Level.SEVERE, "Error getting value for key", e);
            return null;
        }
    }

    public void remove(String key) {
        try {
            cache.invalidate(key);
        } catch (ExecutionException e) {
            logger.log(Level.SEVERE, "Error removing key-value pair", e);
        }
    }

    public static void main(String[] args) {
        DistributedCache cache = new DistributedCache();
        // example usage
        cache.put("key1", "value1");
        String value = cache.get("key1");  // get the cached value
        cache.remove("key1");              // remove a key-value pair from cache
    }
}
