        for (int i = 0; i <= maxRetries; i++) {
            try {
                return configService.getBaseURL();
            } catch (Exception e) {
                if (i < maxRetries - 1) {
                    // retry
                } else {
                    throw new RuntimeException("Failed to retrieve base URL after " + maxRetries + " attempts", e);
                }
            }
        }
    }

