function runTests(moduleName, testCases, blueslipMock, externalDataSource, timeout, config) {
  const retryConfig = config.retries;
  const backoffConfig = config.backoff;
  const maxRetries = retryConfig.maxRetries;
  const delayMultiplier = retryConfig.delayMultiplier;

  let moduleLoaded = false;
  let loadAttempts = 0;
  let loadDelay = 0;

  async function loadModule() {
    if (!moduleLoaded) {
      try {
        await require(moduleName);
        moduleLoaded = true;
      } catch (error) {
        if (loadAttempts < maxRetries) {
          console.log(`Loading module ${moduleName} failed. Retrying in ${loadDelay}ms...`);
          setTimeout(() => loadModule(), loadDelay);
          loadDelay *= delayMultiplier;
          loadAttempts++;
        } else {
          throw error;
        }
      }
    }
  }

  async function runTestCase(testCase) {
    console.log(`Running test case: ${testCase.name}`);
    try {
      await Promise.all([
        ...Array(5).fill().map(() => {
          return externalDataSource.then((data) => {
            blueslipMock.data = data;
          });
        }),
        testCase(blueslipMock, data),
      ]);
    } catch (error) {
      console.error(`Test case ${testCase.name} failed: ${error}`);
      // Log detailed error report
    }
  }

  async function runAllTests() {
    await loadModule();
    for (const testCase of testCases) {
      await runTestCase(testCase);
      blueslipMock.reset();
      externalDataSource = null;
    }
    console.log(`Total time taken: ${Date.now() - startTime}ms`);
  }

  let startTime = Date.now();
  runAllTests().then(() => {
    // Log overall performance metrics
  });
}
