// service.js
import { ApolloServer } from '@apollo/server';
import { makeExecutableSchema } from 'graphql-tools';
import { retry } from 'apollo-client';
import { sentimentAnalysisEngine } from './sentiment-analysis-engine';

const API_ENDPOINTS = [
  'https://api1.com',
  'https://api2.com',
  'https://api3.com'
];

const PREPROCESSING_PIPELINE = {
  filterStopWords: (text) => text.replace(/[^a-zA-Z0-9]/g, ''),
  handleDomainSpecificSlang: (text) => text.replace(/(\w+)\s+(\w+)/g, '$1-$2'),
};

const APOLLO_SERVER = new ApolloServer({
  typeDefs: makeExecutableSchema({
    typeDefs: /* GraphQL */ `
      type Review {
        id: ID!
        content: String
        sentiment: Float
      }

      query {
        reviews(limit: Int): [Review]
        sentimentAnalysis(reviewId: ID!): Float
      }
    `,
    resolvers: {
      Query: {
        reviews: async (parent, { limit }) => {
          const reviews = [];
          try {
            for await (const endpoint of API_ENDPOINTS) {
              const response = await retry(() => fetch(endpoint + '/reviews'), 3);
              const data = await response.json();
              reviews.push(...data.reviews.map((review) => ({ ...review, sentiment: sentimentAnalysisEngine(review.content) })));
            }
          } catch (error) {
            console.error('Error fetching reviews:', error);
          }
          return reviews.slice(0, limit);
        },
        sentimentAnalysis: async (parent, { reviewId }) => {
          const response = await fetch(`https://sentiment-analysis-api.com/${reviewId}`);
          const data = await response.json();
          return data.sentiment;
        },
      },
    },
  }),
});

APOLLO_SERVER.listen({ port: 4000 });
