function renderFooterScripts(scripts) {
  const footerHtml = '';
  scripts.forEach((script) => {
    if (!script.type || !['module', 'text/javascript'].includes(script.type)) {
      throw new Error('Invalid script type');
    }

    let scriptTag = `<script ${script.type === 'module' ? 'type="module"' : 'type="text/javascript"'} ${
      script.src
        ? `src="${script.src}" defer`
        : `>${sanitizeScriptContent(script.id, script.key)}`}>${script.id}</script>`;

    if (script.src) {
      fetchScript(script.src, script.key)
        .then((response) => {
          const cachedResponse = cacheScripts.get(script.src);
          if (cachedResponse && Date.now() - cachedResponse.timestamp < 86400000) {
            // Use cached response
            return Promise.resolve(cachedResponse.body);
          } else {
            // Fetch and cache the script
            return response.text().then((scriptContent) => {
              cacheScripts.set(script.src, { body: scriptContent, timestamp: Date.now() });
              return scriptContent;
            });
          }
        })
        .catch((error) => {
          console.error('Error fetching script:', error);
          // Retry up to 3 times
          if (retryCount < 3) {
            setTimeout(() => fetchScript(script.src, script.key), 1000 * retryCount++);
          } else {
            // Log and continue processing other scripts
            console.log('Failed to load script:', script.src);
          }
        })
        .then((scriptContent) => {
          // Replace the placeholder with the actual script content
          scriptTag = `<script ${script.type === 'module' ? 'type="module"' : 'type="text/javascript"'}>${
            sanitizeScriptContent(script.id, script.key)
          }</script>`;
        });
    }

    footerHtml += scriptTag;
  });

  // Check the combined size of rendered scripts
  const totalSize = scripts.reduce((acc, script) => {
    return acc + (script.src ? getScriptSize(script.src) : 0);
  }, 0);

  if (totalSize > 10240) { // 10KB limit exceeded
    console.warn('Scripts exceed the size limit. Deferring some scripts to improve performance...');
    const criticalScripts = scripts.filter((script) => script.key === 'critical');
    criticalScripts.forEach((script) => {
      footerHtml += `<script ${script.type === 'module' ? 'type="module"' : 'type="text/javascript"'}>${
        sanitizeScriptContent(script.id, script.key)
      }</script>`;
    });
  }

  return footerHtml;
}

const cacheScripts = new Map();
let retryCount = 0;

function fetchScript(src, key) {
