  const { amount, currency } = req.body;
  const exchangeRate = getExchangeRate(currency);
  const paymentMethod = req.body.paymentMethod;

  // Call the relevant payment gateway API with the processed amount and currency
  axios.post(paymentGateways[paymentMethod].url, {
    amount: amount * exchangeRate,
    currency: 'USD'
  }, {
    headers: {
      'Authorization': `Bearer ${paymentGateways[paymentMethod].api_key}`,
    }
  })
  .then(response => {
    res.send({ status: 'success', transactionId: response.data.transactionId });
  })
  .catch(error => {
    console.error(error);
    res.status(500).send({ status: 'failure' });
  });
});

