  const { transactionId } = req.body;
  const paymentMethod = req.body.paymentMethod;

  // Call the relevant payment gateway API with the refund request
  axios.post(paymentGateways[paymentMethod].url + '/refunds', {
    transactionId,
  }, {
    headers: {
      'Authorization': `Bearer ${paymentGateways[paymentMethod].api_key}`,
    }
  })
  .then(response => {
    res.send({ status: 'success' });
  })
  .catch(error => {
    console.error(error);
    res.status(500).send({ status: 'failure' });
  });
});

// Define a function to get the exchange rate for a given currency
