import * as fs from 'fs';
import * as path from 'path';
import { Service } from 'typedi';
import { Injectable } from '@nestjs/common';
import { Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { CacheManager } from 'cache-manager';

@Injectable()
@Service('config-service')
export class ConfigService {
  private logger: Logger;
  private config: any;
  private cache: any;

  constructor(
    private readonly configService: ConfigService,
    private readonly cacheManager: CacheManager
  ) {
    this.logger = new Logger();
    this.config = {};
    this.cache = this.cacheManager.get('config-cache');
  }

  async fetchConfig(): Promise<any> {
    try {
      const externalConfig = await this.getExternalConfig();
      if (!this.config) {
        this.config = await this.flattenJson(externalConfig);
      }
      return this.config;
    } catch (error) {
      this.logger.error(`Failed to fetch config: ${error}`);
      throw error;
    }
  }

  async getNestedValue(config: any, path: string): Promise<any> {
    try {
      return Object.values(config).reduce((acc, value) => {
        if (value && value.__typename === 'Object') {
          const nestedPath = `${path}.${value.name}`;
          const result = this.getNestedValue(value, nestedPath);
          if (result !== undefined) {
            return result;
          }
        } else if (value && value.__typename === 'Array') {
          for (const item of value.items) {
            if (item && item.__typename === 'Object') {
              const result = this.getNestedValue(item, `${path}.${value.name}`);
              if (result !== undefined) {
                return result;
              }
            }
          }
        } else {
          return config[path];
        }
      }, undefined);
    } catch (error) {
      this.logger.error(`Failed to get nested value: ${error}`);
      throw error;
    }
  }

  async flattenJson(jsonConfig: any): Promise<any> {
    try {
      const flattenedConfig = {};
      await this.flattenJsonRecursive(flattenedConfig, jsonConfig, '');
      return flattenedConfig;
    } catch (error) {
      this.logger.error(`Failed to flatten config: ${error}`);
      throw error;
    }
  }

  async flattenJsonRecursive(config: any, json: any, path: string): Promise<any> {
    try {
      for (const key in json) {
        if (!json.hasOwnProperty(key)) continue;
        const value = json[key];
        const newPath = `${path}.${key}`;
        if (value && value.__typename === 'Object') {
          await this.flattenJsonRecursive(config, value, newPath);
        } else if (value && value.__typename === 'Array') {
          for (const item of value.items) {
            if (item && item.__typename === 'Object') {
              await this.flattenJsonRecursive(config, item, `${newPath}.${key}`);
            }
          }
        } else {
          config[newPath] = value;
        }
      }
    } catch (error) {
      this.logger.error(`Failed to flatten recursive: ${error}`);
      throw error;
    }
  }

  async filterConfig(role: string): Promise<any> {
    try {
      const filteredConfig = {};
      for (const key in this.config) {
        if (!this.config.hasOwnProperty(key)) continue;
        const value = this.config[key];
        if (value && value.accessLevel <= role) {
          filteredConfig[key] = value;
        }
      }
      return filteredConfig;
    } catch (error) {
      this.logger.error(`Failed to filter config: ${error}`);
      throw error;
    }
  }

  async updateConfig(newConfig: any): Promise<any> {
    try {
      if (!this.config) {
        await this.fetchConfig();
      }
      for (const key in newConfig) {
        if (!newConfig.hasOwnProperty(key)) continue;
        const value = newConfig[key];
        if (value && value.__typename === 'Object') {
          await this.updateConfig(value);
        } else {
          this.config[key] = value;
        }
      }
    } catch (error) {
      this.logger.error(`Failed to update config: ${error}`);
      throw error;
    }
  }

  async start(): Promise<void> {
    try {
      setInterval(async () => {
        const updatedConfig = await this.getExternalConfig();
        if (!this.config || !deepEqual(this.config, updatedConfig)) {
          await this.fetchConfig();
        }
      }, 10000);
    } catch (error) {
      this.logger.error(`Failed to start service: ${error}`);
      throw error;
    }
  }

  private async getExternalConfig(): Promise<any> {
    try {
      const response = await fetch('https://example.com/api/config');
      return await response.json();
    } catch (error) {
      this.logger.error(`Failed to fetch external config: ${error}`);
      throw error;
    }
  }
}

function deepEqual(a: any, b: any): boolean {
  if (!a && !b) return true;
  if (!a || !b) return false;
  for (const key in a) {
    if (!a.hasOwnProperty(key)) continue;
    const value = a[key];
    if (value && value.__typename === 'Object') {
      if (!deepEqual(value, b[key])) return false;
    } else if (value !== b[key]) return false;
  }
  for (const key in b) {
    if (!b.hasOwnProperty(key)) continue;
    const value = b[key];
    if (value && value.__typename === 'Object') {
      if (!deepEqual(value, a[key])) return false;
    } else if (value !== a[key]) return false;
  }
  return true;
}
