#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <dirent.h>

void rename_files_in_dir(char* dir_path) {
    DIR* dir = opendir(dir_path);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* file_path = malloc(strlen(dir_path) + strlen(entry->d_name) + 2);
        strcpy(file_path, dir_path);
        strcat(file_path, "/");
        strcat(file_path, entry->d_name);

        // Append version number, timestamp, and hash-based identifier
        time_t current_time = time(NULL);
        char* timestamp = ctime(&current_time);
        int hash_value = 0;
        for (int i = 0; i < strlen(entry->d_name); i++) {
            hash_value += entry->d_name[i];
        }
        char* version_str = malloc(strlen(timestamp) + strlen(entry->d_name) + 10);
        sprintf(version_str, "%s_%x_%d", timestamp, (unsigned int)hash_value, current_time);

        // Rename file
        if (rename(file_path, strcat(strcpy(file_path, "v"), version_str)) != 0) {
            perror("Error renaming files");
        }
    }
}

int main(int argc, char** argv) {
    rename_files_in_dir(argv[1]);
    return 0;
}
