    return os.path.join(os.getcwd(), f"{os.path.basename(file_path)}-{version}")

def rename_files(directory_path):
    for file_name in os.listdir(directory_path):
        file_path = os.path.join(directory_path, file_name)
        if os.path.isfile(file_path):
            with suppress(FileExistsError):
                new_file_path = get_file_version(file_path, os.path.getsize(file_path), hashlib.md5(open(file_path, "rb").read()).hexdigest())
                os.rename(file_path, new_file_path)

rename_files("/path/to/directory")
