#include <iostream>
#include <string>
#include "TIFFParser.h"

struct TIFFInfo {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
};

TIFFInfo parseTIFffFile(const std::string& filePath) {
    TIFFInfo info;

    // Open the file
    FILE* file = fopen(filePath.c_str(), "rb");
    if (!file) {
        return info;  // Return an error message
    }

    // Read the file header
    unsigned short type;
    fread(&type, sizeof(type), 1, file);
    if (type != 0x002A) {  // Not a TIFF file
        fclose(file);
        return info;  // Return an error message
    }

    // Get the number of images in the file
    unsigned long count;
    fread(&count, sizeof(count), 1, file);
    if (count > 0) {
        fseek(file, 8, SEEK_SET);  // Skip to the first image header
    } else {
        fclose(file);
        return info;  // Return an error message
    }

    // Parse the image header
    unsigned short bitsPerSample;
    unsigned short samplesPerPixel;
    fread(&bitsPerSample, sizeof(bitsPerSample), 1, file);
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        fclose(file);
        return info;  // Return an error message
    }

    fread(&samplesPerPixel, sizeof(samplesPerPixel), 1, file);

    // Read the extra samples (if any)
    int extraSamples = 0;
    for (int i = 0; i < count; ++i) {
        unsigned short sampleCount;
        fread(&sampleCount, sizeof(sampleCount), 1, file);
        if (sampleCount > 0) {
            extraSamples += sampleCount;
        }
    }

    fclose(file);

    info.bitsPerSample = bitsPerSample;
    info.samplesPerPixel = samplesPerPixel;
    info.extraSamples = extraSamples;

    return info;
}

int main() {
    std::string filePath = "image.tiff";
    TIFFInfo info = parseTIFffFile(filePath);
    if (info.bitsPerSample == 0) {
        // Return an error message
        std::cout << "Error: Unable to parse the file." << std::endl;
    } else {
        std::cout << "Bits per sample: " << info.bitsPerSample << std::endl;
        std::cout << "Samples per pixel: " << info.samplesPerPixel << std::endl;
        if (info.extraSamples > 0) {
            std::cout << "Extra samples: " << info.extraSamples << std::endl;
        }
    }

    return 0;
}
```

