// Define a structure for OctreeNode
struct OctreeNode {
    // Data point coordinates (x, y)
    int x, y;
    // Child nodes (0 to 7)
    std::unique_ptr<OctreeNode> children[8];
    // Flag indicating whether the node is full or not
    bool isFull;
};

// Define a class for Octree
class Octree {
public:
    // Constructor for Octree
    Octree() : root(std::make_unique<OctreeNode>()) {}

    // Function to insert a data point into the octree
    void insert(int x, int y) {
        auto node = &root;
        while (!node->isFull) {
            if (x <= node->x && y <= node->y) {
                if (!node->children[0]) {
                    node->children[0] = std::make_unique<OctreeNode>();
                    node->children[0]->x = x / 2;
                    node->children[0]->y = y / 2;
                    node->isFull = true;
                }
                break;
            } else if (x > node->x || y > node->y) {
                if (!node->children[7]) {
                    node->children[7] = std::make_unique<OctreeNode>();
                    node->children[7]->x = x / 2;
                    node->children[7]->y = y / 2;
                    node->isFull = true;
                }
                break;
            } else {
                if (node->children[3]) {
                    auto newNode = &node->children[3];
                    while (!newNode->isFull) {
                        if (x <= newNode->x && y <= newNode->y) {
                            if (!newNode->children[0]) {
                                newNode->children[0] = std::make_unique<OctreeNode>();
                                newNode->children[0]->x = x / 2;
                                newNode->children[0]->y = y / 2;
                                newNode->isFull = true;
                            }
                            break;
                        } else if (x > newNode->x || y > newNode->y) {
                            if (!newNode->children[7]) {
                                newNode->children[7] = std::make_unique<OctreeNode>();
                                newNode->children[7]->x = x / 2;
                                newNode->children[7]->y = y / 2;
                                newNode->isFull = true;
                            }
                            break;
                        } else {
                            node = &newNode->children[4];
                        }
                    }
                } else {
                    node = &node->children[4];
                }
            }
        }
    }

    // Function to query the octree for data points within a given range
    void query(int min_x, int max_x, int min_y, int max_y) {
        auto node = &root;
        while (node != nullptr) {
            if (min_x <= node->x && max_x >= node->x && min_y <= node->y && max_y >= node->y) {
                // Query the current node and its children
                for (int i = 0; i < 8; i++) {
                    if (!node->children[i].get()) continue;
                    query(node->children[i]->x, node->children[i]->y);
                }
            } else {
                // Move to the next node in the octree
                node = nullptr;
                for (int i = 0; i < 8; i++) {
                    if (!node->children[i].get()) continue;
                    if (min_x <= node->children[i]->x && max_x >= node->children[i]->x &&
                        min_y <= node->children[i]->y && max_y >= node->children[i]->y) {
                        node = &node->children[i];
                        break;
                    }
                }
            }
        }
    }

private:
    // Root node of the octree
    std::unique_ptr<OctreeNode> root;
};

int main() {
    Octree octree;

    // Insert some data points into the octree
    octree.insert(100, 100);
    octree.insert(200, 150);
    octree.insert(300, 250);

    // Query the octree for data points within a given range
    octree.query(0, 500, 0, 500);

    return 0;
}

