#include <iostream>
#include <fstream>
#include <string>
#include <cstdint>

struct ImageInfo {
    uint32_t bitsPerSample;
    uint32_t samplesPerPixel;
    uint16_t extraSamples;
};

ImageInfo parseTIFF(const std::string& filename) {
    ImageInfo info;

    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        return {0, 0, 0}; // Error - file not found
    }

    uint16_t bitsPerSample;
    file.seekg(3); // Skip TIFF header
    file.read(reinterpret_cast<char*>(&bitsPerSample), sizeof(bitsPerSample));
    info.bitsPerSample = static_cast<uint32_t>(bitsPerSample);

    if (info.bitsPerSample == 1 || info.bitsPerSample == 2 || info.bitsPerSample == 4 || 
        info.bitsPerSample == 8 || info.bitsPerSample == 16) {
        uint16_t samplesPerPixel;
        file.read(reinterpret_cast<char*>(&samplesPerPixel), sizeof(samplesPerPixel));
        info.samplesPerPixel = static_cast<uint32_t>(samplesPerPixel);

        if (file.tellg() % sizeof(uint16_t) != 0) {
            uint16_t extraSamplesCount;
            file.read(reinterpret_cast<char*>(&extraSamplesCount), sizeof(extraSamplesCount));
            info.extraSamples = static_cast<uint16_t>(extraSamplesCount);
        }
    } else {
        return {0, 0, 0}; // Error - unsupported bits per sample
    }

    file.close();
    return info;
}
