public class CryptoExtension
{
    // AES encryption
    public static byte[] EncryptAES(byte[] plainText, byte[] key)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.BlockSize = 128;
            ICryptoTransform encryptor = aes.CreateEncryptor();
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    cs.Write(plainText, 0, plainText.Length);
                }
                return ms.ToArray();
            }
        }
    }

    public static byte[] DecryptAES(byte[] cipherText, byte[] key)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.BlockSize = 128;
            ICryptoTransform decryptor = aes.CreateDecryptor();
            using (MemoryStream ms = new MemoryStream(cipherText))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    return ReadFully(cs);
                }
            }
        }
    }

    private static byte[] ReadFully(Stream stream)
    {
        const int buffer_size = 1024;
        byte[] buffer = new byte[buffer_size];
        List<byte> result = new List<byte>();
        while (true)
        {
            int read = stream.Read(buffer, 0, buffer_size);
            if (read == 0) break;
            result.AddRange(buffer, 0, read);
        }
        return result.ToArray();
    }

    // Camellia encryption
    public static byte[] EncryptCamellia(byte[] plainText, byte[] key)
    {
        using (CamelliaCryptoServiceProvider crypto = new CamelliaCryptoServiceProvider())
        {
            crypto.Key = key;
            ICryptoTransform encryptor = crypto.CreateEncryptor();
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    cs.Write(plainText, 0, plainText.Length);
                }
                return ms.ToArray();
            }
        }
    }

    public static byte[] DecryptCamellia(byte[] cipherText, byte[] key)
    {
        using (CamelliaCryptoServiceProvider crypto = new CamelliaCryptoServiceProvider())
        {
            crypto.Key = key;
            ICryptoTransform decryptor = crypto.CreateDecryptor();
            using (MemoryStream ms = new MemoryStream(cipherText))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    return ReadFully(cs);
                }
            }
        }
    }

    // MD5 hash
    public static byte[] ComputeMD5Hash(byte[] data)
    {
        using (MD5CryptoServiceProvider crypto = new MD5CryptoServiceProvider())
        {
