from typing import Dict, List
import logging
import requests
import json
from flask import Flask, request, jsonify
from flask_caching import Cache
from transformers import pipeline
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from kafka import KafkaProducer

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})
nlp_pipelines = {}

class InputData(BaseModel):
    text: str

class OutputData(BaseModel):
    sentiment: str
    entities: List[Dict]
    keywords: List[str]

@app.before_request
def before_request():
    if not request.path.startswith('/health'):
        logging.info(f'Received request: {request}')

@app.route('/process', methods=['POST'])
def process_text():
    input_data = InputData(**request.get_json())
    try:
        text = input_data.text
        sentiment_pipeline = nlp_pipelines['sentiment']
        entities_pipeline = nlp_pipelines['entities']
        keywords_pipeline = nlp_pipelines['keywords']

        sentiment_result = sentiment_pipeline(text)
        entities_result = entities_pipeline(text)
        keywords_result = keywords_pipeline(text)

        output_data = OutputData(
            sentiment=sentiment_result['label'],
            entities=entities_result,
            keywords=keywords_result
        )

        return jsonify(output_data.dict())
    except Exception as e:
        logging.error(f'Error processing text: {e}')
        raise HTTPException(status_code=500, detail='Internal Server Error')

def initialize_nlp_pipelines():
    global nlp_pipelines

    try:
        sentiment_pipeline = pipeline('sentiment-analysis')
        entities_pipeline = pipeline('entity- recognition')
        keywords_pipeline = pipeline('keyword-extraction')

        nlp_pipelines = {'sentiment': sentiment_pipeline, 'entities': entities_pipeline, 'keywords': keywords_pipeline}
    except Exception as e:
        logging.error(f'Error initializing NLP pipelines: {e}')
        raise

def main():
    initialize_nlp_pipelines()
    app.run(debug=True)

if __name__ == '__main__':
    main()

