    public class DecryptionService
    {
        private readonly ICryptoKeyProvider _cryptoKeyProvider;
        private readonly ILogger _logger;
        private readonly ILoggingService _loggingService;

        public DecryptionService(ICryptoKeyProvider cryptoKeyProvider, ILogger logger, ILoggingService loggingService)
        {
            _cryptoKeyProvider = cryptoKeyProvider;
            _logger = logger;
            _loggingService = loggingService;
        }

        public async Task ProcessMessageAsync(string base64EncodedMessage)
        {
            try
            {
                var messageBytes = Convert.FromBase64String(base64EncodedMessage);
                var decryptedMessageBytes = Decrypt(messageBytes);

                await _loggingService.LogDecryptedMessageAsync(decryptedMessageBytes);
            }
            catch (Exception ex) when (ex is ArgumentException || ex is NullReferenceException)
            {
                _logger.LogError(ex, "Invalid input");
                await _loggingService.LogErrorAsync(ex);
            }
            catch (Exception ex) when (ex is InvalidOperationException || ex is CryptographicException)
            {
                _logger.LogError(ex, "Decryption failed");
                await _loggingService.LogErrorAsync(ex);

                // Trigger callback mechanism to notify users
                await NotifyUsersOfDecryptionFailure();
            }
        }

        private byte[] Decrypt(byte[] messageBytes)
        {
            var key = _cryptoKeyProvider.GetKey();
            var iv = _cryptoKeyProvider.GetIV();

            using (var tripleDesAlg = TripleDES.Create())
            {
                tripleDesAlg.Key = key;
                tripleDesAlg.IV = iv;

                using (var decryptor = tripleDesAlg.CreateDecryptor())
                {
                    return decryptor.TransformFinalBlock(messageBytes, 0, messageBytes.Length);
                }
            }
        }

        private async Task NotifyUsersOfDecryptionFailure()
        {
            // Implement callback mechanism to notify users
        }
    }
}
