    public class DataRetrievalService
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<DataRetrievalService> _logger;
        private readonly IEncryptionService _encryptionService;
        private readonly ICacheService _cacheService;
        private readonly IConfigurationRoot _configuration;

        public DataRetrievalService(HttpClient httpClient, ILogger<DataRetrievalService> logger, IEncryptionService encryptionService, ICacheService cacheService, IConfigurationRoot configuration)
        {
            _httpClient = httpClient;
            _logger = logger;
            _encryptionService = encryptionService;
            _cacheService = cacheService;
            _configuration = configuration;
        }

        public async Task<string> GetDataAsync(string storageService, string dataId)
        {
            // Check if the data is already cached
            if (_cacheService.TryGetValue(dataId, out string cachedData))
                return cachedData;

            // Generate a signature for the request
            string signature = _encryptionService.GenerateSignature(dataId);

            // Convert the data to the required format
            string formattedData = _encryptionService.FormatData(dataId);

            // Send the request to the external API
            HttpResponseMessage response = await _httpClient.GetAsync($"https://{storageService}/{dataId}?signature={signature}&format={formattedData}");

            // Handle rate limiting and circuit breaker logic here

            if (response.IsSuccessStatusCode)
            {
                // Deserialize the data
                string deserializedData = await _encryptionService.DeserializeData(response.Content.ReadAsStreamAsync().Result);

                // Cache the data for future requests
                _cacheService.Set(dataId, deserializedData, TimeSpan.FromDays(7));

                return deserializedData;
            }
            else
            {
                // Handle errors and exceptions here
                throw new Exception("Failed to retrieve data");
            }
        }
    }

