let configFiles = {};

app.get('/config', (req, res) => {
  const { filename } = req.query;
  if (!filename || !configFiles[filename]) {
    return res.status(404).send({ message: 'Configuration file not found' });
  }
  try {
    const configFile = configFiles[filename];
    const placeholders = Object.keys(configFile.placeholders);
    const encryptedPassword = decrypt(configFile.password);
    const updatedConfig = replacePlaceholders(configFile.content, placeholders, encryptedPassword);
    res.send(updatedConfig);
  } catch (err) {
    console.error(err);
    res.status(500).send({ message: 'Error updating configuration' });
  }
});

app.post('/config', (req, res) => {
  const { filename, values } = req.body;
  if (!filename || !values) {
    return res.status(400).send({ message: 'Invalid request' });
  }
  try {
    configFiles[filename] = JSON.parse(req.body.config);
    const placeholders = Object.keys(configFiles[filename].placeholders);
    const encryptedPassword = crypto.createCipher('aes-256-cbc', process.env.ENCRYPTION_KEY).update(values.password, 'utf8', 'hex');
    configFiles[filename].password = encryptedPassword;
    res.send({ message: 'Configuration updated successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).send({ message: 'Error updating configuration' });
  }
});

