```javascript
// Import required libraries
const express = require('express');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');

// Create the Express app
var app = express();

// Connect to the database
mongoose.connect('mongodb://localhost/eCommercePlatform', { useNewUrlParser: true, useUnifiedTopology: true });

// Define the User model
let User = mongoose.model('User', {
  email: String,
  password: String,
  ShoppingCart: [{type: mongoose.Schema.Types.ObjectId, ref: 'Product'}]
});

// Define the Product model
let Product = mongoose.model('Product', {
  name: String,
  price: Number,
  inventory: Number
});

// Implement authentication and authorization
app.use((req, res, next) => {
  if (!req.headers.authorization) return res.status(401).send({ message: 'Unauthorized Request.' });
  const token = req.headers.authorization.split(' ')[0].replace('Bearer ', '');
  if (token !== process.env.TOKEN_KEY) return res.status(403).send({ message: 'Forbidden Access.' });
  let decoded = jwt.verify(token, process.env.SECRET_KEY);
  req.user = User.findById(decoded.id).exec();
  next();
});

// Implement API routes
app.get('/api/products', (req, res) => {
  Product.find().then(products => res.json(products));
});
