// Function to enqueue a new measurement in the thread-safe queue
void measurement_enqueue(LTE_UeMeasurementReport** measurements, int measurement_count) {
    // Create a new thread-safe queue
    pthread_mutex_lock(&measurement_queue_mutex);

    // Enqueue the new measurement
    measurements[measurement_count] = lte_ue_measurement_report_new(measurement_id, rsrp_value, sinr_value);

    // Notify the background worker thread to process the updated queue
    pthread_cond_signal(&measurement_queue_condition);

    pthread_mutex_unlock(&measurement_queue_mutex);
}

// Function to persist measurements exceeding a certain size or frequency to disk-based storage
void measurement_persist(LTE_UeMeasurementReport* report) {
    // Connect to the SQLite database
    sqlite3* db;
    int rc = sqlite3_open("measurements.db", &db);

    if (rc == SQLITE_OK) {
        // Create a new table to store the measurement data
        char* query = "CREATE TABLE IF NOT EXISTS measurements (measurement_id INTEGER PRIMARY KEY, rsrp_value REAL, sinr_value REAL);";
        sqlite3_exec(db, query, NULL, NULL, NULL);

        // Insert the measurement data into the table
        sqlite3_stmt* stmt;
        rc = sqlite3_prepare_v2(db, "INSERT INTO measurements VALUES (?, ?, ?);", -1, &stmt, NULL);
        if (rc == SQLITE_OK) {
            sqlite3_bind_int(stmt, 1, report->measurement_id);
            sqlite3_bind_double(stmt, 2, report->rsrp_value);
            sqlite3_bind_double(stmt, 3, report->sinr_value);

            rc = sqlite3_step(stmt);
            if (rc != SQLITE_DONE) {
                printf("Error persisting measurement: %s\n", sqlite3_errmsg(db));
            }

            sqlite3_finalize(stmt);
        }

        sqlite3_close(db);
    }
}

