void deserializeData(std::vector<complexDataRecord> &records, google::protobuf::Message* message) {
    complexDataRecord deserializedRecord;
    // Deserialize data structure from compact binary format using Google Protocol Buffers
    for (int i = 0; i < records.size(); i++) {
        auto deserializedRecord = message->DeserializeToBinary();
        records[i] = deserializedRecord;
    }
}

void computeMovingAverage(std::vector<complexDataRecord> &records) {
    int windowSize = 5;
    std::vector<double> movingAverages;

    for (int i = 0; i < records.size(); i++) {
        double sum = 0.0;
        for (int j = 0; j < windowSize && i + j < records.size(); j++) {
            if (records[i + j].getSomeIntField() > 0) {
                sum += records[i + j].getSomeDoubleField();
            }
        }
        movingAverages.push_back(sum / static_cast<double>(windowSize));
    }

    for (int i = 0; i < records.size(); i++) {
        if (movingAverages.size() > i) {
            auto record = &records[i];
            std::string movingAverageString;
            for (int j = 0; j < windowSize && i + j < records.size(); j++) {
                if (record->getSomeIntField() > 0) {
                    movingAverageString += boost::lexical_cast<std::string>(movingAverages[i]);
                    record->addMoreFields(movingAverageString);
                }
            }
        }
    }
}
