class OrderProcessor {
public:
    OrderProcessor(size_t numThreads) : inventory_(std::make_shared<std::mutex>()),
                                        updateQueue_(std::make_shared<std::mutex>()) {}

    void processOrder(const std::string& productId, size_t quantity) {
        // Validate product ID and quantity
        if (productId.empty() || quantity <= 0) {
            throw std::invalid_argument("Invalid order");
        }

        // Get current stock quantity
        auto it = inventory_.find(productId);
        size_t availableQuantity;
        if (it != inventory_.end()) {
            availableQuantity = it->second;
        } else {
            availableQuantity = 0; // New product or out-of-stock
        }

        // Check for sufficient stock
        if (quantity > availableQuantity) {
            throw std::out_of_range("Insufficient stock");
        }

        // Update inventory and mark as pending
        {
            std::lock_guard<std::shared_mutex> lock(*inventory_);
            it->second -= quantity;
            updateQueue_.emitUpdate(productId, -quantity);
        }

        // Process payment and confirm transaction
        try {
            // Simulate payment processing (e.g., integrate with third-party API)
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            // Confirm transaction
            {
                std::lock_guard<std::shared_mutex> lock(*inventory_);
                it->second = availableQuantity; // Reset stock quantity
            }
        } catch (const std::exception& e) {
            // Roll back changes on failure
            {
                std::lock_guard<std::shared_mutex> lock(*inventory_);
                it->second += quantity;
            }
            throw;
        }
    }

private:
    struct Update {
        const std::string productId;
        size_t quantity;

        Update(const std::string& productId, size_t quantity) : productId(productId), quantity(quantity) {}
    };

    template <typename T>
    class AtomicQueue {
    public:
        AtomicQueue(size_t capacity) : queue_(std::make_shared<std::mutex>(), capacity) {}

        void emitUpdate(T update) {
            std::unique_lock<std::shared_mutex> lock(*queue_.mutex_);
            while (queue_.size_ >= queue_.capacity_) {
                queue_.condition_variable_.wait(lock);
            }
            queue_.updates_.push_back(std::move(update));
            lock.unlock();
            queue_.notify_one();
        }

        void processUpdates() {
            std::unique_lock<std::shared_mutex> lock(*queue_.mutex_);
            while (true) {
                if (queue_.size_ > 0) {
                    auto update = std::move(queue_.updates_.front());
                    queue_.updates_.pop_front();
                    queue_.size_--;
                    processUpdate(std::move(update));
                } else {
                    queue_.condition_variable_.wait(lock);
                }
            }
        }

    private:
        struct Queue {
            size_t size_;
            std::vector<Update> updates_;
            std::shared_mutex mutex_;
            std::condition_variable condition_variable_;
        };

        AtomicQueue(const AtomicQueue&) = delete;
        AtomicQueue& operator=(const AtomicQueue&) = delete;
    };

    // Real-time market data feed integration
    void processMarketDataFeed() {
        auto updateQueue = *updateQueue_;
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            try {
                // Simulate real-time updates from the market data feed
                size_t newQuantity;
                std::string productId;
                // ...
                updateQueue.emitUpdate(productId, newQuantity);
            } catch (const std::exception& e) {
                // Handle errors and roll back changes if necessary
            }
        }
    }

    std::shared_ptr<std::mutex> inventory_;
    std::shared_ptr<std::mutex> updateQueue_;
};

int main() {
    OrderProcessor orderProcessor(4); // Initialize with 4 worker threads

    // Process orders concurrently
    for (size_t i = 0; i < 10000; ++i) {
