class RandomNumberGenerator {
public:
    RandomNumberGenerator() : rng_(std::rand()), lock_(), cond_(lock_) {}

    template<typename T>
    T generateRandom(T min, T max) {
        std::lock_guard<std::mutex> guard(lock_);
        return min + (max - min) * static_cast<T>(rng_()) / RAND_MAX;
    }

    void setSeed(unsigned int seed) {
        std::unique_lock<std::mutex> lock(lock_);
        rng_.seed(seed);
    }

private:
    std::random_device rd;
    std::mt19937 rng_;
    mutable std::mutex lock_;
    std::condition_variable cond_;

    template<typename T>
    static constexpr T generateRandomRange(T min, T max) {
        return static_cast<T>(std::uniform_real_distribution<T>(min, max)(rd));
    }
};
