    // Get timestamp
    time_t current_time = time(NULL);

    // Version file name with timestamp
    char filename[256];
    sprintf(filename, "%s-%ld", path, (long int)current_time);
    if (rename(path, filename) != 0) {
        return -1;
    }

    return 0;
}

