public class ResilientBackgroundProcessingSystem {
    private final ExecutorService executor = new ThreadPoolExecutor(
            10, // initial pool size
            20, // maximum pool size
            60, TimeUnit.SECONDS,
            new ArrayBlockingQueue<Runnable>(1000)); // queue capacity

    private final List<Worker> workers;

    public ResilientBackgroundProcessingSystem() {
        this.workers = new ArrayList<>();
    }

    public void addWorker(Worker worker) {
        workers.add(worker);
    }

    public void startProcessing() {
        workers.forEach(this::submitToExecutor);
    }

    private void submitToExecutor(Worker worker) {
        executor.submit(() -> worker.process());
    }
}

abstract class Worker implements Runnable {
    private final Logger logger = LoggerFactory.getLogger(getClass());

    @Override
    public void run() {
        try {
            process();
        } catch (Exception e) {
            logger.error("Error processing task", e);
            recoverFromFailure();
        }
    }

    abstract void process();

    void recoverFromFailure() {
        // implement recovery logic here
    }
}

