    public class Cipher
    {
        private readonly Aes aes;
        private readonly Camellia camellia;
        private readonly MD5 md5;
        private readonly SHA1 sha1;
        private readonly SHA256 sha256;

        public Cipher()
        {
            aes = Aes.Create();
            camellia = Camellia.Create();
            md5 = MD5.Create();
            sha1 = SHA1.Create();
            sha256 = SHA256.Create();
        }

        public byte[] Encrypt(string data, string key)
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = aes.CreateEncryptor(Encoding.UTF8.GetBytes(key), null))
                {
                    var encryptorStream = new CryptoStream(ms, cs, CryptoStreamMode.Write);
                    using (var sw = new StreamWriter(encryptorStream))
                    {
                        sw.Write(data);
                    }
                    encryptorStream.FlushFinalBlock();
                }
            }
        }

        public byte[] Decrypt(byte[] data, string key)
        {
            using (var ms = new MemoryStream(data))
            {
                using (var cs = aes.CreateDecryptor(Encoding.UTF8.GetBytes(key), null))
                {
                    var decryptorStream = new CryptoStream(ms, cs, CryptoStreamMode.Read);
                    using (var sr = new StreamReader(decryptorStream))
                    {
                        return sr.ReadToEnd().ToCharArray();
                    }
                }
            }
        }

        public byte[] CalculateMd5Hash(string data)
        {
            using (var md = MD5.Create())
            {
                var hashValue = md.ComputeHash(Encoding.UTF8.GetBytes(data));
                return hashValue;
            }
        }

        public byte[] CalculateSha1Hash(string data)
        {
            using (var sha = SHA1.Create())
            {
                var hashValue = sha.ComputeHash(Encoding.UTF8.GetBytes(data));
                return hashValue;
            }
        }

        public byte[] CalculateSha256Hash(string data)
        {
            using (var sha = SHA256.Create())
            {
                var hashValue = sha.ComputeHash(Encoding.UTF8.GetBytes(data));
                return hashValue;
            }
        }
    }
}
