#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for CellularPacket
typedef struct {
    int TransmissionTimingOffset;
    int TimingAdvance;
    void* PHYFrame; // pointer to external network buffer
} CellularPacket;

// Define the dynamic array of CellularPacket structures
typedef struct {
    CellularPacket** packets;
    int capacity;
    int size;
    pthread_mutex_t mutex; // synchronization mutex
} DynamicArray;

// Function to initialize a new DynamicArray with initial capacity and resize mechanism
DynamicArray* dynamic_array_init(int initial_capacity) {
    DynamicArray* array = (DynamicArray*) malloc(sizeof(DynamicArray));
    array->packets = (CellularPacket**) calloc(initial_capacity, sizeof(CellularPacket*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to resize the dynamic array
void dynamic_array_resize(DynamicArray* array) {
    int new_capacity = array->capacity * 2; // double the capacity for growth
    CellularPacket** new_packets = (CellularPacket**) realloc(array->packets, new_capacity * sizeof(CellularPacket*));
    array->packets = new_packets;
    array->capacity = new_capacity;
}

// Function to add a packet to the dynamic array
void dynamic_array_add(DynamicArray* array, CellularPacket* packet) {
    pthread_mutex_lock(&array->mutex); // acquire the mutex for thread safety
    if (array->size >= array->capacity) { // check for resizing needed
        dynamic_array_resize(array);
    }
    array->packets[array->size] = packet;
    array->size++;
    pthread_mutex_unlock(&array->mutex); // release the mutex
}

// Function to get a packet from the dynamic array
CellularPacket* dynamic_array_get(DynamicArray* array, int index) {
    pthread_mutex_lock(&array->mutex); // acquire the mutex for thread safety
    if (index < 0 || index >= array->size) { // check for out-of-range access
        return NULL; // return error or handle as desired
    }
    CellularPacket* packet = array->packets[index];
    pthread_mutex_unlock(&array->mutex); // release the mutex
    return packet;
}

// Function to free the dynamic array and its packets
void dynamic_array_free(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex); // acquire the mutex for thread safety
    for (int i = 0; i < array->size; i++) { // clean up packets
        if (array->packets[i]->PHYFrame) {
            free(array->packets[i]->PHYFrame);
        }
        free(array->packets[i]);
    }
    pthread_mutex_unlock(&array->mutex); // release the mutex
    free(array->packets);
    free(array);
}

// Function to demonstrate the user interface for querying packet count and accessing individual packets
int main() {
    DynamicArray* array = dynamic_array_init(10);

    // Add some packets...
    CellularPacket* packet1 = (CellularPacket*) malloc(sizeof(CellularPacket));
    packet1->TransmissionTimingOffset = 1;
    packet1->TimingAdvance = 2;
    packet1->PHYFrame = (void*) "some PHY frame data";
    dynamic_array_add(array, packet1);

    CellularPacket* packet2 = (CellularPacket*) malloc(sizeof(CellularPacket));
    packet2->TransmissionTimingOffset = 3;
    packet2->TimingAdvance = 4;
    packet2->PHYFrame = (void*) "some other PHY frame data";
    dynamic_array_add(array, packet2);

    // Query the current packet count...
    printf("Packet count: %d\n", array->size);

    // Access individual packets...
    CellularPacket* packet3 = dynamic_array_get(array, 0);
    if (packet3) {
        printf("Packet 1 TTO: %d, TA: %d, PHY frame data: %s\n",
               packet3->TransmissionTimingOffset, packet3->TimingAdvance,
               (char*) packet3->PHYFrame);
    }

    // Clean up and free the dynamic array...
    dynamic_array_free(array);

    return 0;
}

