import hashlib
import os
import concurrent.futures
import logging

class HashCalculator:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=5)

    def calculate_hashes(self, file_paths):
        results = []
        futures = []

        for file_path in file_paths:
            future = self.executor.submit(self._calculate_hash, file_path)
            futures.append(future)

        for future in concurrent.futures.as_completed(futures):
            result = future.result()
            results.append(result)

        return results

    def _calculate_hash(self, file_path):
        try:
            with open(file_path, 'rb') as file:
                file_size = os.path.getsize(file_path)
                chunk_size = 1024 * 1024  # Start with a reasonable chunk size
                if file_size < chunk_size:
                    chunk_size = file_size

                md5_hash = hashlib.md5()
                sha256_hash = hashlib.sha256()

                for i in range(0, file_size, chunk_size):
                    chunk = file.read(chunk_size)
                    md5_hash.update(chunk)
                    sha256_hash.update(chunk)

                return {
                    'file_path': file_path,
                    'md5_hash': md5_hash.hexdigest(),
                    'sha256_hash': sha256_hash.hexdigest()
                }
        except Exception as e:
            self.logger.error(f"Error calculating hash for {file_path}: {str(e)}")
            return None

    def validate_hashes(self, hashes):
        results = []

        for file_hash in hashes:
            if file_hash['md5_hash'] == file_hash['sha256_hash']:
                results.append({'file_path': file_hash['file_path'], 'status': 'Valid'})
            else:
                results.append({'file_path': file_hash['file_path'], 'status': 'Invalid'})

        return results

    def configure_logger(self, log_level='INFO', log_file=None):
        logging.basicConfig(level=log_level)
        if log_file:
            handler = logging.FileHandler(log_file)
            handler.setLevel(log_level)
            self.logger.addHandler(handler)

    def test_module(self):
        file_paths = ['path/to/file1', 'path/to/file2', ...]
        hashes = self.calculate_hashes(file_paths)
        validation_results = self.validate_hashes(hashes)
        print(validation_results)

if __name__ == "__main__":
    calculator = HashCalculator()
    calculator.configure_logger(log_level='DEBUG', log_file='hash_calculator.log')
    calculator.test_module()
