    public void LoadConfig(string configFilePath)
    {
        var config = JsonConvert.DeserializeObject<Config>(File.ReadAllText(configFilePath));
        // Set the configuration values
    }

    public void ProcessFile(string filePath)
    {
        // Load file metadata (size, etc.)
        var fileLength = new FileInfo(filePath).Length;
        var chunkSize = Math.Min(1024 * 1024, fileLength); // adjust chunk size based on network latency and server load

        using (var fileStream = File.OpenRead(filePath))
        {
            var chunks = new List<string>();
            for (int i = 0; i < (fileLength + chunkSize - 1) / chunkSize; i++)
            {
                var chunk = fileStream.Read(chunkSize);
                chunks.Add(new MD5().ComputeHash(chunk));
            }
        }

        // Validate MD5 hash
        if (chunks.Count != fileLength)
        {
            throw new Exception("File corrupted during transfer");
        }
    }

    public void ValidateHashes(List<string> hashes)
    {
        // Check for SHA-256 hash discrepancies across distributed servers
    }

    public async Task StartProcessing(IList<string> files)
    {
        foreach (var file in files)
        {
            await Task.Run(() => ProcessFile(file));
        }
    }

    public void LogErrors(List<Exception> errors)
    {
        foreach (var error in errors)
        {
            Console.WriteLine(error.Message);
