    [ApiController]
    [Route("api/[controller]")]
    public class FileHashController : ControllerBase
    {
        private readonly IFileHasher _fileHasher;

        public FileHashController(IFileHasher fileHasher)
        {
            _fileHasher = fileHasher;
        }

        [HttpPost]
        public async Task<IActionResult> HashFile([FromForm]IFormFile file, int chunkSize = 1024 * 1024)
        {
            using (var stream = file.OpenReadStream())
            {
                var buffer = new byte[chunkSize];
                long bytesRead = 0;

                while ((bytesRead = await stream.ReadAsync(buffer, 0, chunkSize)) > 0)
                {
                    _fileHasher.update(new MemoryStream(buffer, 0, bytesRead));
                }
            }

            return Ok(_fileHasher.get_hash());
        }
    }
