// Dynamic array of CellularPacket structures
struct {
    int size;
    int capacity;
    CellularPacket** packets;
    pthread_mutex_t mutex;
} cellular_packet_array = {0};

// Initialize the dynamic array with a default capacity and size
void init_cellular_packet_array(int initial_capacity) {
    cellular_packet_array.packets = (CellularPacket**)calloc(initial_capacity, sizeof(CellularPacket*));
    cellular_packet_array.size = 0;
    cellular_packet_array.capacity = initial_capacity;
    pthread_mutex_init(&cellular_packet_array.mutex, NULL);
}

// Resize the dynamic array based on adaptive thresholds
void resize_cellular_packet_array(int new_capacity) {
    int old_size = cellular_packet_array.size;
    CellularPacket** old_packets = cellular_packet_array.packets;

    // Handle resizing logic here...

    free(old_packets);
    cellular_packet_array.packets = (CellularPacket**)calloc(new_capacity, sizeof(CellularPacket*));
    cellular_packet_array.capacity = new_capacity;
