        // Handle error handling and logging...
    }

    pthread_mutex_lock(&cellular_packet_array.mutex);
    free(cellular_packet_array.packets[index]);
    for (int i = index; i < cellular_packet_array.size - 1; i++) {
        cellular_packet_array.packets[i] = cellular_packet_array.packets[i + 1];
    }
    cellular_packet_array.size--;
    pthread_mutex_unlock(&cellular_packet_array.mutex);
}

// Predictive cleanup of unused PHYFrame pointers
void predictive_cleanup() {
    // Handle error checking and logging...

    for (int i = 0; i < cellular_packet_array.size; i++) {
        if (!is_frame_in_use(cellular_packet_array.packets[i]->PHYFrame)) {
            free(cellular_packet_array.packets[i]->PHYFrame);
            cellular_packet_array.packets[i]->PHYFrame = NULL;
        }
    }
}

