    class Logger {
    public:
        Logger(const std::string& serviceName) : serviceName_(serviceName), logLevel_(DEBUG) {}

        void setLogLevel(LogLevel level) {
            logLevel_ = level;
        }

        template <typename... Args>
        void log(LogLevel level, const char* fmt, Args... args) {
            if (level > logLevel_) return;

            std::string message = fmt;
            ((std::cout << ... << args) >> std::cout).write(message);
            std::cout.flush();

            // Asynchronous logging
            std::thread([this, level, &message]() {
                std::unique_lock<std::mutex> lock(mutex_);
                queue_.emplace(message);

                if (level == FATAL) {
                    notifyService();
                }
            }).detach();
        }

    private:
        std::string serviceName_;
        LogLevel logLevel_;
        mutable std::mutex mutex_;
        std::condition_variable cv_;
        std::queue<std::string> queue_;

        void notifyService() {
            while (!queue_.empty()) {
                std::unique_lock<std::mutex> lock(mutex_);
                auto message = queue_.front();
                queue_.pop();

                // Send log messages to external services
                // ...

                cv_.notify_all();
            }
        }

        void flush() {
            while (!queue_.empty()) {
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
                notifyService();
            }
        }
    };

    class LogCollector : public Logger {
    public:
        LogCollector(const std::string& serviceName, const std::string& logEndpoint)
            : Logger(serviceName), logEndpoint_(logEndpoint) {}

        void start() override {
            flushThread_ = std::thread([this]() { flush(); });
