    private static final int MAX_EVENT_QUEUE_SIZE = 1000000; // adjust based on requirements
    private static final int EVENT_PROCESSOR_POOL_SIZE = Runtime.getRuntime().availableProcessors() * 2;
    private static final long EVENT_TIMEOUT_MILLIS = 5000L; // adjust based on requirements

    private final BlockingQueue<ApplicationEvent> eventQueue = new LinkedBlockingDeque<>(MAX_EVENT_QUEUE_SIZE);
    private final ThreadPoolExecutor eventProcessorPool = new ThreadPoolExecutor(EVENT_PROCESSOR_POOL_SIZE, EVENT_PROCESSOR_POOL_SIZE,
            0L, TimeUnit.MILLISECONDS, eventQueue);

    public EventProcessingFramework() {
        // start the thread pool
        eventProcessorPool.setRejectedExecutionHandler(new RejectedExecutionHandler() {
            @Override
            public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                try {
                    // implement retry logic for failed deliveries
                    Thread.sleep(EVENT_TIMEOUT_MILLIS);
                    if (executor.getQueue().size() < MAX_EVENT_QUEUE_SIZE) {
                        eventProcessorPool.execute(r);
                    } else {
                        // handle overflow conditions
                    }
                } catch (InterruptedException e) {
                    // handle interrupt exceptions
                }
            }
        });
    }

    public void processEvents(ApplicationEvent... events) {
        for (ApplicationEvent event : events) {
            eventQueue.put(event); // or use a producer-consumer queue to improve performance
        }
    }

