#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_LIST_SIZE 10000
#define CRCFLAG_DEFAULT (rand() % 2)

// Structure definition
typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to validate input list size
int validate_list_size(int N) {
    if (N < 1 || N > MAX_LIST_SIZE) {
        // Log warning and return error status
        printf("Invalid input list size: %d\n", N);
        return -1;
    }
    return 0;
}

// Function to allocate memory for linked list
void* alloc_list_node(void) {
    // Allocate memory for node
    void* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        // Handle allocation failure
        printf("Memory allocation failed.\n");
    }
    return node;
}

// Function to free memory for linked list nodes
void free_list_node(void* node) {
    // Free memory for node
    free(node);
}

// Function to insert a new node into the linked list
int insert_node(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (!(*head)) {
        *head = node;
    } else {
        // Insert node at the end of the list
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = node;
    }
    return 0;
}

// Function to remove a node from the linked list
int remove_node(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (*head == node) {
        *head = node->next;
    } else {
        // Remove node from the middle of the list
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while (temp->next && temp->next != node) {
            temp = temp->next;
        }
        if (temp->next == node) {
            temp->next = node->next;
        }
    }
    return 0;
}

// Function to update CRC flag for a node
int update_crc_flag(NFAPI_CRC_INDICATION_PDU_T* node, int crcflag) {
    // Update CRC flag for the node
    node->crc_indication.crcflag = crcflag;
    return 0;
}

// Function to print linked list
void print_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp) {
        printf("UE Info: %x, RNTI: %x, CRC Flag: %d\n", temp->ue_info, temp->rnti, temp->crc_indication.crcflag);
        temp = temp->next;
    }
}

int main() {
    // Initialize linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Allocate and insert nodes into the linked list
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = alloc_list_node();
        if (!node) {
            break;
        }
        // Initialize CRC flag randomly
        node->crc_indication.crcflag = CRCFLAG_DEFAULT;
        insert_node(&head, node);
    }

    // Update CRC flag for a node
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
