class EventStreamProcessor {
public:
    void processEvent(std::string event) {
        // Process the event
        std::cout << "Received event: " << event << std::endl;
    }

    void startProcessing() {
        std::thread thread([&]() {
            while (true) {
                // Read events from buffer and process them
                std::unique_lock<std::mutex> lock(bufferMutex);
                if (!buffer.empty()) {
                    auto event = buffer.front();
                    buffer.pop();
                    processEvent(event);
                }
                lock.unlock();

                // Sleep for a short period to avoid CPU overload
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        });
    }

private:
    std::mutex bufferMutex;
    std::queue<std::string> buffer;

    void enqueueEvent(std::string event) {
        lockGuard(bufferMutex);
        buffer.push(event);
    }
};

