public:
    DeviceMetricsManager();

    // Add device metrics to the dynamic array
    void addDeviceMetrics(const DEVICE_METRICS_T& metrics);

    // Get device metrics from the dynamic array by index
    DEVICE_METRICS_T getDeviceMetrics(int idx) const;

    // Remove device metrics from the dynamic array by index
    void removeDeviceMetrics(int idx);

private:
    std::vector<std::unique_ptr<DEVICE_METRICS_T>> deviceMetricsArray;
};

// Implement DeviceMetricsManager class methods
DeviceMetricsManager::DeviceMetricsManager() : deviceMetricsArray{} {}

void DeviceMetricsManager::addDeviceMetrics(const DEVICE_METRICS_T& metrics) {
    // Optimize memory allocation and deallocation using std::unique_ptr
    std::unique_ptr<DEVICE_METRICS_T> newMetric = std::make_unique<DEVICE_METRICS_T>(metrics);
    deviceMetricsArray.push_back(std::move(newMetric));
}

DEVICE_METRICS_T DeviceMetricsManager::getDeviceMetrics(int idx) const {
    if (idx < 0 || idx >= deviceMetricsArray.size()) {
        // Handle out-of-bounds error
        throw std::out_of_range("Index out of bounds");
    }
    return *deviceMetricsArray[idx].get();
}

void DeviceMetricsManager::removeDeviceMetrics(int idx) {
    if (idx < 0 || idx >= deviceMetricsArray.size()) {
        // Handle out-of-bounds error
        throw std::out_of_range("Index out of bounds");
    }
    deviceMetricsArray.erase(deviceMetricsArray.begin() + idx);
}
