int rename_files_in_directory(const char* directory_path) {
    DIR* dir = opendir(directory_path);
    if (!dir) {
        return -1;
    }

    // Initialize the cache and metadata service
    cache_set("initialized", "true");
    get_mime_type("example.txt", NULL);

    // Iterate over the files in the directory
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_DIR || !strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
            continue;
        }

        // Get the MIME type and metadata for the file
        char* mime_type = NULL;
        int metadata = fetch_metadata(entry->d_name);

        // Generate a unique identifier
        unsigned long timestamp = time(NULL);
        unsigned long hash = murmurhash2(entry->d_name, strlen(entry->d_name), 0);
        char* new_filename = malloc(strlen(entry->d_name) + 32);
        sprintf(new_filename, "%s-%ld-%lu.%s", entry->d_name, timestamp, hash, mime_type);

        // Rename the file
        if (rename(entry->d_name, new_filename) == -1) {
            free(new_filename);
            continue;
        }

        free(new_filename);
    }

    closedir(dir);
    return 0;
