    if (file == NULL) {
        return NULL;
    }
    unsigned char* buffer = malloc(1024);
    size_t buffer_size = 0;
    while (1) {
        size_t read = fread(buffer + buffer_size, 1, 1024 - buffer_size, file);
        if (read == 0) {
            break;
        }
        buffer_size += read;
    }
    fclose(file);
    unsigned char* hash = malloc(16);
    hashlib_md5_CTX ctx;
    hashlib_md5_init(&ctx);
    for (size_t i = 0; i < buffer_size; i++) {
        hashlib_md5_update(&ctx, buffer + i, 1);
    }
    hashlib_md5_final(&ctx, hash);
    char* hexdigest = malloc(33);
    for (int i = 0; i < 16; i++) {
        sprintf(hexdigest + i * 2, "%02x", hash[i]);
