        var logger = new Logger();
        logger.StartLogging();

        int value = 0;
        var randomGenerator = new RandomGenerator();
        value = randomGenerator.GenerateRandomValue();

        for (int i = 0; i < 10; ++i) {
            logger.Log("Random value: " + value.ToString());
        }

        logger.StopLogging();
    }
}
