};

class Logger {
public:
    Logger(std::map<std::string, std::vector<LogMessage>> &logs) : logs_(logs) {}

    void log(const LogMessage &message) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.insert({message.level, {message}}).first->second.push_back(message);
    }

private:
    mutable std::mutex mutex_;
    std::map<std::string, std::vector<LogMessage>> &logs_;
};

class LogIngestionService {
public:
    LogIngestionService(Logger &logger) : logger_(logger) {}

    void ingestLogs(const std::vector<LogMessage> &logs) {
        for (const auto &log : logs) {
            logger_.log(log);
        }
    }

private:
    Logger &logger_;
};

class DataCache {
public:
    DataCache(std::map<std::string, std::vector<std::string>> &cache) : cache_(cache) {}

    void put(const std::string &key, const std::string &value) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_.insert({key, {value}}).first->second.push_back(value);
    }

    std::vector<std::string> get(const std::string &key) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cache_.count(key)) {
            return cache_[key];
        }
        return {};
    }

private:
    mutable std::mutex mutex_;
    std::map<std::string, std::vector<std::string>> &cache_;
};

