#include <functional>

class ImageProcessor {
public:
    ImageProcessor() : stop(false), lock(mutex_) {}

    void startProcessing(std::function<void()> processImage) {
        thread_ = std::thread([this, &processImage] {
            while (!stop) {
                {
                    std::unique_lock<std::mutex> lock(mutex_);
                    cv_.wait(lock, [this] { return !queue_.empty(); });
                }
                auto image = queue_.front();
                processImage(image);
                queue_.pop_front();
            }
        });
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop = true;
        }
        cv_.notify_all();
        if (thread_.joinable()) {
            thread_.join();
        }
    }

    void addImage(std::string image) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            queue_.push_back(image);
        }
        cv_.notify_one();
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::deque<std::string> queue_;
    bool stop;
    std::thread thread_;
};

