#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <random>

class NFService {
public:
    NFService(int numWorkerThreads, int maxConcurrency) : 
        numWorkerThreads(numWorkerThreads), maxConcurrency(maxConcurrency),
        workerPool(numWorkerThreads), stop(false), cond(std::make_shared<std::mutex>()), logQueue() {
        for (int i = 0; i < numWorkerThreads; ++i) {
            workerPool.emplace([this, i]() {
                while (!stop) {
                    std::unique_lock<std::mutex> lock(*cond);
                    cond->wait(lock, [this] { return !stop || !logQueue.empty(); });
                    if (stop && logQueue.empty()) break;
                    auto work = logQueue.front();
                    logQueue.pop();
                    processWork(work);
                }
            });
        }
    }

    void enqueueLogEntry(int rnti, int crcFlag) {
        std::unique_lock<std::mutex> lock(*cond);
        if (stop) return; // service is stopped
        logQueue.emplace(rnti, crcFlag);
        cond->notify_one();
    }

    ~NFService() {
        stop = true;
        cond->notify_all();
        for (auto & worker : workerPool) worker.join();
    }

private:
    void processWork(int rnti, int crcFlag) {
        // generate NF-CRC indication PDU
        // ...
        std::cout << "Processed work: RNTI - " << rnti << ", CRC Flag - " << crcFlag << std::endl;
    }

    const int numWorkerThreads;
    const int maxConcurrency;
    std::vector<std::thread> workerPool;
    bool stop;
    std::shared_ptr<std::mutex> cond;
    std::queue<std::pair<int, int>> logQueue;
};

int main() {
    NFService service(4, 50);
    while (true) {
        // Generate RX UE information tags
        auto rnti = rand();
        auto crcFlag = rand();
        service.enqueueLogEntry(rnti, crcFlag);
    }
}
