public class DynamicStreamingDataProcessor {
    private static final Logger LOG = LoggerFactory.getLogger(DynamicStreamingDataProcessor.class);

    private Map<String, DataProcessor> processors = new ConcurrentHashMap<>();
    private Map<String, ConsumerConfig> kafkaConfigs = new ConcurrentHashMap<>();
    private Map<String, MqttClient> mqttClients = new ConcurrentHashMap<>();
    private Map<String, Call> restCalls = new ConcurrentHashMap<>();

    public void addDataProcessor(String dataSourceName, DataProcessor processor) {
        processors.put(dataSourceName, processor);
    }

    public void removeDataProcessor(String dataSourceName) {
        processors.remove(dataSourceName);
    }

    public void processStream(String dataSourceName, Object message) {
        DataProcessor processor = processors.get(dataSourceName);
        if (processor != null) {
            processor.process(message);
        }
    }

    public void subscribeToKafkaTopic(String topicName, ConsumerConfig config) {
        kafkaConfigs.put(topicName, config);
    }

    public void unsubscribeFromKafkaTopic(String topicName) {
        kafkaConfigs.remove(topicName);
    }

    public void connectMqttClient(String clientId, MqttClient client) {
        mqttClients.put(clientId, client);
    }

    public void disconnectMqttClient(String clientId) {
        mqttClients.remove(clientId);
    }

    public void makeRestCall(String url, Call call) {
        restCalls.put(url, call);
    }

    public void cancelRestCall(String url) {
        restCalls.remove(url).cancel();
    }
}

interface DataProcessor {
    void process(Object message);
}
