import logging
from abc import ABC, abstractmethod
import json
import requests
import time
import threading
import queue
from typing import Dict, List

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class Device(ABC):
    @abstractmethod
    def get_data(self) -> Dict:
        pass

    @abstractmethod
    def set_config(self, config: Dict):
        pass

class Sensor(Device):
    def __init__(self, device_id: str, data_stream: List[Dict]):
        self.device_id = device_id
        self.data_stream = data_stream

    def get_data(self) -> Dict:
        return {'device_id': self.device_id, 'data': next(self.data_stream)}

    def set_config(self, config: Dict):
        pass  # No-op for now

class Actuator(Device):
    def __init__(self, device_id: str, commands: List[Dict]):
        self.device_id = device_id
        self.commands = commands

    def get_data(self) -> Dict:
        return {'device_id': self.device_id, 'commands': next(self.commands)}

    def set_config(self, config: Dict):
        pass  # No-op for now

class IoTGateway:
    def __init__(self):
        self.devices = []
        self.config_queue = queue.Queue()

    def add_device(self, device: Device) -> None:
        self.devices.append(device)

    def get_data(self) -> List[Dict]:
        data = []
        for device in self.devices:
            if isinstance(device, Sensor):
                data.append(device.get_data())
            elif isinstance(device, Actuator):
                data.append(device.get_data())
        return data

    def set_config(self, config: Dict) -> None:
        for device in self.devices:
            if isinstance(device, Sensor):
                device.set_config(config)
            elif isinstance(device, Actuator):
                device.set_config(config)

# Example usage
if __name__ == '__main__':
