    # Add devices to the gateway
    sensor1 = Sensor('sensor-1', [{'temperature': 25.0}, {'humidity': 60.0}])
    actuator1 = Actuator('actuator-1', [{'command': 'turn_on'}])
    gateway.add_device(sensor1)
    gateway.add_device(actuator1)

    # Get data from devices
    data = gateway.get_data()

    # Set config for devices
    config = {'temperature_threshold': 28.0}
    gateway.set_config(config)
