#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure representing an RRC Connection Failure Message (CFM) record
typedef struct {
    int id;
    char message[256];
} NFAPI_RRC_CFM_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_RRC_CFM_PDU_T *record;
    struct Node *next;
} Node;

// Thread-safe linked list structure
typedef struct {
    Node *head;
    pthread_mutex_t lock;
} CFMList;

// Function to create a new CFM record node
Node* create_node(NFAPI_RRC_CFM_PDU_T *record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    return node;
}

// Function to insert a new CFM record at the end of the linked list
void cfm_list_insert(CFMList *list, NFAPI_RRC_CFM_PDU_T *new_record) {
    Node* new_node = create_node(new_record);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to delete a CFM record from the linked list
void cfm_list_remove(CFMList *list, int id) {
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL && current->record->id != id) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) return; // Record not found
    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
}

// Function to retrieve a CFM record by ID from the linked list
NFAPI_RRC_CFM_PDU_T* cfm_list_get(CFMList *list, int id) {
    Node* current = list->head;
    while (current != NULL && current->record->id != id) {
        current = current->next;
    }
    if (current == NULL) return NULL; // Record not found
    return current->record;
}

// Function to initialize the CFM list with a database connection
CFMList* cfm_list_init() {
    CFMList* list = (CFMList*)malloc(sizeof(CFMList));
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

// Function to free memory allocated for the linked list and database connection
void cfm_list_free(CFMList *list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage:
int main() {
    CFMList *cfm_list = cfm_list_init();

    // Insert records
    NFAPI_RRC_CFM_PDU_T record1 = {"record1", "This is the first CFM record"};
    cfm_list_insert(cfm_list, &record1);
    NFAPI_RRC_CFM_PDU_T record2 = {"record2", "This is the second CFM record"};
    cfm_list_insert(cfm_list, &record2);

    // Retrieve records
    NFAPI_RRC_CFM_PDU_T* retrieved_record = cfm_list_get(cfm_list, 1);
    if (retrieved_record != NULL) {
        printf("Retrieved record: %s\n", retrieved_record->message);
    }

    // Delete a record
    cfm_list_remove(cfm_list, 2);

    // Close the CFM list and free memory
    cfm_list_free(cfm_list);
    return 0;
}
