```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for CFM record
typedef struct {
    int timestamp;
    char *message;
} NFAPI_RRC_CFM_PDU_T;

// Define the linked list node structure
typedef struct {
    NFAPI_RRC_CFM_PDU_T record;
    struct list_node *next;
} list_node_t;

// Define the linked list structure
typedef struct {
    list_node_t *head;
    pthread_mutex_t lock;
} list_t;

// Function to create a new CFM record
NFAPI_RRC_CFM_PDU_T* cfm_record_create(int timestamp, char *message) {
    NFAPI_RRC_CFM_PDU_T* record = (NFAPI_RRC_CFM_PDU_T*)malloc(sizeof(NFAPI_RRC_CFM_PDU_T));
    record->timestamp = timestamp;
    record->message = message;
    return record;
}

// Function to insert a new CFM record into the linked list
void list_insert(list_t *list, NFAPI_RRC_CFM_PDU_T* record) {
    list_node_t *new_node = (list_node_t*)malloc(sizeof(list_node_t));
    new_node->record = *record;
    new_node->next = list->head;
    list->head = new_node;
}

// Function to delete a CFM record from the linked list
void list_delete(list_t *list, NFAPI_RRC_CFM_PDU_T* record) {
    list_node_t *curr = list->head;
    while (curr && curr->record != *record) {
        curr = curr->next;
    }
    if (curr) {
        list_node_t *temp = curr->next;
        free(curr);
        list->head = temp;
    }
}

// Function to retrieve a CFM record from the linked list
NFAPI_RRC_CFM_PDU_T* list_get(list_t *list, int timestamp) {
    list_node_t *curr = list->head;
    while (curr) {
        if (curr->record.timestamp == timestamp) {
            return &curr->record;
        }
        curr = curr->next;
    }
    return NULL;
}

// Initialize the linked list
void list_init(list_t *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

// Free the linked list resources
void list_free(list_t *list) {
    pthread_mutex_destroy(&list->lock);
    while (list->head) {
        list_node_t *temp = list->head;
        list->head = temp->next;
        free(temp);
    }
}
```
