// Distributed caching mechanism optimized for memory usage and cache hit rate
class DynamicCache {
public:
    DynamicCache(size_t capacity) : cache_(capacity), lock_() {}

    void put(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lock(lock_);
        if (cache_.size() >= capacity) {
            // Evict least-recently-used item
            auto it = cache_.begin();
            while (it != cache_.end()) {
                if (std::chrono::steady_clock::now() - it->second.timestamp >
                    std::chrono::milliseconds(1000)) {
                    break;
                }
                it = cache_.erase(it);
            }
        }
        cache_[key] = {value, std::chrono::steady_clock::now()};
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(lock_);
        if (cache_.count(key)) {
            auto it = cache_.find(key);
            return it->second.value;
        }
        return "";
    }

private:
    std::unordered_map<std::string, std::pair<std::string, std::chrono::steady_clock::time_point>> cache_;
    std::mutex lock_;
};

