class ThreadSafeRNG {
public:
    // Constructor: Seeding the RNG with a provided seed or system time
    ThreadSafeRNG(uint64_t seed = 0) : 
        mt_(seed), stateTransitionLog_(true), currentSeed_(seed) {}

    // Destructor: Properly managing resources and logging state transitions
    ~ThreadSafeRNG() {
        LogStateTransition("Destructor");
    }

    // Generating integer random numbers within specified bounds
    uint32_t GenerateInt(uint32_t min, uint32_t max) {
        return mt_() % (max - min + 1) + min;
    }

    // Generating floating-point random numbers within specified bounds
    double GenerateFloat(double min, double max) {
        return (double)(GenerateInt((uint32_t)((min - 0.0) * 2147483647 / (max - 0.0)), 
                                       (uint32_t)((max - 0.0) * 2147483647 / (max - 0.0)))) / 2147483647.0 + min;
    }

private:
    // Thread-safe Mersenne Twister generator
    class MT {
    public:
        uint32_t operator()() {
            uint32_t y = mersenneTwist_++;
            return (y >> 1) ^ ((y & 1) != 0 ? (uint32_t(0x9908b0dd)) : (uint32_t)0);
        }

    private:
        uint32_t mersenneTwist_;
    };

    // Logging state transitions and seed changes
    void LogStateTransition(const std::string& message = "") {
        if (!stateTransitionLog_) return;
        // Integrate with external logging system here, e.g., using a logger class
    }

    // Seeding the RNG (deterministic when seeded, non-deterministic otherwise)
    uint32_t seed() const { return currentSeed_; }

    MT mt_;
    std::atomic<bool> stateTransitionLog_;
    uint64_t currentSeed_;
};

// Example usage:
int main() {
    ThreadSafeRNG rng;

    // Generating random integers within a specified range
    for (int i = 0; i < 10; ++i) {
        int randomInt = rng.GenerateInt(1, 100);
        std::cout << "Random integer: " << randomInt << std::endl;
    }

    // Generating random floating-point numbers within a specified range
    for (int i = 0; i < 10; ++i) {
        double randomFloat = rng.GenerateFloat(0.0, 1.0);
        std::cout << "Random float: " << randomFloat << std::endl;
    }

    return 0;
}

