#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <fstream>

class LogAggregator {
public:
    LogAggregator() : running(true) {}

    ~LogAggregator() {
        stop();
    }

    void start() {
        thread_ = std::thread(&LogAggregator::run, this);
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            running_ = false;
        }
        cv_.notify_one();
        if (thread_) {
            thread_->join();
            thread_.reset();
        }
    }

    void addLog(const std::string& log) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            while (!running_) {
                cv_.wait(lock);
            }
            queue_.emplace(log);
        }
    }

    void readLogs() {
        while (true) {
            if (queue_.empty()) {
                break;
            }
            auto log = queue_.front();
            queue_.pop();
            // Process the log
            std::cout << "Processed: " << log << std::endl;
        }
    }

private:
    void run() {
        while (running_) {
            if (!queue_.empty()) {
                readLogs();
            } else {
                cv_.wait_for(mutex_, std::chrono::milliseconds(10));
            }
        }
    }

    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> running_;
    std::thread::shared_ptr<std::thread> thread_;
    std::queue<std::string> queue_;
};

int main() {
    LogAggregator aggregator;
    aggregator.start();

    // Add logs
    aggregator.addLog("Log 1");
    aggregator.addLog("Log 2");
    aggregator.addLog("Log 3");

    // Read logs
    aggregator.readLogs();

    return 0;
}
