        structures[i].RX_UE_INFORMATION_TAG[1] = 'X';
        structures[i].RX_UE_INFORMATION_TAG[2] = '_';
        structures[i].RX_UE_INFORMATION_TAG[3] = 'U';
        structures[i].RX_UE_INFORMATION_TAG[4] = 'E';
