import hashlib
import os

class AttackTemplate:
    def __init__(self, name: str, version: int, timestamp: long):
        self.name = name
        self.version = version
        self.timestamp = timestamp

class AttackSelector:
    def __init__(self):
        self.templates = []
        self.cached_templates = {}

    def add_template(self, template: AttackTemplate):
        with lock:
            self.templates.append(template)

    def select_and_rename_attack(self, attack_name: str) -> str:
        with lock:
            # Check if the attack is already in the cache
            cached_template = self.cached_templates.get(attack_name)
            if cached_template:
                return f"{cached_template[0]}_{cached_template[1]}"

            # Fetch the template from the database
            try:
                fetched_template = "Fetched Template: " + attack_name
                # Simulate a network call with varying response times
                os.urandom(randint(1000)).read()
                fetched_template += f"_{hashlib.md5(fetched_template.encode()).hexdigest()}"
            except Exception as e:
                print(f"Error fetching template: {e}")
                return ""

            # Cache the template
            version = randint(1, 100)
            timestamp = time.time()
            new_template = AttackTemplate(fetched_template, version, timestamp)
            self.cached_templates[attack_name] = (fetched_template, (version, timestamp))

            # Rename the attack template with the version and timestamp
            return f"{fetched_template}_{new_template.version}_{new_template.timestamp}"
