class CombatSystem {
public:
    enum class Attack { A, B };

    CombatSystem(int attackRatePerMinute) : attackRatePerMinute_(attackRatePerMinute), max AttacksPerSecond_(50 * 60 / 1000), cooldowns_({
        {Attack::A, 7},
        {Attack::B, 10}
    }), lastAttackTime_(0) {}

    void performAttack(Attack attack) {
        if (canPerformAttack()) {
            // Simulate attack logic here
            std::cout << "Attacking with " << (attack == Attack::A ? "Attack A" : "Attack B") << "...\n";
            updateCooldowns(attack);
        } else {
            handleCooldownRestrictions();
        }
    }

    void updateCooldowns(Attack attack) {
        int cooldown = getCooldown(attack);
        lastAttackTime_ += cooldown;
        std::this_thread::sleep_for(std::chrono::milliseconds(cooldown * 1000));
    }

    bool canPerformAttack() {
        if (getElapsedSecondsSinceLastAttack() >= maxAttacksPerSecond_) {
            return true;
        }
        int elapsed = getElapsedSecondsSinceLastAttack();
        int cooldown = getCooldown(Attack::A);
        if (elapsed >= cooldown) {
            return true;
        }
        // Check Attack B cooldown
        cooldown = getCooldown(Attack::B);
        if (elapsed >= cooldown) {
            return true;
        }
        return false;
    }

    void handleCooldownRestrictions() {
        std::cout << "Cooldown restrictions detected! Cannot perform an attack.\n";
    }

    int getElapsedSecondsSinceLastAttack() {
        return (int)((clock() - lastAttackTime_) / 1000);
    }

    int getCooldown(Attack attack) {
        if (attack == Attack::A) {
            return cooldowns_[Attack::A];
        } else if (attack == Attack::B) {
            return cooldowns_[Attack::B];
        }
        // Handle unknown attacks
        return -1;
    }

private:
    int attackRatePerMinute_;
    int maxAttacksPerSecond_;
    std::map<Attack, int> cooldowns_;
    double lastAttackTime_;
};

// Simulated API to track attack cooldowns
void getCooldownData(const CombatSystem& combatSystem) {
    Json::Value json;
    json["AttackA"] = 7; // Simulated cooldown timestamp in JSON format
    json["AttackB"] = 10;

    std::cout << "Received cooldown data: " << json << "\n";
}

int main() {
    CombatSystem combatSystem(50);

    while (true) {
        std::string input;
        std::cout << "Enter 'attack A' or 'attack B' to perform an attack, or 'exit' to quit.\n";
