    private final BlockingQueue<CharacterAction> actionQueue;

    public CombatSystem() {
        this.characterCooldowns = new ConcurrentHashMap<>();
        this.actionQueue = new LinkedBlockingQueue<>();
    }

    public void registerCharacter(String characterId) {
        characterCooldowns.put(characterId, new ConcurrentHashMap<>());
    }

    public void unregisterCharacter(String characterId) {
        characterCooldowns.remove(characterId);
    }

    public void addAttackAction(CharacterAction action) {
        if (actionQueue.offer(action)) {
            // Start a separate thread to process actions
            new Thread(() -> processActions()).start();
        }
