    private void processActions() {
        while (true) {
            try {
                CharacterAction action = actionQueue.take();
                String characterId = action.getCharacterId();
                Long cooldownTime = characterCooldowns.get(characterId).get(action.getType());
                if (cooldownTime == null || System.currentTimeMillis() >= cooldownTime) {
                    // Attack is ready to be executed
                    executeAttack(action);
                } else {
                    // Attack is on cooldown, wait until it's ready
                    long delay = cooldownTime - System.currentTimeMillis();
                    Thread.sleep(delay);
                    actionQueue.poll(); // Remove the action from the queue
                }
            } catch (InterruptedException | ExecutionException e) {
                // Handle exceptions and restart the thread if necessary
            }
        }
