namespace CryptoExtension
{
    public class CryptoProcessor
    {
        private readonly ICryptoService _cryptoService;

        public CryptoProcessor(ICryptoService cryptoService)
        {
            _cryptoService = cryptoService;
        }

        public async Task ProcessDataAsync(byte[] data, string algorithm)
        {
            using (var aes = _cryptoService.GetAlgorithm(algorithm))
            {
                var encryptedData = await EncryptDataAsync(data, aes);
                Console.WriteLine("Encrypted Data: " + Convert.ToBase64String(encryptedData));
            }
        }

        private async Task<byte[]> EncryptDataAsync(byte[] data, SymmetricAlgorithm algorithm)
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, algorithm.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    await cs.WriteAsync(data, 0, data.Length);
                    await cs.FlushFinalBlockAsync();
                }
                return ms.ToArray();
            }
        }

        public interface ICryptoService
        {
            SymmetricAlgorithm GetAlgorithm(string algorithmName);
        }
    }

    public class CryptoService : ICryptoService
    {
        private readonly Dictionary<string, SymmetricAlgorithm> _algorithms;

        public CryptoService()
        {
            _algorithms = new Dictionary<string, SymmetricAlgorithm>()
            {
                {"AES", Aes.Create()},
                {"Camellia", Camellia.Create()}
            };
        }

        public SymmetricAlgorithm GetAlgorithm(string algorithmName)
        {
            if (_algorithms.ContainsKey(algorithmName))
            {
                return _algorithms[algorithmName];
            }
            else
            {
                throw new ArgumentException("Unsupported Algorithm");
            }
        }
    }
}
