    initSystem(10000, 1024);

    // Create a pool of NFAPI_RRC_UE_CONTEXT structures
    pthread_t ueContextPoolManagerThread;
    pthread_create(&ueContextPoolManagerThread, NULL, &ueContextPoolManager, NULL);

