int validate_operation(struct connection* conn, const char* password, void (*callback)(void))
{
    if (!password || strlen(password) == 0)
        return EINVAL; // invalid password

    if (!conn->title || strlen(conn->title) == 0)
        return ECONNREFUSED; // invalid connection title

    if (!callback)
        return ENOENT; // callback function not provided

    return 0; // operation validated successfully
