**JavaScript Function for Extracting Book Names from Bible's Old Testament**

```javascript
function extractBookNames(text) {
  const bookNames = {
    Genesis: /Genesis/,
    Exodus: /Exodus/,
    Leviticus: /Leviticus/,
    Numbers: /Numbers/,
    Deuteronomy: /Deuteronomy/,
    Joshua: /Joshua/,
    Judges: /Judges/,
    Ruth: /Ruth/,
    1Samuel: /1 Samuel/,
    2Samuel: /2 Samuel/,
    1Kings: /1 Kings/,
    2Kings: /2 Kings/,
    1Chronicles: /1 Chronicles/,
    2Chronicles: /2 Chronicles/,
    Ezra: /Ezra/,
    Nehemiah: /Nehemiah/,
    Esther: /Esther/,
    Job: /Job/,
    Psalms: /Psalms/,
    Proverbs: /Proverbs/,
    Ecclesiastes: /Ecclesiastes/,
    SongOfSolomon: /Song of Solomon/,
    Isaiah: /Isaiah/,
    Jeremiah: /Jeremiah/,
    Lamentations: /Lamentations/,
    Ezekiel: /Ezekiel/,
    Daniel: /Daniel/,
    Hosea: /Hosea/,
    Joel: /Joel/,
    Amos: /Amos/,
    Obadiah: /Obadiah/,
    Jonah: /Jonah/,
    Micah: /Micah/,
    Nahum: /Nahum/,
    Habakkuk: /Habakkuk/,
    Zephaniah: /Zephaniah/,
    Haggai: /Haggai/,
    Zechariah: /Zechariah/,
    Malachi: /Malachi/
  };

  const bookCount = {};

  Object.keys(bookNames).forEach((book) => {
    let matches = text.match(bookNames[book]);
    while (matches !== null) {
      if (!Object.prototype.hasOwnProperty.call(bookCount, book)) {
        bookCount[book] = 0;
      }
      bookCount[book]++;
      matches = text.match(bookNames[book]);
    }
  });

  return bookCount;
}

console.log(extractBookNames("Genesis 1:1-3"));']

