import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

public class ConfigManager {
    private static final Logger logger = LoggerFactory.getLogger(ConfigManager.class);

    private Map<String, Object> configMap = new ConcurrentHashMap<>();
    private List<ConfigSource> configSources = new CopyOnWriteArrayList<>();

    public void addConfigSource(ConfigSource source) {
        configSources.add(source);
    }

    public void loadConfigurations() {
        for (ConfigSource source : configSources) {
            try {
                Map<String, Object> config = source.loadConfiguration();
                configMap.putAll(config);
            } catch (Exception e) {
                logger.error("Error loading configuration from {}: {}", source.getName(), e.getMessage());
            }
        }
    }

    public void updateConfig(String key, Object value) {
        configMap.put(key, value);
    }

    public void saveConfig() {
        for (ConfigSource source : configSources) {
            try {
                Map<String, Object> config = new HashMap<>(configMap);
                source.saveConfiguration(config);
            } catch (Exception e) {
                logger.error("Error saving configuration to {}: {}", source.getName(), e.getMessage());
            }
        }
    }

    public void startCaching() {
        configMap.put("lastUpdate", System.currentTimeMillis());
    }

    public void stopCaching() {
        // Invalidate cache
    }

    public class ConfigSource {
        private String name;
        private URI uri;

        public ConfigSource(String name, URI uri) {
            this.name = name;
