        // ...
        return ResponseEntity.ok("Data ingested");
    }

    @GetMapping("/logs")
    public ResponseEntity<List<LogEntry>> getLogs() {
        // Retrieve logs from logging service
        List<LogEntry> logs = ...;
        return ResponseEntity.status(HttpStatus.OK).body(logs);
    }
}

class UnionFind {
    private Map<Integer, Integer> parentMap;

    public void union(int value) {
        int root = find(value);
        for (int i = 0; i < parentMap.size(); i++) {
            if (parentMap.get(i) == root) {
                parentMap.put(i, value);
                break;
            }
        }
    }

    private int find(int value) {
        if (!parentMap.containsKey(value)) {
            parentMap.put(value, value);
        }
        return parentMap.get(value);
    }
}

class Measurement {
    private String sensorId;
    private int value;

    public String getSensorId() {
        return sensorId;
    }

    public int getValue() {
        return value;
    }
}

class Anomaly {
