package main
import (
	"fmt"
	"log"
	"time"

	"github.com/go-queue/queue"
)

func main() {
	// Initialize the queue with a capacity of 1000 messages
	q, err := queue.New(1000)
	if err != nil {
		log.Fatal(err)
	}

	// Start a new goroutine to handle messages from the queue
	go func() {
		for q.Get(); q.TryGet(); {
			msg, err := q.Recv()
			if err != nil {
				log.Println(err)
				continue
			}
			fmt.Printf("Received message: %s\n", msg)
		}
	}()

	// Start a new goroutine to send messages to the queue
	go func() {
		for i := 0; i < 10; i++ {
			err := q.Send(fmt.Sprintf("Message %d", i))
			if err != nil {
				log.Println(err)
				continue
			}
			time.Sleep(time.Second * 2)
		}
	}()

	// Run the main loop forever
	for {
		time.Sleep(time.Second * 1)
	}
}

