use async_graphql::{Context, Result};
use futures::stream::FuturesUnordered;
use log::info;

async fn process_payment_transaction(
    ctx: &mut Context<'_>,
    transaction_data: Vec<PaymentTransactionData>,
) -> Result<Vec<String>> {
    let mut result = vec![];

    for tx in transaction_data {
        match select_gateway(tx).await {
            Ok(gateway) => {
                if let Err(err) = process_transaction(ctx, gateway, &tx).await {
                    info!("Error processing transaction: {}", err);
                }
            },
            Err(e) => {
                info!("Error selecting gateway: {}", e);
            }
        }

        result.push("Transaction processed".to_string());
    }

    Ok(result)
}

async fn select_gateway(transaction_data: PaymentTransactionData) -> Result<Gateway, String> {
    // Dynamic configuration and security checks
    let config = get_config().await?;
    let (stripe_api_key, stripe_endpoint_url) = match transaction_data.gateway.as_ref() {
        "Stripe" => (
            config.stripe_api_key.clone(),
            config.stripe_endpoint_url.clone(),
        ),
        "PayPal" => (config.paypal_api_key.clone(), config.paypal_endpoint_url.clone()),
        "Braintree" => (config.braintree_api_key.clone(), config.braintree_endpoint_url.clone()),
        _ => return Err("Unsupported payment gateway".to_string()),
    };

    // Asynchronous communication with external gateways
    let mut gateways = FuturesUnordered::new();
    gateways.push(async move {
        let result = stripe_gateway(stripe_api_key, stripe_endpoint_url, transaction_data).await;
        match result {
            Ok(gateway) => Ok(gateway),
            Err(e) => Err(format!("Stripe gateway error: {}", e)),
        }
    });
    // ... add other gateways ...

    if let Some(result) = gateways.next().await {
        return result;
    }

    Err("No available gateways".to_string())
}

async fn process_transaction(ctx: &mut Context<'_>, gateway: Gateway, transaction_data: &PaymentTransactionData) -> Result<(), String> {
    // End-to-end encryption and tokenization for sensitive data
    let encrypted_data = encrypt_data(transaction_data.card_number, transaction_data.expiration_date, transaction_data.cvv);
    let tokenized_data = tokenize_data(&encrypted_data);

    // Asynchronous API calls to gateways
    match gateway.as_ref() {
        "Stripe" => stripe_api(stripe_endpoint_url(), &tokenized_data).await,
        "PayPal" => paypal_api(paypal_endpoint_url(), &tokenized_data).await,
        "Braintree" => braintree_api(braintree_endpoint_url(), &tokenized_data).await,
    };

    // Error handling and structured logging
    if let Err(err) = api_call_result {
        log_error(&err);
        return Err("Transaction processing failed".to_string());
    }

    Ok(())
}

async fn stripe_gateway(api_key: String, endpoint_url: String, transaction_data: PaymentTransactionData) -> Result<Gateway, String> {
    // Stripe-specific API calls and error handling
    let client = reqwest::blocking::ClientBuilder::new().timeout(std::time::Duration::from_secs(30)).build()?;
    let response = client.post(endpoint_url)
        .header("Authorization", format!("Bearer {}", api_key))
        .json(&transaction_data)
        .send()?;

    match response.status() {
        200 => Ok(Gateway::Stripe),
        _ => Err(format!("Stripe gateway error: {}", response.status())),
    }
}

