type TokenStore struct {
	mu     sync.Mutex
	tokens map[string]string
}

func NewTokenStore() *TokenStore {
	return &TokenStore{tokens: make(map[string]string)}
}

func (ts *TokenStore) Set(token string, value string) {
	ts.mu.Lock()
	defer ts.mu.Unlock()
	ts.tokens[token] = value
}

func (ts *TokenStore) Get(token string) (string, bool) {
	ts.mu.Lock()
	defer ts.mu.Unlock()
	if v, ok := ts.tokens[token]; ok {
