// Define a function to process DICOM file and extract pixel data information
DicomFile* readDICOMFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return NULL;

    // Read file header and verify format
    DicomFile* dicomFile = malloc(sizeof(DicomFile));
    fread(&dicomFile->pixelSpacing[0], sizeof(dicomFile->pixelSpacing), 3, file);
    fread(&dicomFile->rescaleSlope, sizeof(dicomFile->rescaleSlope), 1, file);
    fread(&dicomFile->rescaleIntercept, sizeof(dicomFile->rescaleIntercept), 1, file);
    fread(&dicomFile->pixelType, sizeof(dicomFile->pixelType), 1, file);
    fread(&dicomFile->photometricInterpretation, sizeof(dicomFile->photometricInterpretation), 1, file);

    // Verify pixel type and photometric interpretation
    if (dicomFile->pixelType < 1 || dicomFile->pixelType > 3) {
        printf("Unsupported pixel type: %u\n", dicomFile->pixelType);
        free(dicomFile); return NULL;
    }

    if (dicomFile->photometricInterpretation != 0 && dicomFile->photometricInterpretation != 1) {
        printf("Unsupported photometric interpretation: %u\n", dicomFile->photometricInterpretation);
        free(dicomFile); return NULL;
    }

    fclose(file);
