**Task 1: Modular Text Processing Microservice in Python**

```
import logging
from flask import Flask, request, jsonify
from transformers import pipeline
from flask_caching import Cache

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

nlp_pipelines = {
    'sentiment_analysis': pipeline('sentiment-analysis'),
    'entity_recognition': pipeline('ner'),
    'keyword_extraction': pipeline('keyphrase-extraction')
}

@app.route('/process', methods=['POST'])
def process_text():
    data = request.get_json()
    text = data['text']

    # Cache the NLP pipelines to reduce latency
    sentiment_pipeline = cache.get_or_compute('sentiment_analysis', lambda: nlp_pipelines['sentiment_analysis'].predict(text))
    entity_pipeline = cache.get_or_compute('entity_recognition', lambda: nlp_pipelines['entity_recognition'].predict(text))
    keyword_pipeline = cache.get_or_compute('keyword_extraction', lambda: nlp_pipelines['keyword_extraction'].predict(text))

    # Process the text using the cached NLP pipelines
    sentiment_results = sentiment_pipeline[0]
    entity_results = entity_pipeline[0]
    keyword_results = keyword_pipeline[0]

    return jsonify({
        'sentiment': sentiment_results,
        'entities': entity_results,
        'keywords': keyword_results
    })

if __name__ == '__main__':
    app.run(debug=True)
