    int timingAdvance;
    std::shared_ptr<PHYFrame> phyFrame;
};

class PacketManager {
private:
    std::vector<CellularPacket> packets;
    std::mutex mutex;
    std::condition_variable condition;

public:
    void addPacket(const CellularPacket& packet) {
        std::unique_lock<std::mutex> lock(mutex);
        packets.push_back(packet);
        lock.unlock();
        condition.notify_one();
    }

    void retrievePackets() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            if (packets.empty()) {
                condition.wait(lock);
            }
            CellularPacket packet = packets.back();
            packets.pop_back();
            lock.unlock();

            // Process the packet
            processPacket(packet.phyFrame);

            // Update memory allocation based on network conditions
            updateMemoryAllocation(packet.transmissionTimingOffset, packet.timingAdvance);
