import org.springframework.web.reactive.function.server.ServerResponse;
import reactor.core.publisher.Flux;

@SpringBootApplication
public class DataSyncMicroserviceApplication {

    public static void main(String[] args) {
        SpringApplication.run(DataSyncMicroserviceApplication.class, args);
    }

    @Bean
    public ThreadPoolTaskExecutor taskExecutor() {
        return new ThreadPoolTaskExecutor();
    }

    @Bean
    public ExecutorService executorService() {
        return Executors.newFixedThreadPool(5);
    }

    @Bean
    public Flux<String> syncData(Flux<RequestMessage> requestMessages) {
        return requestMessages.map(this::processRequest).flatMap(this::processResponse);
    }

    private Mono<ServerResponse> processRequest(RequestMessage message) {
        // Process incoming HTTP requests
        return Mono.just(ServerResponse.ok());
    }

    private Flux<Message> processResponse( ServerResponse response) {
        // Trigger batch jobs for data synchronization
        return Flux.fromIterable(Arrays.asList(
            new DataSyncJob("db1", "schema1"),
            new DataSyncJob("db2", "schema2")
        ));
    }

