namespace ModularWebsocketApplication
{
    public class WebSocketProcessor : Hub<WebSocketProcessor>
    {
        private readonly IDatabaseService _databaseService;
        private readonly IAnalyticsService _analyticsService;
        private readonly IKeyManagementService _keyManagementService;

        public WebSocketProcessor(IDatabaseService databaseService, IAnalyticsService analyticsService, IKeyManagementService keyManagementService)
        {
            _databaseService = databaseService;
            _analyticsService = analyticsService;
            _keyManagementService = keyManagementService;
        }

        public async Task ProcessMessage(string message)
        {
            try
            {
                // Decrypt the message using Triple DES
                byte[] encryptedBytes = Convert.FromBase64String(message);
                byte[] decryptedBytes = Decrypt(encryptedBytes);

                // Parse the JSON message
                int largestInteger = JsonConvert.DeserializeObject<int[]>(Convert.ToBase64String(decryptedBytes))[0];

                // Store the largest integer in the database
                await _databaseService.StoreLargestInteger(largestInteger);

                // Send the largest integer to analytics service for real-time insights
                await _analyticsService.SendAnalyticsData(largestInteger);
            }
            catch (Exception ex)
            {
                // Log error information for post-mortem analysis
                Console.WriteLine($"Error processing message: {ex.Message}");
            }
        }

        private byte[] Decrypt(byte[] encryptedBytes)
        {
            // Get the current key and IV from the key management service
            byte[] key = _keyManagementService.GetKey();
            byte[] iv = _keyManagementService.GetIV();

            // Decrypt the message using Triple DES
            MemoryStream ms = new MemoryStream(encryptedBytes);
            CryptoStream cs = new CryptoStream(ms, TripleDESCryptoServiceProvider.Create(key, iv));
            byte[] decryptedBytes = new byte[cs.Length];
            cs.Read(decryptedBytes, 0, decryptedBytes.Length);

            return decryptedBytes;
        }
    }
}
