using System.IO;
using System.Security.Cryptography;
using System.Text;

namespace SecureFileDecryptor
{
    public class FileDecryptor
    {
        private readonly IVaultService _vaultService;

        public FileDecryptor(IVaultService vaultService)
        {
            _vaultService = vaultService;
        }

        public async Task DecryptFileAsync(string filePath, string encryptionKeyId, string initializationVectorId)
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var encryptedBytes = new byte[fileStream.Length];
                await fileStream.ReadAsync(encryptedBytes.AsMemory(), 0, encryptedBytes.Length);

                var key = _vaultService.GetKey(encryptionKeyId);
                var iv = _vaultService.GetInitializationVector(initializationVectorId);

                using (var aesCbc = Aes.Create())
                {
                    aesCbc.Key = key;
                    aesCbc.IV = iv;

                    using (var decryptor = aesCbc.CreateDecryptor())
                    {
                        using (var memoryStream = new MemoryStream(encryptedBytes))
                        {
                            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                            {
                                var decryptedBytes = new byte[encryptedBytes.Length];
                                await cryptoStream.ReadAsync(decryptedBytes.AsMemory(), 0, decryptedBytes.Length);

                                using (var fileWriter = File.Create(filePath + ".decrypted"))
                                {
                                    await fileWriter.WriteAsync(decryptedBytes.AsMemory(), 0, decryptedBytes.Length);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    public interface IVaultService
    {
        byte[] GetKey(string keyId);
        byte[] GetInitializationVector(string ivId);
    }
}
