class RandomNumberGenerator:
    def __init__(self, seed_source):
        self.seed_source = seed_source
        self.current_seed = None
        self.lock = threading.Lock()

    def get_random_integer(self, min_value, max_value):
        with self.lock:
            if not self.current_seed:
                self.current_seed = self.seed_source.get_seed()
                logging.info(f"First random number generated after seed change: {self.current_seed}")
            return random.randint(min_value, max_value)

    def get_random_float(self, min_value, max_value):
        with self.lock:
            if not self.current_seed:
                self.current_seed = self.seed_source.get_seed()
                logging.info(f"First random number generated after seed change: {self.current_seed}")
            return (max_value - min_value) * random.random() + min_value

    def get_current_seed(self):
        with self.lock:
            return self.current_seed

