class TimestampedList {
public:
    void addTimestampedInt(int value, int timestamp) {
        std::lock_guard<std::recursive_mutex> lock(mutex_);
        auto newNode = new Node(value, timestamp);
        if (!root_) {
            root_ = newNode;
        } else {
            Node* current = root_;
            while (current->next_) {
                current = current->next_.get();
            }
            current->next_ = newNode;
        }
    }

    void findAndInsert(int targetValue, int startTimestamp, int endTimestamp) {
        std::lock_guard<std::recursive_mutex> lock(mutex_);
        Node* current = root_;
        while (current && (startTimestamp > current->timestamp || endTimestamp < current->timestamp)) {
            if (!current->next_) break;
            current = current->next_.get();
        }
        if (!current) {
            if (!root_) return; // list is empty
            append(&targetValue);
        } else {
            insertAfter(current, targetValue);
        }
    }

private:
    struct Node {
        int value;
        int timestamp;
        std::shared_ptr<Node> next_;
        Node(int value, int timestamp) : value(value), timestamp(timestamp) {}
    };

    void insertAfter(Node* before, int value) {
        auto newNode = new Node(value, timeService_.getCurrentTimestamp());
        newNode->next_ = before->next_.get();
        before->next_ = newNode;
    }

    void append(int* value) {
        root_->next_.reset(new Node(*value, timeService_.getCurrentTimestamp()));
    }

    std::shared_ptr<Node> root_;
    std::recursive_mutex mutex_;
    TimeService& timeService_;
};

class TimeService {
public:
    int getCurrentTimestamp() {
        // API call to get current timestamp
        return 1643723400; // sample timestamp
    }
};
