function asyncProcessCellularPackets(packetArray, bufferThreshold) {
  const packetMap = new WeakMap();
  let packetCount = 0;

  function getPacket(index) {
    if (!packetMap.has(index)) {
      const packet = packetArray[index];
      if (!packet) return null;
      packetMap.set(index, packet);
    }
    return packetMap.get(index);
  }

  async function processPackets() {
    for (let i = 0; i < packetArray.length; i++) {
      try {
        const packet = getPacket(i);
        if (!packet) continue;

        // Initialize PHYFrame and populate with data from the external network buffer
        packet.phyFrame = await initializePHYFrame(packet.phyFrame, bufferThreshold);

        // Perform processing operations on the packet
        await processPacket(packet);

      } catch (error) {
        console.error(`Error processing packet at index ${i}: ${error.message}`);
      }
