      return phf;
    } catch (error) {
      console.error(`Error initializing PHYFrame: ${error.message}`);
      throw error;
    }
  }

  function reduce(numbers, initial, callback) {
    let accumulator = initial;

    async function reducer() {
      for await (const number of numbers) {
        try {
          accumulator = callback(accumulator, number);
        } catch (error) {
          console.error(`Error reducing values: ${error.message}`);
          return error;
        }
      }

      return accumulator;
    }

    return reducer();
  }

