import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;

public class RateLimiter {

    private final ConcurrentHashMap<String, AtomicLong> tokenBucketMap = new ConcurrentHashMap<>();
    private final int maxTokensPerSecond;
    private final long replenishRateMs;

    public RateLimiter(int maxTokensPerSecond, long replenishRateMs) {
        this.maxTokensPerSecond = maxTokensPerSecond;
        this.replenishRateMs = replenishRateMs;
    }

    public void acquire(String key) {
        AtomicLong tokens = tokenBucketMap.computeIfAbsent(key, k -> new AtomicLong());
        while (tokens.get() < 1) {
            long sleepTime = calculateSleepTime(tokens);
            try {
                Thread.sleep(sleepTime);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            tokens.set(0); // Reset the token bucket
        }
        tokens.decrementAndGet(); // Consume a token
    }

    private long calculateSleepTime(AtomicLong tokens) {
        long remainingTokens = maxTokensPerSecond;
        long sleepTimeMs = 0;
        while (remainingTokens > 0) {
            sleepTimeMs += replenishRateMs;
            remainingTokens -= maxTokensPerSecond;
        }
        return sleepTimeMs;
    }
}
