    pthread_mutex_lock(&lock);

    if (numUeContexts < MAX_UE_CONTEXTS) {
        NFAPI_RRC_UE_CONTEXT* ueContext = &ueContextPool[numUeContexts++];
        return ueContext;
    }

    pthread_mutex_unlock(&lock);
    return NULL; // Pool is full
}

void releaseUeContext(NFAPI_RRC_UE_CONTEXT* ueContext) {
    pthread_mutex_lock(&lock);

