// Custom Lock Manager
class LockManager {
public:
    LockManager() : lock_(std::make_unique<std::mutex>()) {}

    void lock() {
        std::unique_lock<std::mutex, std::defer_lock> lock(*lock_);
        if (!lock.try_lock()) {
            throw std::runtime_error("Failed to acquire lock");
        }
    }

    void unlock() { (*lock_).unlock(); }

private:
    std::unique_ptr<std::mutex> lock_;
};

// Policy Engine
class PolicyEngine {
public:
    PolicyEngine(size_t capacity) : capacity_(capacity), purged_(0) {}

    void add(const std::string& key, const std::string& value) {
        if (purged_ >= capacity_) {
            throw std::runtime_error("Cache is full");
        }
        cache_.emplace(key, value);
    }

    void purge() {
        size_t toPurge = 0;
        for (auto it = cache_.begin(); it != cache_.end();) {
            if (!validate(it->first, it->second)) {
                it = cache_.erase(it);
                toPurge++;
            } else {
                ++it;
            }
        }
        purged_ += toPurge;
    }

private:
    size_t capacity_;
    size_t purged_;
    std::unordered_map<std::string, std::string> cache_;
};

