import java.util.*;

public class DisjointPairCounter {
    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);

        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!uf.find(i, j)) {
                    long start = System.nanoTime();
                    // Perform check
                    boolean disjoint = true;
                    for (int k = 0; k < array.length; k++) {
                        if ((k != i && k != j) && uf.isConnected(i, k) || uf.isConnected(j, k)) {
                            disjoint = false;
                            break;
                        }
                    }
                    long end = System.nanoTime();
                    if (!disjoint) {
                        System.out.println("Disjoint pair found: (" + array[i] + ", " + array[j] + ") - Time taken: " + (end - start));
                    }
                }
            }
        }

        return uf.countSets();
    }

    private static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public boolean find(int i, int j) {
            return (i == find(i)) && (j == find(j));
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }

        public int countSets() {
            Set<Integer> sets = new HashSet<>();
            for (int i = 0; i < parent.length; i++) {
                sets.add(find(i));
            }
            return sets.size();
        }
    }
}
