@RestController
class TextProcessingController {

    private final List<String> processedTexts = new ArrayList<>();
    private final int maxLength;

    public TextProcessingController(Random random) {
        this.maxLength = 1000;
    }

    @PostMapping("/process")
    public ResponseEntity process(@RequestBody String text) {
        if (text.isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Empty input");
        }

        // Apply customizable text transformations
        String processedText = transform(text);

        // Append a unique identifier (#) if the transformed text meets specified length constraints
        if (processedText.length() > maxLength) {
            processedText += "#" + random.nextInt(1000);
        }

        this.processedTexts.add(processedText);

        return ResponseEntity.ok("Processed text: " + processedText);
    }
}

@RestController
class AnalyticsController {

    private final TextProcessingRepository repository;

    public AnalyticsController(TextProcessingRepository repository) {
        this.repository = repository;
    }

    @GetMapping("/analytics")
    public ResponseEntity getAnalytics() {
        // Collect metrics from each processing operation and send aggregated insights to a centralized dashboard
        List<String> processedTexts = repository.getProcessedTexts();
        int totalOperations = processedTexts.size();

        double averageLength = processedTexts.stream().mapToInt(String::length).average().orElse(0);
        double uniqueIdCount = (double) processedTexts.stream().filter(text -> text.endsWith("#")).count() / totalOperations;

        return ResponseEntity.ok("Total operations: " + totalOperations +
                "\nAverage length: " + averageLength +
                "\nUnique ID count: " + uniqueIdCount);
    }
}

@Repository
class TextProcessingRepository {

    private final List<String> processedTexts = new ArrayList<>();

    public List<String> getProcessedTexts() {
        return this.processedTexts;
    }

    // Implement methods for storing and retrieving text processing results
}
