function asyncReduce(arr, callback) {
  let result = null;
  arr.forEach((num, i, nums) => {
    if (i === 0) {
      callback(num, (acc) => { result = acc; });
    } else {
      callback(num, (acc) => { result += acc; });
    }
  });
  return result;
}
