import pandas as pd
from kafka import KafkaProducer
from mqtt import MQTTClient
import http.client
import time
from datetime import datetime
from flask_sqlalchemy import SQLAlchemy

class IoTDataPipeline:
    def __init__(self):
        self.kafka_producer = KafkaProducer(bootstrap_servers=['localhost:9092'])
        self.mqtt_client = MQTTClient('localhost', 1883)
        self.http_client = http.client.HTTPConnection('localhost')

    def process_data(self, data):
        # Process IoT device data
        processed_data = pd.DataFrame(data).apply(lambda x: x['temperature'] + x['humidity'])

        # Store data in time-series database (InfluxDB)
        db = SQLAlchemy(url='influxdb://user:password@localhost:8086')
        db.write_points(processed_data, measurement='iot_data')

    def ingest_data(self):
        while True:
            try:
                message = self.kafka_producer.poll(0.1).values()[0]
                if message is not None:
                    data = json.loads(message.value)
                    self.process_data(data)
                    self.mqtt_client.publish('iot_data', str(data))
                    self.http_client.request('POST', '/api/v1/iot_data')
            except Exception as e:
                print(f"Error: {e}")
            time.sleep(0.5)

if __name__ == '__main__':
    pipeline = IoTDataPipeline()
    pipeline.ingest_data()

