namespace EdgeFramework {
    class Node {
        public:
            // Constructor
            Node(const std::string& nodeName) : nodeName_(nodeName) {}

            // Destructor
            ~Node() = default;

            // Model inference interface
            virtual void infer(std::vector<float> input) const = 0;

            // Load model from file
            virtual void loadModel(const std::string& modelFile) = 0;

            // Save model to file
            virtual void saveModel(const std::string& modelFile) = 0;

            // Get node name
            const std::string& getNodeName() const {
                return nodeName_;
            }

        private:
            std::string nodeName_;
    };

    class TensorFlowNode : public Node {
        public:
            // Constructor
            TensorFlowNode(const std::string& nodeName, const std::string& modelFile)
                : Node(nodeName), model_(tensorflow::loadModel(modelFile)) {}

            // Destructor
            ~TensorFlowNode() override = default;

            // Model inference interface
            void infer(std::vector<float> input) const override {
                tensorflow::infer(*model_, input);
            }

            // Load model from file
            void loadModel(const std::string& modelFile) override {
                model_ = tensorflow::loadModel(modelFile);
            }

            // Save model to file
            void saveModel(const std::string& modelFile) override {
                tensorflow::saveModel(*model_, modelFile);
            }

        private:
            tensorflow::ModelPtr model_;
    };

    class ONNXNode : public Node {
        public:
            // Constructor
            ONNXNode(const std::string& nodeName, const std::string& modelFile)
                : Node(nodeName), model_(onnx::loadModel(modelFile)) {}

            // Destructor
            ~ONNXNode() override = default;

            // Model inference interface
            void infer(std::vector<float> input) const override {
                onnx::infer(*model_, input);
            }

            // Load model from file
            void loadModel(const std::string& modelFile) override {
                model_ = onnx::loadModel(modelFile);
            }

            // Save model to file
            void saveModel(const std::string& modelFile) override {
                onnx::saveModel(*model_, modelFile);
            }

        private:
            onnx::ModelPtr model_;
    };

    class PyTorchNode : public Node {
        public:
            // Constructor
            PyTorchNode(const std::string& nodeName, const std::string& modelFile)
                : Node(nodeName), model_(pytorch::loadModel(modelFile)) {}

            // Destructor
            ~PyTorchNode() override = default;

            // Model inference interface
            void infer(std::vector<float> input) const override {
                pytorch::infer(*model_, input);
            }

            // Load model from file
            void loadModel(const std::string& modelFile) override {
                model_ = pytorch::loadModel(modelFile);
            }

            // Save model to file
            void saveModel(const std::string& modelFile) override {
                pytorch::saveModel(*model_, modelFile);
            }

        private:
            pytorch::ModelPtr model_;
    };

    class EdgeNode {
        public:
            // Constructor
            EdgeNode(Node* node, const std::string& nodeName)
                : node_(node), nodeName_(nodeName) {}

            // Destructor
            ~EdgeNode() = default;

            // Run inference on input data
            void runInference(std::vector<float> input) {
                node_->infer(input);
            }

        private:
            Node* node_;
            std::string nodeName_;
    };

    class EdgeFramework {
        public:
            // Constructor
            EdgeFramework() {}

            // Destructor
            ~EdgeFramework() = default;

            // Create edge node with given model and name
            EdgeNode createEdgeNode(Node* node, const std::string& nodeName) {
                return EdgeNode(node, nodeName);
            }

            // Load model on edge node
            void loadModel(EdgeNode& node, const std::string& modelFile) {
                node.node_->loadModel(modelFile);
            }

            // Save model to file on edge node
            void saveModel(EdgeNode& node, const std::string& modelFile) {
                node.node_->saveModel(modelFile);
            }
    };
}

