#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class MTRNG {
public:
    MTRNG(int seed = 0) : mt_(new MT19937(seed)), lastSeed_(seed) {}

    void seed() {
        int64_t now = std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();
        *mt_ = (int(now % 0x100000000LL));
        lastSeed_ = now;
    }

    double generateDouble(int min, int max) {
        uint64_t t = *mt_;
        t ^= (t >> 11);
        t ^= (t << 7) & 0x9d2c5680ULL;
        t ^= (t << 15) & 0xefbeaedfLL;
        t ^= (t >> 18);
        return min + ((double)(t % (max - min + 1)) / (double)(pow(2, 32) - 1));
    }

    int generateInt(int min, int max) {
        uint64_t t = *mt_;
        t ^= (t >> 11);
        t ^= (t << 7) & 0x9d2c5680ULL;
        t ^= (t << 15) & 0xefbeaedfLL;
        t ^= (t >> 18);
        return min + (int)(((double)(t % (max - min + 1)) / (double)(pow(2, 32) - 1)) * (max - min));
    }

private:
    struct MT19937 {
        uint64_t state;

        MT19937(int seed = 0) : state(0x6d072879LL + ((uint64_t)seed << 33)) {}

        uint32_t generate() {
            state = state * 0x1964F2C5ULL ^ (state >> 17);
            state ^= state << 15;
            state *= 0x1A41B333ULL;
            state += (state >> 18) ^ 0xE9A5BA3LL;

            return static_cast<uint32_t>(state);
        }
    };

    std::unique_ptr<MT19937> mt_;
    int64_t lastSeed_;
};

class RNGService {
public:
    RNGService(MTRNG& rng, int intervalMs = 100) : rng_(rng), interval_(std::chrono::milliseconds(intervalMs)) {}

    void start() {
        thread_ = std::thread(&RNGService::seedLoop, this);
    }

    void generateDouble(int min, int max) {
        double val = rng_.generateDouble(min, max);
        // Handle logging here
    }

    void generateInt(int min, int max) {
        int val = rng_.generateInt(min, max);
        // Handle logging here
    }

private:
    void seedLoop() {
        while (true) {
            std::this_thread::sleep_for(interval_);
            rng_.seed();
        }
    }

    MTRNG& rng_;
    std::chrono::duration<int> interval_;
    std::thread thread_;
};
```']

