['```rust
use tokio::sync::{mpsc, oneshot};
use tokio::task;
use url::Url;

async fn validate_jwt(token: String) -> Result<(), failure::Error> {
    let client = reqwest::Client::new();
    let idp_url = Url::parse("https://your-idp.com/validate-token")?;
    let request = client.get(idp_url)
        .header(reqwest::header::AUTHORIZATION, "Bearer your-client-id")
        .header(reqwest::header::CONTENT_TYPE, "application/json")
        .body(serde_json::to_string_pretty(&json!({"token": token}))?)
        .send()
        .await?
        .error_for_status()?;

    let result = client.text(idp_url)
        .header(reqwest::header::AUTHORIZATION, "Bearer your-client-id")
        .header(reqwest::header::CONTENT_TYPE, "application/json")
        .body(serde_json::to_string_pretty(&json!({"token": token}))?)
        .send()
        .await?
        .text()
        .await?;

    match serde_json::from_str::<jsonwebtoken::ValidationResult>(&result) {
        Ok(validation_result) => match validation_result {
            jsonwebtoken::ValidationResult::Valid => Ok(()),
            jsonwebtoken::ValidationResult::Invalid => Err(failure::err_msg("Invalid JWT")),
        },
        Err(_) => Err(failure::err_msg("Failed to parse JSON response")),
    }
}

#[tokio::main]
async fn main() {
    let (tx, rx) = mpsc::channel(10);

    tokio::task::spawn(async move {
        while let Ok(msg) = rx.recv().await {
            match validate_jwt(msg).await {
                Ok(_) => println!("Validation successful"),
                Err(err) => println!("Error: {}", err),
            }
        }
    });

    for _ in 0..100 {
        tx.send("your-jwt-token".to_string()).await?;
    }

    rx.recv().await
}

struct jsonwebtoken::ValidationResult {
    iss: Option<String>,
    sub: Option<String>,
    aud: Option<String>,
    exp: Option<i64>,
    iat: Option<i64>,
    nbf: Option<i64>,
}
