                if (!pokemon.hasWeaknesses()) {
                    try {
                        String weakestie = getWeakestie(pokemon.getName());
                        if (StringUtils.isNotBlank(weakestie)) {
                            pokemon.addWeakness(weakestie);
                        }
                    } catch (Exception e) {
                        logger.error("Error retrieving weakness for " + pokemon.getName(), e);
                    }
                }
            }
        }, 1, TimeUnit.MINUTES); // Update every minute
    }

    @Subscribe
    public void handleEvent(Event event) {
        if (event instanceof PokemonUpdateEvent) {
            PokemonUpdateEvent updateEvent = (PokemonUpdateEvent) event;
            updatePokemonWeaknesses(Collections.singletonList(updateEvent.getPokemon()));
        }
    }

    private void updatePokemonWeaknesses(List<Pokemon> pokemonData) {
        for (Pokemon pokemon : pokemonData) {
            if (!pokemonMap.containsKey(pokemon.getName())) {
                pokemonMap.put(pokemon.getName(), pokemon);
            } else {
                Pokemon existingPokemon = pokemonMap.get(pokemon.getName());
                // Update existing Pokemon with new weaknesses
                for (String weakness : pokemon.getWeaknesses()) {
                    existingPokemon.addWeakness(weakness);
                }
            }
        }
    }

