                ResultSet rs = ps.executeQuery();
                if (rs.next()) {
                    return rs.getString("city") + ", " + rs.getString("address");
                }
            }
        } catch (SQLException e) {
            logger.error("Error retrieving weakestie for " + pokemonName, e);
            throw new Exception("Failed to retrieve weakestie");
