    public class CryptoProcessor
    {
        private readonly Aes _aes;
        private readonly Camellia _camellia;
        private readonly MD5 _md5;
        private readonly SHA1 _sha1;
        private readonly SHA256 _sha256;
        private readonly RandomNumberGenerator _rng;

        public CryptoProcessor()
        {
            _aes = Aes.Create();
            _camellia = Camellia.Create();
            _md5 = MD5.Create();
            _sha1 = SHA1.Create();
            _sha256 = SHA256.Create();
            _rng = RandomNumberGenerator.Create();
        }

        public byte[] Encrypt(byte[] data, string key)
        {
            using (var ms = new MemoryStream())
            {
                var aesCryptoServiceProvider = _aes.CreateEncryptor(key.GetBytes());
                var cryptoStream = new CryptoStream(ms, aesCryptoServiceProvider);
                cryptoStream.Write(data, 0, data.Length);
                return ms.ToArray();
            }
        }

        public byte[] Decrypt(byte[] data, string key)
        {
            using (var ms = new MemoryStream(data))
            {
                var aesCryptoServiceProvider = _aes.CreateDecryptor(key.GetBytes());
                var cryptoStream = new CryptoStream(ms, aesCryptoServiceProvider);
                return cryptoStream.ToArray();
            }
        }

        public byte[] ComputeMD5(byte[] data)
        {
            return _md5.ComputeHash(data);
        }

        public byte[] ComputeSHA1(byte[] data)
        {
            return _sha1.ComputeHash(data);
        }

        public byte[] ComputeSHA256(byte[] data)
        {
            return _sha256.ComputeHash(data);
        }

        public byte[] GenerateRandomBytes(int length)
        {
            var randomBytes = new byte[length];
            _rng.GetBytes(randomBytes);
            return randomBytes;
        }
    }
}
