struct Profile {
    id: String,
    name: String,
    email: String,
}

async fn fetch_profiles(api_url: &str) -> Result<Vec<Profile>, reqwest::Error> {
    let client = reqwest::Client::new();
    let response = client.get(api_url).send().await?;
    let json = response.json::<Vec<Profile>>().await?;
    Ok(json)
}

async fn process_profiles(profiles: Vec<Profile>) -> Result<(), Box<dyn std::error::Error>> {
    // process profiles
    println!("Processed {} profiles", profiles.len());
    Ok(())
}

#[tokio::main]
async fn main() {
    let api_urls = vec![
        "https://api1.com",
        "https://api2.com",
        "https://api3.com",
    ];

    let mut workers = Vec::new();

    for api_url in &api_urls {
        let (tx, rx) = mpsc::channel(10);
        workers.push((tx, api_url.clone()));
        tokio::spawn(async move {
            let profiles = fetch_profiles(api_url).await?;
            tx.send(profiles).await;
        });
    }

    while let Some((tx, _)) = workers.pop() {
        let mut profile_batch = Vec::new();
        for _ in 0..10 {
            if let Ok(profiles) = rx.recv().await {
                profile_batch.extend_from_slice(&profiles);
            } else {
                break;
            }
        }
        process_profiles(profile_batch).await?;
    }
}

fn main() {
    // nothing to do here
}
