class CellularPacket {
public:
    int TransmissionTimingOffset;
};

void manageCellularPackets(std::vector<CellularPacket>& packets) {
    // implementation goes here...
}

// Thread-safe queue for logging and monitoring
class LoggingQueue {
private:
    std::mutex mtx;
    std::condition_variable condVar;
    std::queue<CellularPacket> packets;

public:
    void push(CellularPacket packet) {
        std::unique_lock<std::mutex> lock(mtx);
        packets.push(packet);
        lock.unlock();
        condVar.notify_one();
    }

    CellularPacket pop() {
        std::unique_lock<std::mutex> lock(mtx);
        while (packets.empty()) {
            condVar.wait(lock);
        }
        CellularPacket packet = packets.front();
        packets.pop();
        return packet;
    }
};

int main() {
    // Example usage:
    LoggingQueue logQueue;

    for (int i = 0; i < 100; ++i) {
        CellularPacket packet = {i};
        logQueue.push(packet);
    }

    while (!logQueue.empty()) {
        CellularPacket packet = logQueue.pop();
        std::cout << "Received packet: " << packet.TransmissionTimingOffset << std::endl;
    }
}
