from queue import Queue
from threading import Thread
from functools import wraps

# Configure logging settings
logging.basicConfig(level=logging.INFO)

# Set environment variables for configuration
FILE_CHUNK_SIZE = int(os.environ.get('FILE_CHUNK_SIZE', 1024 * 1024))  # default 1MB
RATE_LIMIT_PER_MINUTE = int(os.environ.get('RATE_LIMIT_PER_MINUTE', 100))
HASHING_SERVICE_URL = os.environ.get('HASHING_SERVICE_URL', 'https://example.com/hash/verify')

# Define a decorator for rate limiting API calls
def rate_limited(max_requests_per_minute):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal _rate_limit_counter
            if _rate_limit_counter >= max_requests_per_minute:
                logging.warning(f'Reached rate limit ({max_requests_per_minute} requests per minute). Waiting...')
                time.sleep(60 / max_requests_per_minute)  # wait for the next minute
            _rate_limit_counter += 1
            return func(*args, **kwargs)
        return wrapper
    return decorator

_rate_limit_counter = 0

# Define a thread-safe queue for processing files concurrently
file_queue = Queue()

def process_file(file_path):
    file_size = os.path.getsize(file_path)
    chunk_size = FILE_CHUNK_SIZE

    # Read the file in chunks to manage memory efficiently
    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            # Compute the SHA-256 hash of each file chunk
            chunk_hash = hashlib.sha256(chunk).hexdigest()
            logging.info(f'Processing file {file_path} - chunk {chunk_size} bytes')

            # Add the chunk to the queue for further processing
            file_queue.put((file_path, chunk_hash))

def verify_hashes():
    while True:
        try:
            file_path, chunk_hash = file_queue.get(block=False)
        except queue.Empty:
            break

        # Make API calls in parallel using threads
        def api_call(file_path, chunk_hash):
            @rate_limited(RATE_LIMIT_PER_MINUTE)
            def request_api():
                response = requests.post(HASHING_SERVICE_URL, json={'file': file_path, 'hash': chunk_hash})
                if response.status_code == 200:
                    return response.json()
                else:
                    raise Exception(f'API error: {response.status_code} - {response.text}')
            try:
                result = request_api()
                logging.info(f'Verified file {file_path}: {result.get("verified", "Failed")}')
            except Exception as e:
                logging.error(f'Error verifying file {file_path}: {str(e)}')
        Thread(target=api_call, args=(file_path, chunk_hash)).start()

# Start processing files concurrently
for root, dirs, files in os.walk('/path/to/files'):
    for file in files:
        process_file(os.path.join(root, file))

# Wait for all threads to finish before exiting
for _ in range(file_queue.qsize()):
    file_queue.get(block=True)

logging.info('Finished processing and verifying files')
