#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

class SensorDataNode {
public:
    std::string deviceId;
    int timestamp;
    double value;
    std::string tag;

    SensorDataNode(const std::string& id, int ts, double val, const std::string& tg)
        : deviceId(id), timestamp(ts), value(val), tag(tg) {}
};

class DistributedTree {
public:
    class Node {
    public:
        SensorDataNode data;
        Node* left = nullptr;
        Node* right = nullptr;

        Node(const SensorDataNode& data) : data(data) {}
    };

    class Iterator {
    private:
        Node* current;

    public:
        Iterator(Node* start) : current(start) {}

        bool hasNext() { return current != nullptr; }

        SensorDataNode next() {
            if (!hasNext()) throw std::runtime_error("No more elements");
            SensorDataNode data = current->data;
            current = current->right;
            return data;
        }
    };

    DistributedTree();
    ~DistributedTree();

    void insert(const SensorDataNode& data);
    Iterator getIterator() { return Iterator(root); }

private:
    Node* root = nullptr;

    std::mutex mtx;
    std::condition_variable cv;
};

DistributedTree::DistributedTree() {
    // Initialize the tree
}

DistributedTree::~DistributedTree() {
    // Clean up resources
}

void DistributedTree::insert(const SensorDataNode& data) {
    Node* newNode = new Node(data);
    {
        std::unique_lock<std::mutex> lock(mtx);
        if (root == nullptr) {
            root = newNode;
        } else {
            Node* curr = root;
            while (true) {
                if (data.timestamp > curr->data.timestamp) {
                    if (!curr->right) {
                        curr->right = newNode;
                        break;
                    }
                    curr = curr->right;
                } else {
                    if (!curr->left) {
                        curr->left = newNode;
                        break;
                    }
                    curr = curr->left;
                }
            }
        }
    }
    cv.notify_one();
}

