  // Check if the payment gateway is available and not down
  if (!paymentGateways.find((gateway) => gateway.id === parseInt(gatewayId))) {
    return res.status(400).send({ message: 'Payment gateway unavailable' });
  }

  try {
    // Process transaction with chosen payment gateway
    const response = await axios.post(`${paymentGateways[gatewayId - 1].endpoint}/transactions`, {
      amount,
      currency,
    });

    if (response.status === 200) {
      // Update database with successful transaction
      dbPool.query(`INSERT INTO transactions (amount, currency, status) VALUES ($1, $2, 'success') RETURNING *`, [
        amount,
        currency,
      ]);

      return res.send({ message: 'Transaction processed successfully' });
    } else {
      return res.status(400).send({ message: 'Transaction failed' });
    }
  } catch (error) {
    console.error(error);
    return res.status(500).send({ message: 'Internal server error' });
  }
});

// Implement refund transaction API endpoint
app.post('/refund-transaction', async (req, res) => {
  const { transactionId } = req.body;

  try {
    // Retrieve transaction details from database
    const result = await dbPool.query(`SELECT * FROM transactions WHERE id = $1`, [transactionId]);

    if (result.rows.length === 0) {
      return res.status(404).send({ message: 'Transaction not found' });
    }

    // Refund transaction with chosen payment gateway
    const response = await axios.post(`${paymentGateways[req.headers['x-payment-gateway-id']].endpoint}/refunds`, {
      amount: result.rows[0].amount,
      currency: result.rows[0].currency,
    });

    if (response.status === 200) {
      // Update database with successful refund
      dbPool.query(`UPDATE transactions SET status = 'refunded' WHERE id = $1`, [transactionId]);

      return res.send({ message: 'Transaction refunded successfully' });
    } else {
      return res.status(400).send({ message: 'Refund failed' });
    }
  } catch (error) {
