typedef struct {
    int socket_fd;
    char* client_ip;
} connection_t;

typedef struct {
    pthread_mutex_t lock;
    int num_connections;
    connection_t connections[MAX_CONNECTIONS];
} pool_t;

pool_t* create_pool();
void init_logging(pool_t* pool);
int handle_connection(pool_t* pool, int fd);
void close_connection(pool_t* pool, int index);

int main() {
    pool_t* pool = create_pool();
    init_logging(pool);

    // Main event loop
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        int client_fd = accept.pool[i].socket_fd;
        if (client_fd != -1) {
            handle_connection(pool, client_fd);
        }
    }

    return 0;
}

pool_t* create_pool() {
    pool_t* pool = malloc(sizeof(pool_t));
    pthread_mutex_init(&pool->lock, NULL);
    pool->num_connections = 0;
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pool->connections[i].socket_fd = -1;
    }
    return pool;
}

void init_logging(pool_t* pool) {
    // Initialize logging service
    int logging_service_fd = socket(AF_INET, SOCK_STREAM, 0);
    connect(logging_service_fd, (struct sockaddr*) &logging_service_port);

    pthread_create(&logger_thread, NULL, log_connections, pool);
}

int handle_connection(pool_t* pool, int fd) {
    connection_t new_conn;
    new_conn.socket_fd = fd;
    new_conn.client_ip = malloc(strlen(getpeername(fd)));
    strcpy(new_conn.client_ip, getpeername(fd));

    pthread_mutex_lock(&pool->lock);
    pool->connections[pool->num_connections++] = new_conn;
    pthread_mutex_unlock(&pool->lock);
}

void close_connection(pool_t* pool, int index) {
    connection_t* conn = &pool->connections[index];
    shutdown(conn->socket_fd, SHUT_RDWR);
    close(conn->socket_fd);
    free(conn->client_ip);
}
