#include <curl/curl.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t total_items;
    struct Item *items;
    size_t *item_lengths;
} ResourceBundle;

typedef struct {
    char *name;
    size_t value_length;
} Item;

int loadResourceBundle(const char* url, ResourceBundle** resource_bundle) {
    CURL* curl_handle = NULL;
    CURLcode result;
    char errorbuf[CURL_ERROR_SIZE];
    FILE *fp;
    int item_count = 0;
    size_t total_items = 0;
    char buffer[1024];
    struct Item **items = NULL;
    size_t *item_lengths = NULL;

    // Retry mechanism
    int retries = 3;  // Default number of retries
    CURLcode retry_result;

    do {
        // Initialize curl
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl_handle = curl_easy_init();

        if(curl_handle) {
            // Set URL and options
            curl_easy_setopt(curl_handle, CURLOPT_URL, url);
            curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, writeMemoryCallback);
            curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, buffer);
            curl_easy_setopt(curl_handle, CURLOPT_TIMEOUT, 10L); // Default timeout

            // Perform request and get response
            result = curl_easy_perform(curl_handle);

            if(result == CURLE_OK) {
                // Parse response
                fp = fopen("temp.txt", "w");
                fwrite(buffer, sizeof(char), strlen(buffer), fp);
                fclose(fp);

                // Read items from file
                item_count = 0;
                char line[1024];
                FILE *fp_items = fopen("temp.txt", "r");

                if (fp_items) {
                    while(fgets(line, sizeof(line), fp_items)) {
                        size_t pos = strlen(line);
                        while(pos > 1 && line[pos-1] == '\n') {
                            line[pos-1] = '\0';
                            pos--;
                        }
                        Item *item = malloc(sizeof(Item));
                        item->name = strdup(line);
                        item->value_length = strlen(item->name);
                        total_items++;
                        items = realloc(items, (total_items+1)*sizeof(struct Item*));
                        items[total_items-1] = item;
                    }
                }

                // Read lengths from file
                size_t *item_lengths = malloc(total_items * sizeof(size_t));

                for(int i=0; i<total_items; i++) {
                    fscanf(fp_items, "%zu\n", &item_lengths[i]);
                }
            } else {
                // Error handling
                if(result == CURLE_WRITE_ERROR) {
                    return E_INVALID_RESPONSE_FORMAT;
                } else if(result == CURLE_OPERATION_TIMED_OUT) {
                    return E_TIMEOUT;
                } else {
                    return E_CONNECTION_ERROR;
                }
            }

            free(items);
            items = NULL;

        } else {
            // Error handling
            return E_HTTP_STATUS_CODE_ERROR;
        }

    } while(retries-- > 0);

    curl_easy_cleanup(curl_handle);
    curl_global_cleanup();

    ResourceBundle *resource_bundle = malloc(sizeof(ResourceBundle));
    resource_bundle->total_items = total_items;
    resource_bundle->items = items;
    resource_bundle->item_lengths = item_lengths;

    *resource_bundle = resource_bundle;

    return 0;
}

size_t writeMemoryCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((char*)userp) += size*nmemb;
    return size*nmemb;
}
