// Secure Hash Helper Function
function cryptoHash(inputString) {
  const crypto = require('crypto');
  return crypto.createHash('sha256').update(inputString).digest('hex');
}

// Dialog Field Refresh Function
function refreshDialogFields(resourceId, resourceUrl, dialogFields) {
  // Iterate through field names and validate each against the input string
  for (const fieldName in dialogFields) {
    const fieldValue = dialogFields[fieldName];
    if (!fieldValue) continue;
    const hashInput = cryptoHash(fieldValue);
    if (hashInput.includes(resourceId)) {
      // Send message to parent window if a match is found
      postMessageToParent(window, { action: 'refresh', field: fieldName });
    }
  }

  // Helper function to send messages to the parent window
  function postMessageToParent(parentWindow, data) {
    try {
      parentWindow.postMessage(JSON.stringify(data), resourceUrl);
    } catch (err) {
      console.error('Error sending message to parent:', err);
    }
  }

  // Event listener for responses from the parent window
  window.addEventListener('message', function(event) {
    const { action, field, result } = JSON.parse(event.data);
    if (action === 'refresh') {
      // Update the dialog field with the response
      try {
        dialogFields[field] = result;
      } catch (err) {
        console.error('Error updating dialog field:', err);
      }
    }
  });
}
