class Attack {
public:
    std::string type;
    double probability;

    Attack(std::string type, double probability) : type(type), probability(probability) {}
};

std::mutex mtx;
std::condition_variable cv;
std::set<Attack*> attackSet;
std::map<std::string, double> probabilitiesMap;

void selectAttack() {
    std::unique_lock<std::mutex> lock(mtx);
    while (true) {
        for (auto& attack : attackSet) {
            if (rand() / static_cast<double>(RAND_MAX) < attack->probability) {
                std::cout << "Selected attack: " << attack->type << std::endl;
                return;
            }
        }
        cv.wait_for(lock, std::chrono::microseconds(500));
    }
}

void selectAttack(std::string type) {
    std::unique_lock<std::mutex> lock(mtx);
    if (auto it = probabilitiesMap.find(type); it != probabilitiesMap.end()) {
        double probability = it->second;
        if (rand() / static_cast<double>(RAND_MAX) < probability) {
            std::cout << "Selected attack: " << type << std::endl;
            return;
        }
    }
