const express = require('express');
const app = express();
const cors = require('cors');
const axios = require('axios');
const crypto = require('crypto');
const { v4: uuidv4 } = require('uuid');

// Payment Gateway API Endpoints
const paymentGateways = [
  {
    name: 'Gateway A',
    apiEndpoint: 'https://api.gateway-a.com/transactions',
  },
  {
    name: 'Gateway B',
    apiEndpoint: 'https://api.gateway-b.com/transactions',
  },
  // Add more gateways...
];

// Third-party services for currency conversion and fraud detection
const currencyConverter = axios.create({
  baseURL: 'https://api.currencyconverter.net/api/v2/',
});

const fraudDetector = axios.create({
  baseURL: 'https://api.frauddetector.com/api/v1/',
});

// Load balancing strategy
function getGateway() {
  const gatewayIndex = Math.floor(Math.random() * paymentGateways.length);
  return paymentGateways[gatewayIndex].apiEndpoint;
}

// Transaction processing and refund function
app.post('/transactions', (req, res) => {
  const transactionId = uuidv4();
  const { amount, currency } = req.body;

  // Convert currency to USD using third-party service
  const usdAmount = axios
    .get(`https://api.currencyconverter.net/api/v2/${currency}/USD`)
    .then((response) => response.data.rates.USD * amount)
    .catch((error) => {
      console.error(error);
      res.status(500).send({ message: 'Error converting currency' });
    });

  // Process transaction using selected payment gateway
  const gatewayEndpoint = getGateway();
  axios
    .post(gatewayEndpoint, { amount: usdAmount, transactionId })
    .then((response) => {
      console.log(`Transaction ${transactionId} processed successfully`);
      res.send({ message: 'Transaction processed successfully' });
    })
    .catch((error) => {
      console.error(error);
      res.status(500).send({ message: 'Error processing transaction' });
    });

  // Refund function
  app.post('/refund', (req, res) => {
    const { transactionId } = req.body;
    axios
      .post(getGateway(), { amount: usdAmount, transactionId })
      .then((response) => {
        console.log(`Refund for transaction ${transactionId} successful`);
        res.send({ message: 'Refund successful' });
      })
      .catch((error) => {
        console.error(error);
        res.status(500).send({ message: 'Error processing refund' });
      });
  });

// Error handling and logging
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send({ message: 'Internal Server Error' });
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Server started on port 3000');
});
