// Function to free memory allocated by create_and_populate_nfaapi_crc_indication_list
void free_nfaapi_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T** indication_list, int num_ue) {
    for (int i = 0; i < num_ue; i++) {
        if (indication_list[i]) {
            free(indication_list[i]);
            indication_list[i] = NULL;
        }
    }

