#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <string>
#include <map>
#include <memory>

// Forward declaration of worker class
class Worker;

// Load balancer class
class LoadBalancer {
public:
    LoadBalancer(size_t numWorkers) : workers_(numWorkers), queue_() {}

    template<typename T>
    void push(T&& task) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(std::forward<T>(task));
    }

    void start() {
        for (size_t i = 0; i < workers_; ++i) {
            workerThreads_.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex_);
                    if (queue_.empty()) {
                        condition_.wait(lock);
                    }
                    auto task = queue_.front();
                    queue_.pop();
                    lock.unlock();
                    task();
                }
            });
        }
    }

    ~LoadBalancer() {
        for (auto& thread : workerThreads_) {
            thread.join();
        }
    }

private:
    size_t workers_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::function<void()>> queue_;
    std::vector<std::thread> workerThreads_;
};

// Worker class
