#include <future>
#include <string>
#include <fstream>

class DiskIORequest {
public:
    std::string file_path;
    char operation; // 'r' for read, 'w' for write
    int size;

    DiskIORequest(const std::string& path, char op, int sz) 
        : file_path(path), operation(op), size(sz) {}
};

class DiskIOManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<DiskIORequest> request_queue;
    std::map<std::string, int> cache;
    int cache_size;

public:
    DiskIOManager(int max_cache_size) : cache_size(max_cache_size) {}

    void manage_disk_io_requests(const DiskIORequest& req) {
        // Handle requests in a separate thread
        auto worker = std::thread([this, &req]() {
            process_request(req);
        });
        worker.detach();
    }

private:
    void process_request(const DiskIORequest& req) {
        std::unique_lock<std::mutex> lock(mtx);

        // Check if the file is in cache
        if (cache.find(req.file_path) != cache.end()) {
            // Serve from cache
            serve_from_cache(req);
            return;
        }

        // Add request to queue and notify main thread
        request_queue.push(req);
        cv.notify_one();
    }

    void serve_from_cache(const DiskIORequest& req) {
        // Read/Write data from cache
        std::ifstream file(req.file_path, std::ios::binary | std::ios::in | std::ios::ate);
        if (file.is_open()) {
            // Handle read/write operation
            if (req.operation == 'r') {
                // Read data from file
                char* buffer = new char[req.size];
                file.read(buffer, req.size);
                delete[] buffer;
            } else {
                // Write data to file
                file.seekg(0);
                file.write("Data", req.size);
            }
        }
    }

    void handle_queue() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);

            cv.wait(lock, [this] { return !request_queue.empty(); });

            DiskIORequest req = request_queue.front();
            request_queue.pop();

            process_request(req);
        }
    }

};

int main() {
    DiskIOManager disk_io_manager(10000); // 10 MB cache size

    while (true) {
        std::string file_path;
        char operation; // 'r' for read, 'w' for write
        int size;

        // Get input from user or API call
        // ...

        DiskIORequest req(file_path, operation, size);
        disk_io_manager.manage_disk_io_requests(req);

        // Handle errors and exceptions
    }

    return 0;
}
```']

