    StreamProcessor(int numThreads) : stop(false), threads(numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] {
                processStream();
            });
        }
    }

    ~StreamProcessor() {
        std::unique_lock<std::mutex> lock(mutex);
        stop = true;
        cv.notify_one();
