};

class PacketScheduler {
private:
    std::priority_queue<CellularPacket*, std::vector<CellularPacket*>, [](const CellularPacket* a, const CellularPacket* b) {
        return a->TransmissionTimingOffset > b->TransmissionTimingOffset; // Prioritize critical packets over less important ones
    }> packetPriorityQueue;

public:
    void schedulePackets() {
        while (!packetPriorityQueue.empty()) {
            CellularPacket* packet = packetPriorityQueue.top();
            packetPriorityQueue.pop();
            // Schedule packet processing logic here
        }
    }

    void addPacket(CellularPacket* packet) {
        packetPriorityQueue.push(packet);
    }
};

int main() {
