class HTTP_RESPONSE_MESSAGE {
public:
    // Constructor, destructor and necessary member functions
};

class HTTP_RESPONSE_MANAGER {
private:
    std::map<std::string, std::shared_ptr<HTTP_RESPONSE_MESSAGE>> responseTemplates;
    std::mutex templateMutex;
    std::condition_variable templateCondition;

    std::queue<std::pair<int, std::unique_ptr<HTTP_RESPONSE_MESSAGE>>> requestQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;

    // External REST API client for logging and analytics
    std::string apiKey;

    int concurrentRequestLimit = 1000; // configurable limit

public:
    HTTP_RESPONSE_MANAGER(const std::string& apiKey) : apiKey(apiKey) {}

    void addResponseTemplate(const std::string& key, const std::shared_ptr<HTTP_RESPONSE_MESSAGE>& response) {
        std::unique_lock<std::mutex> lock(templateMutex);
        responseTemplates[key] = response;
        lock.unlock();
        templateCondition.notify_all();
    }

    std::shared_ptr<HTTP_RESPONSE_MESSAGE> getResponseTemplate(const std::string& key) {
        std::unique_lock<std::mutex> lock(templateMutex);
        while (responseTemplates.find(key) == responseTemplates.end()) {
            templateCondition.wait(lock);
        }
        return responseTemplates[key];
    }

    void enqueueRequest(int requestID, const std::unique_ptr<HTTP_RESPONSE_MESSAGE>& response) {
        std::unique_lock<std::mutex> lock(queueMutex);
        requestQueue.push({requestID, response});
        if (requestQueue.size() >= concurrentRequestLimit) {
            queueCondition.notify_all();
        }
    }

    void dequeueRequest() {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (requestQueue.empty()) {
            queueCondition.wait(lock);
        }
        requestQueue.pop();
    }

    // Hybrid logging strategy with configurable thresholds
    void logRequest(int requestID, const HTTP_RESPONSE_MESSAGE& response) {
        if (requestID % 1000 == 0 && response.get().errorCode != 0) { // configurable threshold
            // Log to local file
            std::cout << "Local Log: Request " << requestID << " failed with error code " << response.get().errorCode << std::endl;
        } else if (requestID % 10000 == 0 && response.get().errorCode != 0) { // configurable threshold
            // Send to external API for analytics and logging
            std::cout << "Remote Log: Request " << requestID << " failed with error code " << response.get().errorCode << std::endl;
        }
    }

    void start() {
        std::thread producer([&]() {
            while (true) {
                dequeueRequest();
                // Process requests and send responses
                // ...
            }
        });

        std::thread consumer([&]() {
            while (true) {
                enqueueRequest(requestID, response);
                // Send responses and update queue
                // ...
            }
        });

        producer.join();
        consumer.join();
    }

    ~HTTP_RESPONSE_MANAGER() {
        // Release resources
    }
};
