func main() {
	// Create a new kafka producer
	p, err := kafka.NewProducer(&kafka.ConfigMap{
		"bootstrap.servers": "localhost:9092",
		"client.id":         "my-producer",
	})

	if err != nil {
		log.Fatal(err)
	}

	// Send a message to the topic 'my_topic'
	topicPartitions, err := p.ProducePartition("my_topic", 0)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Create a producer record with topic name and message value
	record := &kafka.Message{
		TopicPartition: *topicPartitions,
		Value:          []byte("Hello, Kafka!"),
	}

	// Send the producer record to Kafka
	err = p.Produce(record)
	if err != nil {
		fmt.Println(err)
		return
	}
}

