#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <map>
#include <mutex>
#include <condition_variable>
#include <atomic>

class MessageBroker {
public:
    MessageBroker(int numThreads) : queue_(std::make_shared<std::queue<Message>>()), consumers_(numThreads), stopped_(false) {}

    void start() {
        for (int i = 0; i < consumers_.size(); ++i) {
            std::thread(consumerThread, this).detach();
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stopped_ = true;
        }
        queue_->empty();
    }

    void send(const Message& message) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopped_) {
                return; // Broker is stopped
            }
        }
        queue_->push(message);
    }

private:
    std::shared_ptr<std::queue<Message>> queue_;
    std::vector<std::thread> consumers_;
    std::atomic<bool> stopped_;
    std::mutex mutex_;

    void consumerThread(MessageBroker* broker) {
        while (true) {
            Message message;
            {
                std::unique_lock<std::mutex> lock(broker->mutex_);
                while (!broker->stopped_ && queue_->empty()) {
                    condition_.wait(lock);
                }
                if (broker->stopped_) {
                    return; // Broker is stopped
                }
                message = queue_->front();
                queue_->pop();
            }
            processMessage(message);
        }
    }

    void processMessage(const Message& message) {
        // Process the message here
    }
};

class Message {
public:
    Message(std::string sender, std::string recipient, int priority, std::string content)
        : sender_(sender), recipient_(recipient), priority_(priority), content_(content) {}

    std::string getSender() const { return sender_; }
    std::string getRecipient() const { return recipient_; }
    int getPriority() const { return priority_; }
    std::string getContent() const { return content_; }

private:
    std::string sender_;
    std::string recipient_;
    int priority_;
    std::string content_;
};

int main() {
    MessageBroker broker(5);
    broker.start();

    // Send messages
    for (int i = 0; i < 10000; ++i) {
        Message message("Client1", "Server1", 1, "Hello");
        broker.send(message);
    }

    // Stop the broker
    broker.stop();

    return 0;
}
```

