        m_frameBuffer(std::vector<uint8_t>(m_bufferCapacity)) {}

    // Start the video stream processor
    void start() {
        std::thread decodeThread(&VideoStreamProcessor::decodeFrames, this);
        std::thread analyzeThread(&VideoStreamProcessor::analyzeFrames, this);

        // Start the threads
        decodeThread.detach();
        analyzeThread.detach();
    }

