app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///forms.db"
db = SQLAlchemy(app)

class Form(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    fields = db.relationship("Field", backref="form")

class Field(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    form_id = db.Column(db.Integer, db.ForeignKey("form.id"))
    name = db.Column(db.String(50), nullable=False)
    type = db.Column(db.String(20), nullable=False)

class Role(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50), nullable=False)

class Tenant(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    roles = db.relationship("Role", secondary="tenant_role")

@app.route("/forms/<int:form_id>", methods=["GET"])
def get_form(form_id):
    form = Form.query.get(form_id)
    if not form:
        return jsonify({"error": "Form not found"}), 404
    return jsonify([{"name": field.name, "type": field.type} for field in form.fields])

@app.route("/forms/<int:form_id>/fields", methods=["POST"])
def create_field(form_id):
    form = Form.query.get(form_id)
    if not form:
        return jsonify({"error": "Form not found"}), 404
    new_field = Field(name=request.json["name"], type=request.json["type"], form=form)
    db.session.add(new_field)
    db.session.commit()
    return jsonify({"message": "Field created successfully"})

@app.route("/forms/<int:form_id>/fields/<int:field_id>", methods=["PUT"])
def update_field(form_id, field_id):
    form = Form.query.get(form_id)
    if not form:
        return jsonify({"error": "Form not found"}), 404
    field = Field.query.get(field_id)
    if not field or field.form_id != form_id:
        return jsonify({"error": "Field not found"}), 404
    field.name = request.json["name"]
    db.session.commit()
    return jsonify({"message": "Field updated successfully"})

@app.route("/forms/<int:form_id>/roles", methods=["GET"])
def get_roles(form_id):
    form = Form.query.get(form_id)
    if not form:
        return jsonify({"error": "Form not found"}), 404
    return jsonify([{"name": role.name} for role in form.roles])

@app.route("/forms/<int:form_id>/roles/<int:role_id>", methods=["GET"])
def get_role(form_id, role_id):
    form = Form.query.get(form_id)
    if not form:
        return jsonify({"error": "Form not found"}), 404
    role = Role.query.get(role_id)
    if not role or role not in form.roles:
        return jsonify({"error": "Role not found"}), 404
    return jsonify({"name": role.name})

if __name__ == "__main__":
    app.run(debug=True)
