```java
// Modular Event Stream Library (MESL)

import java.util.*;
import java.io.*;

public class MESL {
    // Adaptive In-Memory Event Buffer
    public static class EventBuffer {
        private Queue<Event> buffer;
        private long retentionPolicy;

        public EventBuffer(long retentionPolicy) {
            this.buffer = new LinkedList<>();
            this.retentionPolicy = retentionPolicy;
        }

        public void put(Event event) {
            if (buffer.size() >= retentionPolicy) {
                // Handle buffer overflow
                buffer.poll();
            }
            buffer.add(event);
        }

        public Event get() {
            return buffer.poll();
        }
    }

    // Flexible Event Transformation Pipeline
    public static interface Transformer {
        void transform(Event event);
    }

    public static class TransformationPipeline {
        private List<Transformer> transformers;

