// Doubly linked list to manage NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

// Initialize the doubly linked list
List* init_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Insert a new node into the doubly linked list by RNTI
void insert_list(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the doubly linked list by RNTI
void remove_list(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (node == list->head) {
        list->head = node->next;
    }
    if (node == list->tail) {
        list->tail = node->prev;
    }
    node->prev->next = node->next;
    node->next->prev = node->prev;
    free(node);
    pthread_mutex_unlock(&list->lock);
}

// Search for a node in the doubly linked list by RNTI
Node* search_list(List* list, uint16_t RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Free the doubly linked list
void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
