// dialog-updater.js
import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, EMPTY } from 'rxjs';
import { retryWhen, tap, mergeMap } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class DialogUpdaterService {

  private apiUrl = 'https://your-api.com/api/v1/dialogs'; // Update with your API URL
  private apiToken = 'your-token-here'; // Update with your API token
  private cache = {};

  constructor(private http: HttpClient) { }

  updateDialogFields(resourceId: string, url: string): Observable<any> {
    return this.http.get(this.apiUrl + '/' + resourceId + '?url=' + url, {
      headers: new HttpHeaders({
        Authorization: 'Bearer ' + this.apiToken
      }),
      observe: 'response'
    })
    .pipe(
      retryWhen(errors => errors.pipe(delay(5000))), // Retry failed requests after 5 seconds
      tap(response => console.log('Fetching data for dialog fields...')),
      mergeMap(response => {
        const fields = response.body.fields;
        return this.updateFields(fields);
      }),
      tap(() => console.log('Dialog fields updated successfully!'))
    );
  }

  private updateFields(fields: any[]): Observable<any> {
    if (!fields || !fields.length) {
      return EMPTY; // Return an empty observable if no fields are provided
    }

    const fieldUpdates = fields.map(field => {
      // Update the dialog field values here...
      return { [field.name]: field.value };
    });

    // Perform asynchronous updates for each field
    return Observable.zip(...fieldUpdates.map(update => {
      return this.http.patch('https://your-api.com/api/v1/dialogs/' + resourceId, update).pipe(
        retryWhen(errors => errors.pipe(delay(5000))), // Retry failed requests after 5 seconds
        tap(() => console.log(`Updated field ${update.name} successfully!`)),
        catchError(error => {
          console.error('Error updating field:', error);
          return EMPTY;
        })
      );
    }));
  }
}

// Example usage:
import { Component, OnInit } from '@angular/core';
import { DialogUpdaterService } from './dialog-updater.service';

@Component({
  selector: 'app-example',
  template: '<p>Example component</p>'
})
export class ExampleComponent implements OnInit {

  constructor(private dialogUpdater: DialogUpdaterService) {}

  ngOnInit(): void {
    const resourceId = 'your-resource-id';
    const url = 'https://example.com/dialog-url';
    this.dialogUpdater.updateDialogFields(resourceId, url).subscribe();
  }
}
```

