class Graph {
public:
    using Edge = std::pair<int, int>;
    using Node = int;

    class BFS {
    public:
        void operator()(const Node& start) const {
            std::map<Node, bool> visited;
            std::set<Node> nodesToVisit;
            nodesToVisit.insert(start);
            visited[start] = true;

            while (!nodesToVisit.empty()) {
                auto node = *nodesToVisit.begin();
                nodesToVisit.erase(nodesToVisit.begin());

                // Process the node
                std::cout << "Visiting node: " << node << std::endl;
                for (const Edge& edge : graph_[node]) {
                    if (!visited[std::get<1>(edge)]) {
                        nodesToVisit.insert(std::get<1>(edge));
                        visited[std::get<1>(edge)] = true;
                    }
                }
            }
        }

    private:
        const std::map<Node, std::set<Edge>>& graph_;
    };

    class DFS {
    public:
        void operator()(const Node& start) const {
            std::stack<Node> nodesToVisit;
            nodesToVisit.push(start);

            while (!nodesToVisit.empty()) {
                auto node = nodesToVisit.top();
                nodesToVisit.pop();

                // Process the node
                std::cout << "Visiting node: " << node << std::endl;
                for (const Edge& edge : graph_[node]) {
                    nodesToVisit.push(std::get<1>(edge));
                }
            }
        }

    private:
        const std::map<Node, std::set<Edge>>& graph_;
    };

private:
    std::map<Node, std::set<Edge>> graph_;

public:
    void addEdge(const Node& from, const Node& to) {
        graph_[from].insert(Edge(from, to));
        graph_[to].insert(Edge(to, from));
    }

    void startBFS(const Node& start) {
        BFS bfs;
        bfs(start);
    }

    void startDFS(const Node& start) {
        DFS dfs;
        dfs(start);
    }
};

int main() {
    Graph graph;

    // Adding edges
    graph.addEdge(0, 1);
    graph.addEdge(0, 2);
    graph.addEdge(1, 3);
    graph.addEdge(2, 4);

    // Performing BFS and DFS
    graph.startBFS(0);
    graph.startDFS(0);

    return 0;
}
