    void dfs(const std::string& startNode, const std::function<void(GraphNode*)>& callback) {
        std::stack<std::shared_ptr<GraphNode>> stack;
        std::set<GraphNode*> visited;

        auto current = getGraphNode(startNode);
        if (current != nullptr) {
            stack.push(current);
            visited.insert(current.get());
        }

        while (!stack.empty()) {
            auto node = stack.top();
            stack.pop();

            callback(node.get());

            for (auto& neighbor : node->neighbors) {
                if (visited.find(neighbor.get()) == visited.end()) {
                    stack.push(neighbor);
                    visited.insert(neighbor.get());
                }
            }
        }
    }

private:
    std::unordered_map<std::string, std::shared_ptr<GraphNode>> graph;

    std::shared_ptr<GraphNode> getGraphNode(const std::string& id) {
        if (graph.find(id) == graph.end()) {
            // Handle edge case where node not found
            return nullptr;
        }

        return graph.at(id);
    }
};
```']

