    int count; // Number of bundles in the system
} ResourceManager;

// Function to create a new resource bundle
ResourceBundle* createResourceBundle(int id, char* name) {
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->id = id;
    bundle->name = strdup(name);
    bundle->data = NULL; // Initialize data as null
    return bundle;
}

// Function to add a resource bundle to the system
void addResourceBundle(ResourceManager* manager, ResourceBundle* bundle) {
    pthread_mutex_lock(&manager->lock); // Acquire the lock

    // Add the bundle to the linked list and increment the count
    bundle->next = manager->bundles;
    manager->bundles = bundle;
    manager->count++;

    pthread_mutex_unlock(&manager->lock); // Release the lock
}

// Function to retrieve a resource bundle from the system
ResourceBundle* getResourceBundle(ResourceManager* manager, int id) {
    pthread_mutex_lock(&manager->lock); // Acquire the lock

    // Traverse the linked list to find the requested bundle
    ResourceBundle* current = manager->bundles;
    while (current && current->id != id) {
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock); // Release the lock

    return current;
}

// Function to remove a resource bundle from the system
void removeResourceBundle(ResourceManager* manager, int id) {
    pthread_mutex_lock(&manager->lock); // Acquire the lock

    // Traverse the linked list to find and remove the requested bundle
    ResourceBundle** previous = &manager->bundles;
    while (*previous && (*previous)->id != id) {
        previous = &(*previous)->next;
    }

    if (*previous) {
        *previous = (*previous)->next;
        manager->count--;
    }

    pthread_mutex_unlock(&manager->lock); // Release the lock
}

// Function to synchronize resource bundles across nodes in a distributed system
void syncResourceBundles(ResourceManager* manager, List* remoteBundles) {
    pthread_mutex_lock(&manager->lock); // Acquire the lock

    // Iterate over the remote bundles and update local copies if necessary
    for (List* current = remoteBundles; current; current = current->next) {
        ResourceBundle* bundle = getResourceBundle(manager, ((ResourceBundle*)current->data)->id);
        if (!bundle || memcmp(bundle, (ResourceBundle*)current->data, sizeof(ResourceBundle))) {
            // Update the local copy with the new data
            bundle->data = strdup(((ResourceBundle*)current->data)->data);
        }
    }

    pthread_mutex_unlock(&manager->lock); // Release the lock
}

// Function to release resources and cleanup
void freeResourceManager(ResourceManager* manager) {
    pthread_mutex_lock(&manager->lock); // Acquire the lock

    // Iterate over the linked list and free each bundle
    ResourceBundle* current = manager->bundles;
    while (current) {
        ResourceBundle* next = current->next;
        free(current);
        current = next;
    }

    manager->count = 0;

    pthread_mutex_unlock(&manager->lock); // Release the lock

    free(manager);
}

// Define a structure to represent a list of resource bundles
typedef struct List {
    ResourceBundle* data;
    struct List* next;
} List;
