}

async fn process_payment_transaction(transaction: &PaymentTransaction) -> Result<(), reqwest::Error> {
    let gateways = vec![
        StripeGateway { api_key: "stripe_api_key".to_string() },
        PayPalGateway { client_id: "paypal_client_id".to_string(), client_secret: "paypal_client_secret".to_string() },
        BraintreeGateway { merchant_id: "braintree_merchant_id".to_string(), public_key: "braintree_public_key".to_string() },
    ];

    for gateway in gateways {
        match process_payment(&transaction, &gateway).await {
            Ok(_) => return Ok(()),
            Err(err) => eprintln!("Error processing payment through {}: {}", gateway.name(), err),
        }
    }

    Err(reqwest::Error::new("No gateway available"))
}

async fn process_payment(transaction: &PaymentTransaction, gateway: &dyn PaymentGateway) -> Result<(), reqwest::Error> {
