    PacketManager* pm = (PacketManager*) malloc(sizeof(PacketManager));
    pm->packets = (DataPacket*) calloc(initial_capacity, sizeof(DataPacket));
    pm->num_packets = 0;
    pm->capacity = initial_capacity;
    pthread_mutex_init(&pm->mutex, NULL);
    return pm;
}

// Add a new DataPacket to the collection
void packet_manager_add(PacketManager* pm, DataPacket* packet) {
    pthread_mutex_lock(&pm->mutex);
    if (pm->num_packets >= pm->capacity) {
        // resize the packets array
        pm->packets = (DataPacket*) realloc(pm->packets, (pm->capacity * 2 + 1) * sizeof(DataPacket));
        pm->capacity *= 2;
    }
    memcpy(&pm->packets[pm->num_packets], packet, sizeof(DataPacket));
    pm->num_packets++;
    pthread_mutex_unlock(&pm->mutex);
}

