import hashlib

class MD5FileHasher:
    def __init__(self):
        self.md5_hash = hashlib.md5()

    def calculate_hash(self, file_path):
        with open(file_path, 'rb') as file:
            chunk_size = 4096
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                self.md5_hash.update(chunk)

        return self.md5_hash.hexdigest()

# Example usage
