type EventIngestionService struct {
	ctx context.Context
	bt *bigtable.Client
	runtime int64 // retention period in seconds
}

func NewEventIngestionService(ctx context.Context, bt *bigtable.Client, runtime int64) (*EventIngestionService, error) {
	return &EventIngestionService{
		ctx: ctx,
		bt: bt,
		runtime: runtime,
	}, nil
}

func (eis *EventIngestionService) AddEvent(event CelluarNetworkEvent) error {
	_, err := eis.bt.Put(eis.ctx, "events", fmt.Sprintf("%d", event.EventID), []byte(event.ToString()))
	return err
}

func (eis *EventIngestionService) GetEvents(startTime int64, endTime int64) ([]CelluarNetworkEvent, error) {
	it := eis.bt.NewScanIterator(eis.ctx, "events", &bigtable.Scan{
		Ranges: []*bigtable.Range{&bigtable.Range{
			StartRow: []byte(fmt.Sprintf("%d:", startTime)),
			EndRow:   []byte(fmt.Sprintf("%d:", endTime)),
		}},
	})
	events := make([]CelluarNetworkEvent, 0)
	for {
		row := it.Next()
		if row == nil {
			break
		}
		eventStr := string(row.Data)
		event := CelluarNetworkEvent{}
		json.Unmarshal([]byte(eventStr), &event)
		events = append(events, event)
	}
	return events, nil
}

func (eis *EventIngestionService) RemoveOldEvents() error {
	now := time.Now().UnixNano()
	it := eis.bt.NewScanIterator(eis.ctx, "events", &bigtable.Scan{
		Ranges: []*bigtable.Range{&bigtable.Range{
			StartRow: []byte(fmt.Sprintf("%d:", now-eis.runtime*1000000)),
			EndRow:   []byte{},
		}},
	})
	for {
		row := it.Next()
		if row == nil {
			break
		}
		err := eis.bt.Delete(eis.ctx, "events", row.Key)
		if err != nil {
			return err
		}
	}
	return nil

