use std::path::{Path, PathBuf};

fn create_dir_and_set_env(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = get_or_create_dir(dir_name)?;
    set_env_var("NEW_DIR", &dir_path.to_string_lossy().to_string())?;

    Ok(())
}

fn get_or_create_dir(dir_name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let path = Path::new(dir_name);
    if path.exists() {
        Ok(path.to_path_buf())
    } else {
        fs::create_dir_all(&path)?;
        Ok(path.to_path_buf())
    }
}

fn set_env_var(var: &str, value: &str) -> Result<(), Box<dyn std::error::Error>> {
    let _ = env::set_var(var, value);
    Ok(())
}
