class DataProcessor {
public:
    DataProcessor() : stopped(false) {}

    void start() {
        thread_ = std::thread(&DataProcessor::run, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stopped = true;
        }
        cv_.notify_one();
        if (thread_.joinable()) {
            thread_.join();
        }
    }

private:
    void run() {
        while (!stopped) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return stopped; });

            // Process data here
            std::cout << "Processing data..." << std::endl;
        }
    }

    std::thread thread_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stopped;
};

int main() {
    DataProcessor processor;
    processor.start();

    // Simulate data processing
    for (int i = 0; i < 10; ++i) {
        processor.stop();
        std::this_thread::sleep_for(std::chrono::seconds(1));
        processor.start();
    }

    return 0;
}
