import org.springframework.messaging.Message;
import org.springframework.messaging.MessagingException;
import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.model.SendMessageRequest;

@SpringBootApplication
@EnableIntegration
public class TimeSeriesMicroserviceApplication {

    public static void main(String[] args) {
        SpringApplication.run(TimeSeriesMicroserviceApplication.class, args);
    }

    @Bean
    public InboundGateway inboundGateway() {
        return new InboundGateway("amqp://localhost/time_series_queue");
    }

    @Bean
    public AmazonSQS amazonSQS() {
        return new AmazonSQSClient();
    }

    @Bean
    public SendMessageRequest send_message_request() {
        return new SendMessageRequest()
                .withQueueUrl("https://sqs.us-west-2.amazonaws.com/123456789012/time_series_queue")
                .withMessageBody(new String("{\"time_series\": [1, 2, 3]}"));
    }

    @Bean
    public org.springframework.messaging.MessageChannel message_channel() {
        return new org.springframework.messaging.support.GenericMessageChannel();
    }

    @Bean
    public org.springframework.messaging.MessageHandler message_handler(Message message) throws MessagingException {
        return (messageChannel, message) -> System.out.println(message.toString());
    }

    @Bean
    public org.springframework.integration.channel.DirectChannel direct_channel() {
        return new org.springframework.integration.channel.DirectChannel();
    }

    @Bean
    public org.springframework.integration.core.Pair pair(Pair p) {
        return p;
    }

    @Bean
    public List<org.springframework.messaging.Message> messages(List<Message> list) {
        return list;
    }
}
