from typing import List
import json
import redis
import kubernetes
import logging

# Define a logging configuration
logging.basicConfig(level=logging.INFO)

class LogProcessor:
    def __init__(self, pipeline_name: str):
        self.pipeline_name = pipeline_name
        self.redis_client = redis.Redis(host='localhost', port=6379, db=0)
        self.k8s_api = kubernetes.client.V1Api()

    # Define a stage for deduplication
    def deduplicate(self, logs: List[dict]) -> List[dict]:
        unique_logs = set()
        processed_logs = []
        for log in logs:
            if log not in unique_logs:
                unique_logs.add(log)
                processed_logs.append(log)
        return processed_logs

    # Define a stage for filtering
    def filter(self, logs: List[dict], filters: List[dict]) -> List[dict]:
        filtered_logs = []
        for log in logs:
            if all(all(filter.get(k) == v for k, v in filter.items()) for filter in filters):
                filtered_logs.append(log)
        return filtered_logs

    # Define a stage for transformation
    def transform(self, logs: List[dict], transformations: List[dict]) -> List[dict]:
        transformed_logs = []
        for log in logs:
            transformed_log = {}
            for key, value in log.items():
                if any(key == k and value == v for k, v in transformation.items()) for transformation in transformations):
                    transformed_log[key] = value
                else:
                    transformed_log[key] = f"{value}_{key}"
            transformed_logs.append(transformed_log)
        return transformed_logs

    # Define a stage for storage
    def store(self, logs: List[dict], storage_uri: str) -> None:
        with open(storage_uri, 'w') as f:
            json.dump(logs, f)

    # Define the pipeline flow
    def process(self):
        logs = []
        while True:
            log = self.redis_client.brpop('logs')
            if not log:
                break
            logs.append(json.loads(log[1]))

        deduplicated_logs = self.deduplicate(logs)
        filtered_logs = self.filter(deduplicated_logs, [{'level': 'INFO'}, {'category': 'my_category'}])
        transformed_logs = self.transform(filtered_logs, [{'key': 'value'}, {'field': 'value'}])
        self.store(transformed_logs, 'logs.json')

    # Define the pipeline flow with Kubernetes
    def process_with_k8s(self):
        logs = []
        while True:
            log = self.k8s_api.read_namespaced_pod_log('my-pod', 'default')
            if not log:
                break
            logs.append(json.loads(log))

        deduplicated_logs = self.deduplicate(logs)
        filtered_logs = self.filter(deduplicated_logs, [{'level': 'INFO'}, {'category': 'my_category'}])
        transformed_logs = self.transform(filtered_logs, [{'key': 'value'}, {'field': 'value'}])
        self.store(transformed_logs, 'logs.json')

    # Start the pipeline
    def start(self):
        if self.pipeline_name == 'k8s':
            self.process_with_k8s()
        else:
            self.process()

if __name__ == '__main__':
    processor = LogProcessor('my_pipeline')
    processor.start()

