        ObjectMapper mapper = new ObjectMapper();
        ObjectNode configurationObject = mapper.readValue(Files.newInputStream(Paths.get(configPath)), ObjectNode.class);
        // configure module based on JSON config
    }

    public void updateCache(String key, Object value) {
