    $this->edgeLocations[] = 'ap-southeast-2';

    $this->originServers[] = 'origin-us-west-1';
    $this->originServers[] = 'origin-eu-west-3';
  }

  public function handleRequest($request) {
    // Determine edge location closest to user
    $closestEdgeLocation = findClosestEdgeLocation($request->getUserIP());
    $edgeLocation = array_shift($this->edgeLocations);

    if ($closestEdgeLocation === $edgeLocation) {
      // Cache hit, serve from edge location
      return cacheHitResponse();
    } else {
      // Cache miss, route to origin server
      return cacheMissResponse($request);
    }
  }

  public function cacheHitResponse() {
    // Serve cached content from edge location
    return new CachedContentResponse();
