    new_state_list->next = NULL;

    // Validate state-related resources and implement retry mechanism
    int retries = 0;
    while (retries < 3) {
        if (validate_resources()) {
            break; // Success, exit loop
        }
        else {
            // Log error and wait before retrying
            log_error("Retry attempt %d: Error validating resources.", ++retries);
            sleep(2); // Wait for 2 seconds
        }
    }

    // Store the resulting state list in cloud storage service
