async function loadAndRegisterWidgets(widgets) {
  const registeredWidgets = [];
  let errors = [];

  for (const widget of widgets) {
    try {
      const { render } = await import(`./widgets/${widget.module}.js`);
      registeredWidgets.push({ ...widget, render });
    } catch (error) {
      console.error(`Error loading widget: ${widget.module}`, error);
      errors.push(error);
    }
  }

  if (errors.length > 0) {
    throw new Error(`Failed to load ${errors.map((error) => error.name).join(', ')}`);
  }

  return Promise.all(registeredWidgets.map((widget) => widget.render()));
}
