#include <iostream>
#include <map>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

// Node struct representing a node in the network
struct Node {
    std::string id;
    int cpu;
    int memory;
};

// Resource management system class
class ResourceManager {
public:
    ResourceManager() {
        // Initialize node map and lock for thread-safe access
        nodes_.clear();
        lock_ = std::mutex{};
        cond_ = std::condition_variable{};
    }

    // Add a new node to the network
    void addNode(Node& node) {
        // Lock access to ensure thread safety
        std::unique_lock<std::mutex> lock(lock_);

        nodes_[node.id] = node;

        // Notify waiting threads that a new node has been added
        cond_.notify_all();
    }

    // Remove a node from the network
    void removeNode(std::string& id) {
        // Lock access to ensure thread safety
        std::unique_lock<std::mutex> lock(lock_);

        if (nodes_.find(id) != nodes_.end()) {
            nodes_.erase(id);
        }

        // Notify waiting threads that a node has been removed
        cond_.notify_all();
    }

    // Allocate resources to a node based on demand and availability
    void allocateResources(std::string& id, int cpuReq, int memoryReq) {
        // Lock access to ensure thread safety
        std::unique_lock<std::mutex> lock(lock_);

        if (nodes_.find(id) != nodes_.end()) {
            Node& node = nodes_[id];

            // Check if the requested resources are available
            if (node.cpu >= cpuReq && node.memory >= memoryReq) {
                // Allocate resources to the node
                node.cpu -= cpuReq;
                node.memory -= memoryReq;

                // Notify waiting threads that resources have been allocated
                cond_.notify_all();
            }
        }
    }

    // Deallocate resources from a node based on demand and availability
    void deallocateResources(std::string& id, int cpuFree, int memoryFree) {
        // Lock access to ensure thread safety
        std::unique_lock<std::mutex> lock(lock_);

        if (nodes_.find(id) != nodes_.end()) {
            Node& node = nodes_[id];

            // Check if the requested resources are available
            if (node.cpu >= cpuFree && node.memory >= memoryFree) {
                // Deallocate resources from the node
                node.cpu += cpuFree;
                node.memory += memoryFree;

                // Notify waiting threads that resources have been deallocated
                cond_.notify_all();
            }
        }
    }

private:
    std::map<std::string, Node> nodes_;
    std::mutex lock_;
    std::condition_variable cond_;
};

int main() {
    ResourceManager rm;

    Node node1 = {"node1", 4, 8};
    Node node2 = {"node2", 8, 16};
    Node node3 = {"node3", 2, 4};

    rm.addNode(node1);
    rm.addNode(node2);
    rm.addNode(node3);

    rm.allocateResources("node1", 2, 4);
    rm.deallocateResources("node1", 1, 2);

    return 0;
}

