import axios from 'axios';
import { debounce } from 'lodash';
import { FilteredElementDatabase } from './database.js';

class AsyncDOMProcessor {
  constructor(apiUrl, selector) {
    this.apiUrl = apiUrl;
    this.selector = selector;
    this.filteredElements = [];
    this.database = new FilteredElementDatabase();
    this.traversalTimer = null;

    this.getDOMTree = debounce(() => {
      axios.get(this.apiUrl)
        .then(response => {
          const domTree = response.data;
          this.processDOMTree(domTree);
        })
        .catch(error => {
          console.error('Error retrieving DOM tree:', error);
        });
    }, 1000); // debounce to minimize requests
  }

  processDOMTree(domTree) {
    try {
      const filteredElements = [];

      (function traverse(node, selector) {
        if (!node) return;
        if (node.matches(selector)) filteredElements.push({ node, selector });

        Array.from(node.childNodes).forEach(child => {
          traverse(child, selector);
        });
      })(domTree.querySelector('body'), this.selector);

      this.filteredElements = filteredElements;
      this.updateDatabase();
    } catch (error) {
      console.error('Error processing DOM tree:', error);
    }
  }

  updateDatabase() {
    if (!this.filteredElements.length) return;

    this.traversalTimer = setTimeout(() => {
      try {
        this.database.put(this.filteredElements);
      } catch (error) {
        console.error('Error updating database:', error);
      } finally {
        clearTimeout(this.traversalTimer);
      }
    }, 500); // delay to minimize writes
  }

  startTraversal() {
    this.getDOMTree();
  }

  stopTraversal() {
    clearTimeout(this.traversalTimer);
  }
}

class FilteredElementDatabase {
  constructor() {
    this.elements = [];
  }

  put(elements) {
    this.elements = elements;
    // implement database persistence logic here
  }
}
