  // Resolve module dependencies and load the latest version
  const modules = await Promise.all(moduleList.map(async (moduleName) => {
    try {
      const moduleMetadata = await apiServices.find((service) => service.name === 'github').get(`https://api.github.com/repos/${moduleName}/metadata`);
      if (!moduleMetadata) return null;

      // Load the module and its dependencies
      const moduleCode = await fs.promises.readFile(path.join(moduleRepository, moduleName), 'utf8');
