    int i, size = 10; // Initial array size
    CellularPacket** packets = (CellularPacket**)malloc(size * sizeof(CellularPacket*));

    for (i = 0; i < size; i++) {
        packets[i] = (CellularPacket*)malloc(sizeof(CellularPacket));
    }

    // Example usage:
    for (i = 0; i < size; i++) {
        packets[i]->transmissionTimingOffset = i;
        packets[i]->timingAdvance = 2 * i;
        packets[i]->phy.phyFrame = "Some frame data";
    }

    // Dynamically resize the array
    size += 5;
    CellularPacket** newPackets = (CellularPacket**)realloc(packets, size * sizeof(CellularPacket*));

    for (i = size - 5; i < size; i++) {
        newPackets[i] = (CellularPacket*)malloc(sizeof(CellularPacket));
        // Initialize the new packets
    }

    free(packets);
    return 0;
}
