CREATE PROCEDURE [dbo].[GetEmployeeDetails]
    @SupervisorID int,
    @Department varchar(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @DepartmentData xml;
    DECLARE @EmployeeData table (Name varchar(100), City varchar(50), Address varchar(200));

    BEGIN TRY
        -- Retrieve employee data from relational database
        INSERT INTO @EmployeeData
        SELECT e.Name, e.City, e.Address
        FROM Employees e
        WHERE e.SupervisorID = @SupervisorID;

        -- Fetch department-specific data from external API
        SET @DepartmentData = 
        (SELECT *
         FROM [ExternalAPI].[dbo].[GetDepartmentData](@Department)
         FOR XML PATH(''), TYPE);

        -- Validate and reconcile data inconsistencies between database and API
        DECLARE @ValidationErrors table (Message varchar(200));
        IF EXISTS (SELECT * FROM @EmployeeData WHERE Name NOT IN (SELECT x.Name FROM @DepartmentData.nodes('/department/employee') AS t(x).Name))
            INSERT INTO @ValidationErrors VALUES ('Inconsistent data found');

        -- Handle null and inconsistent data gracefully
        IF @@ROWCOUNT = 0
            RAISERROR('No data found', 16, 1);
        ELSE
            SELECT e.*
            FROM @EmployeeData e;

        END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage nvarchar(4000), @ErrorSeverity int;
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @ErrorSeverity = ERROR_SEVERITY();

        -- Log error and provide meaningful error message
        INSERT INTO [dbo].[ErrorLog] (Timestamp, Message, Severity)
        VALUES (GETDATE(), @ErrorMessage, @ErrorSeverity);

        RAISERROR(@ErrorMessage, @ErrorSeverity, 1);
    END CATCH;
END;

GO

