CREATE PROCEDURE [dbo].[TriggerEmployeeUpdate]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SupervisorID int,
            @Department varchar(50);

    BEGIN TRY
        -- Retrieve supervisor ID and department from message queue
        SELECT @SupervisorID, @Department = Message
        FROM [MessageQueue].dbo.[ProcessedMessages];

        -- Trigger employee update procedure
        EXEC [dbo].[UpdateEmployeeData] @SupervisorID, @Department;

        END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage nvarchar(4000), @ErrorSeverity int;
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @ErrorSeverity = ERROR_SEVERITY();

        -- Log error and provide meaningful error message
        INSERT INTO [dbo].[ErrorLog] (Timestamp, Message, Severity)
        VALUES (GETDATE(), @ErrorMessage, @ErrorSeverity);

        RAISERROR(@ErrorMessage, @ErrorSeverity, 1);
    END CATCH;
END;

GO

CREATE PROCEDURE [dbo].[MonitorProcedure]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @QueryExecutionTime datetime,
            @CacheHitRate decimal(3,2),
            @ErrorCount int;

    BEGIN TRY
        -- Monitor procedure performance and health
        SELECT @QueryExecutionTime = DATEADD(SECOND, (DATEDIFF(SECOND, GETDATE(), GETDATE()))), 0)
        FROM sys.dm_exec_requests
        WHERE session_id = @@SPID;
        SELECT @CacheHitRate = SUM(hits) / COUNT(*) * 100.00
        FROM sys.dm_os_performance_counters
        WHERE object_name LIKE 'SQL Server:Stored Procedures:%';
        SELECT @ErrorCount = COUNT(*)
        FROM [dbo].[ErrorLog]
        WHERE Timestamp >= DATEADD(DAY, -1, GETDATE());

        -- Log monitoring results
        INSERT INTO [dbo].[ProcedureMonitoring] (Timestamp, QueryExecutionTime, CacheHitRate, ErrorCount)
        VALUES (GETDATE(), @QueryExecutionTime, @CacheHitRate, @ErrorCount);
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage nvarchar(4000), @ErrorSeverity int;
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @ErrorSeverity = ERROR_SEVERITY();

        -- Log error and provide meaningful error message
        INSERT INTO [dbo].[ErrorLog] (Timestamp, Message, Severity)
        VALUES (GETDATE(), @ErrorMessage, @ErrorSeverity);

        RAISERROR(@ErrorMessage, @ErrorSeverity, 1);
    END CATCH;
END;

GO

CREATE TABLE [dbo].[ProcedureMonitoring]
(
    Timestamp datetime,
    QueryExecutionTime datetime,
    CacheHitRate decimal(3,2),
    ErrorCount int
);

CREATE INDEX IX_ProcedureMonitoring_Timestamp ON [dbo].[ProcedureMonitoring] (Timestamp);

GO"]

