```
// logger.go
package logger

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/service/kinesis"
	"github.com/go-redis/redis/v8"
)

type Logger struct {
	config     *LoggerConfig
	kinesis    *kinesis.Kinesis
	redisClient *redis.Client
}

func NewLogger(config *LoggerConfig) (*Logger, error) {
	l := &Logger{
		config: config,
	}
	err := l.init()
	if err != nil {
		return nil, err
	}
	return l, nil
}

func (l *Logger) init() error {
	if l.kinesis == nil {
		l.kinesis = kinesis.New(&aws.Config{Region: aws.String(l.config.Region)})
	}

	if l.redisClient == nil {
		l.redisClient = redis.NewClient(&redis.Option{
			Addr:     fmt.Sprintf("%s:%d", l.config.RedisHost, l.config.RedisPort),
			Password: l.config.RedisPassword,
			DB:       l.config.RedisDB,
		})
	}

	return nil
}

func (l *Logger) Log(ctx context.Context, logMessage string) error {
	err := l.kinesis.PutRecord(&kinesis.PutRecordInput{
		Data:       []byte(logMessage),
	 ShardId:     aws.String("default-shard"),
	 SequenceNumber: aws.String("1234567890"),
	})
	if err != nil {
		return err
	}

	err = l.redisClient.Publish(l.config.RedisChannel, logMessage).Result()
	if err != nil {
		return err
	}
	return nil
}

func (l *Logger) Close() error {
	if l.kinesis != nil {
		err := l.kinesis.Close()
		if err != nil {
			return err
		}
		l.kinesis = nil
	}

	if l.redisClient != nil {
		err := l.redisClient.Close()
		if err != nil {
			return err
		}
		l.redisClient = nil
	}
	return nil
}

// logger_config.go
package logger

type LoggerConfig struct {
	Region           string
	KinesisStreamName string
	RedisHost         string
	RedisPort         int
	RedisPassword     string
	RedisDB           int
	RedisChannel      string
	BatchSize         int
	Compression      string
}
