import json
import os
from typing import Dict, Any

class RegistryManager:
    registry: Dict[str, Any]
    lock = threading.Lock()

    def __init__(self):
        self.registry = {}

    def register_factory(self, factory_name: str, factory_func: Any):
        with self.lock:
            self.registry[factory_name] = factory_func

    def get_factory(self, factory_name: str) -> Any:
        return self.registry.get(factory_name)

    def deregister_factory(self, factory_name: str):
        with self.lock:
            if factory_name in self.registry:
                del self.registry[factory_name]

