    char buffer[1024];
    int len = snprintf(buffer, sizeof(buffer), "Error: %s - ", condition);
    va_start(ap, condition);
    len += vsnprintf(buffer + len, sizeof(buffer) - len, "%s\n", ap);
    va_end(ap);
    FILE *fp = fopen("/path/to/error/log.log", "a+");
    fwrite(buffer, 1, len, fp);
