class WFSRequest {
public:
    std::string provider;
    std::vector<std::pair<double, double>> bbox; // bounding box coordinates

    // Constructor
    WFSRequest(const std::string& provider, const std::vector<std::pair<double, double>>& bbox)
        : provider(provider), bbox(bbox) {}
};

// Satellite image data class
class SatelliteImageData {
public:
    std::string provider;
    std::vector<std::pair<double, double>> boundingBox; // bounding box coordinates

    // Constructor
    SatelliteImageData(const std::string& provider, const std::vector<std::pair<double, double>>& boundingBox)
        : provider(provider), boundingBox(boundingBox) {}
};

// Spatial database class
class SpatialDatabase {
public:
    std::map<std::string, std::unique_ptr<SatelliteImageData>> satelliteData;

    // Constructor
    SpatialDatabase() {}

    // Retrieve satellite data by provider and bounding box
    SatelliteImageData* getSatelliteData(const std::string& provider, const std::vector<std::pair<double, double>>& bbox) {
        auto it = satelliteData.find(provider);
        if (it == satelliteData.end()) return nullptr;

        for (const auto& data : it->second) {
            if (std::all_of(data.begin(), data.end(),
                [&bbox](const std::pair<double, double>& pair) { return pair.first <= bbox[0].first && pair.first >= bbox[1].first && pair.second <= bbox[2].second && pair.second >= bbox[3].second; })) {
                return &data;
            }
        }
        return nullptr;
    }

    // Store satellite data
    void storeSatelliteData(const std::string& provider, const SatelliteImageData& data) {
        satelliteData[provider] = std::make_unique<SatelliteImageData>(data);
    }
};

// Main class
