using System;
using System.IO;
using System.Process;

public class WebSiteManager
{
    private readonly string _rootDirectory;
    private readonly Process[] _processes = new Process[0];

    public WebSiteManager(string rootDirectory)
    {
        _rootDirectory = rootDirectory;
    }

    public void ManageSites()
    {
        var siteNames = Directory.GetFiles(_rootDirectory, "web.config", SearchOption.AllDirectories);

        foreach (var siteName in siteNames)
        {
            var sitePath = Path.GetDirectoryName(siteName);
            var siteNameOnly = Path.GetFileNameWithoutExtension(siteName);

            if (!string.IsNullOrEmpty(siteName))
            {
                if (!UniqueSiteName(siteNameOnly))
                {
                    throw new InvalidOperationException($"Duplicate site name: {siteNameOnly}");
                }

                StartSite(sitePath, siteNameOnly);
            }
        }
    }

    private bool UniqueSiteName(string siteName)
    {
        return !Directory.GetFiles(_rootDirectory, siteName + ".*", SearchOption.AllDirectories).Any();
    }

    public void StartSite(string sitePath, string siteName)
    {
        var process = Process.Start(new ProcessStartInfo
        {
            FileName = $"dotnet {sitePath}Program.cs",
            Arguments = "",
            WorkingDirectory = sitePath,
            RedirectStandardError = true,
            UseShellExecute = false
        });

        _processes = _processes.Append(process).ToArray();
    }

    public void StopSite(string siteName)
    {
        foreach (var process in _processes)
        {
            if (process.ProcessName.Contains(siteName))
            {
                try
                {
                    process.Kill();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error stopping site {siteName}: {ex.Message}");
                }
            }
        }
    }

    public void HealthCheck()
    {
        foreach (var process in _processes)
        {
            if (!process.HasExited)
            {
                try
                {
                    process.WaitForExit();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error checking site health: {ex.Message}");
                }
            }
        }
    }

    public void UpdateConfig(string siteName, string key, string value)
    {
        // Implement configuration update logic here.
    }
}
