// File hashing utility
std::string fileHashing(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        return "Error: File not found";
    }

    MD5_CTX ctx;
    unsigned char hash[16];

    file.seekg(0, std::ios::end);
    long fileSize = file.tellg();
    file.seekg(0);

    while (fileSize > 0) {
        size_t blockSize = (size_t)std::min(fileSize, 65536);
        file.read((char*) &ctx.block[0], blockSize);
        ctx.inputLen += blockSize;
        MD5Update(&ctx, (unsigned char*)&ctx.block[0], blockSize);
        fileSize -= blockSize;
    }

    MD5Final(&ctx, hash);

    std::string md5Hash = "";
    for (int i = 0; i < 16; ++i) {
        char buff[3];
        sprintf(buff, "%02x", hash[i]);
        md5Hash += buff;
    }

    return md5Hash;
}

// Dynamic file renaming
void renameFiles(const std::string& directoryPath) {
    DIR* dir = opendir(directoryPath.c_str());
    if (!dir) {
        perror("Error opening directory");
        return;
    }

    while (struct dirent* entry = readdir(dir)) {
        if (entry->d_type == DT_REG || entry->d_type == DT_DIR) {
            std::string filePath = directoryPath + "/" + entry->d_name;

            // Fetch additional file attributes
            struct stat fileStat;
            fstatat(AT_FDCWD, filePath.c_str(), &fileStat, AT_SYMLINK_NOFOLLOW);
            char* mimeType = getMIMEType(filePath);

            std::string versionedFileName = getUniqueFileName(filePath, mimeType);
            rename(filePath.c_str(), (versionedFileName + ".txt").c_str());
        }
    }

    closedir(dir);
}

// Library function for dynamic file renaming
std::string getUniqueFileName(const std::string& filePath, const char* mimeType) {
    time_t now = time(0);
    tm* localtm = localtime(&now);
    int timestamp = (int)(localtm->tm_sec * 100 + localtm->tm_usec / 100000);

    std::string versionedFileName = filePath;
    if (versionedFileName.find_last_of(".") != std::string::npos) {
        versionedFileName.erase(versionedFileName.find_last_of("."), versionedFileName.length() - 1);
    }

    return versionedFileName + "_" + std::to_string(timestamp) + "." + std::string(mimeType);
}

