    void stop();

    template<typename PacketType>
    void processPacket(PacketType&& packet);

private:
    std::vector<std::thread> threads_;
    std::mutex mtx_;
    std::condition_variable cv_;
    std::queue<PacketType> packetQueue_;

    void workerThread();

    template<typename PacketType>
    void handlePacket(PacketType&& packet);
};

template<typename PacketType>
class StreamingMediaProcessor::PacketIterator {
public:
    PacketIterator(const StreamingMediaProcessor& processor) : processor_(processor) {}

    bool hasNext() const { return !processor_.packetQueue_.empty(); }

    PacketType next() {
        if (hasNext()) {
            PacketType packet = std::move(processor_.packetQueue_.front());
            processor_.packetQueue_.pop();
            return packet;
        }
        return PacketType{}; // Empty packet
    }

private:
    StreamingMediaProcessor& processor_;
};

template<typename PacketType>
void StreamingMediaProcessor::processPacket(PacketType&& packet) {
    std::unique_lock<std::mutex> lock(mtx_);
    packetQueue_.push(std::move(packet));
    cv_.notify_one();
}

void StreamingMediaProcessor::workerThread() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx_);
        cv_.wait(lock, [this] { return !packetQueue_.empty(); });
        if (!packetQueue_.empty()) {
            handlePacket(std::move(packetQueue_.front()));
            packetQueue_.pop();
        }
    }
}

