class LoggingService {
public:
    virtual void log(const std::string& message) = 0;
};

class FileLogger : public LoggingService {
public:
    void log(const std::string& message) override {
        // Implement file-based logging
        std::cout << "Logged to file: " << message << std::endl;
    }
};

class ConsoleLogger : public LoggingService {
public:
    void log(const std::string& message) override {
        // Implement console-based logging
        std::cout << "Logged to console: " << message << std::endl;
    }
};

class StringCollection {
private:
    std::forward_list<std::string> collection_;
    LoggingService* logger_;

public:
    StringCollection(LoggingService* logger) : logger_(logger) {}

    ~StringCollection() {
        // Release resources
    }

    void insert(const std::string& value, const std::string& key = "") {
        if (!key.empty()) {
            auto it = std::find_if(collection_.begin(), collection_.end(),
                [key](const std::string& str) { return str == key; });
            if (it != collection_.end()) {
                collection_.insert_after(it, value);
            } else {
                collection_.emplace_after(collection_.end(), value);
            }
        } else {
            collection_.emplace_after(collection_.end(), value);
        }

        // Log the operation
        logger_->log("StringCollection: Inserted " + value + " (" +
            (key.empty() ? "at end" : "after " + key) + ")");
    }

    void synchronize() const {
        // No-op in this example, but could be implemented for concurrent access
    }
};

int main() {
    auto logger = std::make_shared<FileLogger>();
    StringCollection collection(logger);

    collection.insert("Hello");
    collection.insert("World", "Hello");

    return 0;
}
