#include <arpa/inet.h>

// Define a structure to represent a node in the graph
typedef struct {
    char* id;
    int weight;
} Node;

// Define a structure to represent an edge in the graph
typedef struct {
    char* from;
    char* to;
} Edge;

// Function to add a new node to the graph
void addNode(Node** nodes, int* nodeCount, char* newNodeId) {
    // Allocate memory for the new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->id = newNodeId;
    newNode->weight = 0;

    // Add the new node to the array of nodes
    *nodeCount += 1;
    *nodes = (Node*)realloc(*nodes, *nodeCount * sizeof(Node));

    (*nodes)[*nodeCount - 1] = newNode;
}

// Function to add a new edge between two nodes in the graph
void addEdge(Edge** edges, int* edgeCount, Node* fromNode, Node* toNode) {
    // Allocate memory for the new edge
    Edge* newEdge = (Edge*)malloc(sizeof(Edge));
    newEdge->from = fromNode->id;
    newEdge->to = toNode->id;

    // Add the new edge to the array of edges
    *edgeCount += 1;
    *edges = (Edge*)realloc(*edges, *edgeCount * sizeof(Edge));

    (*edges)[*edgeCount - 1] = newEdge;
}

// Function to generate a random graph with a specified number of nodes and edges
void generateRandomGraph(Node** nodes, int* nodeCount, Edge** edges, int* edgeCount, int numNodes, int numEdges) {
    for (int i = 0; i < numNodes; i++) {
        addNode(nodes, nodeCount, malloc(strlen("Node") + 10));
    }

    for (int i = 0; i < numEdges; i++) {
        Node* fromNode = nodes[rand() % *nodeCount];
        Node* toNode = nodes[rand() % *nodeCount];

        if (fromNode != toNode) {
            addEdge(edges, edgeCount, fromNode, toNode);
        }
    }
}

int main() {
    // Initialize the graph with 10 nodes and 20 edges
    Node* nodes = NULL;
    int nodeCount = 0;
    Edge* edges = NULL;
    int edgeCount = 0;

    generateRandomGraph(&nodes, &nodeCount, &edges, &edgeCount, 10, 20);

    // Print the generated graph
    for (int i = 0; i < nodeCount; i++) {
        printf("Node %s\n", nodes[i]->id);
    }

    for (int i = 0; i < edgeCount; i++) {
        Edge* edge = edges[i];
        printf("%s -> %s\n", edge->from, edge->to);
    }

    return 0;
}
```

