using namespace std;

class FileOperation {
public:
    virtual ~FileOperation() {}
    virtual void execute() = 0;
};

class PutRequest : public FileOperation {
public:
    PutRequest(const string& path, const string& data) : path_(path), data_(data) {}

    void execute() override {
        // Update resource using PUT method
        cout << "Updated resource at: " << path_ << endl;
    }

private:
    string path_;
    string data_;
};

class DeleteRequest : public FileOperation {
public:
    DeleteRequest(const string& path) : path_(path) {}

    void execute() override {
        // Delete resource using DELETE method
        cout << "Deleted resource at: " << path_ << endl;
    }

private:
    string path_;
};

class Resource {
public:
    map<string, string> data;

    void put(const string& path, const string& data) {
        if (data.empty()) {
            // Handle invalid request
            return;
        }
        this->data[path] = data;
    }

    void deleteResource(const string& path) {
        if (!path.empty() && this->data.find(path) != this->data.end()) {
            this->data.erase(path);
        } else {
            // Handle invalid request
            return;
        }
    }
};

class FileOperationManager {
public:
    Resource resource_;

    void handleRequest(const shared_ptr<FileOperation>& request) {
        try {
            request->execute();
        } catch (const exception& e) {
            cout << "Error: " << e.what() << endl;
        }
    }

    void updateResource(const string& path, const string& data) {
        PutRequest putRequest(path, data);
        handleRequest(make_shared<FileOperation>(putRequest));
    }

    void deleteResource(const string& path) {
        DeleteRequest deleteRequest(path);
        handleRequest(make_shared<FileOperation>(deleteRequest));
    }
};

int main() {
    FileOperationManager fileOperationManager;

    // Example usage:
    fileOperationManager.updateResource("path/to/resource", "updated data");
    fileOperationManager.deleteResource("path/to/resource");

    return 0;
}

