#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

typedef struct client {
    int socket;
    char* username;
    struct sockaddr_in addr;
} Client;

void handle_request(Client* client, char* buffer) {
    // Handle incoming request from the client
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    if (bind(server_socket, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        return -1;
    }

    listen(server_socket, MAX_CLIENTS);

    Client clients[MAX_CLIENTS];
    for (int i = 0; i < MAX_CLIENTS; i++) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            perror("accept");
            return -1;
        }

        clients[i].socket = client_socket;
        // Initialize the username and address for the client
    }

    while (1) {
        char buffer[BUFFER_SIZE];
        int bytes_read = read(0, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("read");
            return -1;
        }

        for (int i = 0; i < MAX_CLIENTS; i++) {
            Client* client = &clients[i];
            if (client->socket > 0) {
                write(client->socket, buffer, bytes_read);
            }
        }
    }

    for (int i = 0; i < MAX_CLIENTS; i++) {
        close(clients[i].socket);
    }

    return 0;
}
