            {
                // Cache the sensor readings for 1 minute
                return await _memoryCache.SetMemoryCacheOptions(new MemoryCacheEntryOptions().SlidingExpiration(TimeSpan.FromMinutes(1))).Set(cacheKey, sensorReadings);
            });

            if (cachedSensorReadings != null)
            {
                // Process the cached sensor readings
                foreach (var reading in cachedSensorReadings)
                {
                    // Analyze and visualize the data
                    await _logger.LogInformationAsync($"Processing sensor reading: {reading.Timestamp} - {reading.Value}");
                }
            }
            else
            {
                // Cache miss, process the original sensor readings
                foreach (var reading in sensorReadings)
                {
                    // Analyze and visualize the data
                    await _logger.LogInformationAsync($"Processing sensor reading: {reading.Timestamp} - {reading.Value}");
                }

                // Cache the processed sensor readings for 1 minute
                await _memoryCache.SetMemoryCacheOptions(new MemoryCacheEntryOptions().SlidingExpiration(TimeSpan.FromMinutes(1))).Set(cacheKey, sensorReadings);
            }
        }
