                with open(file_path, 'rb') as file:
                    chunk = file.read(1024 * 1024)  # Read 1MB chunks
                    if not chunk:
                        break

                    md5_hash = hashlib.md5(chunk).hexdigest()
                    intermediate_state[file_path] = md5_hash
                    self.store_intermediate_state(intermediate_state)
            except Exception as e:
                print(f"Error uploading file: {e}")

        return md5_hash

    def get_intermediate_state(self, file_path):
        if file_path in self.intermediate_states:
            return self.intermediate_states[file_path]
        return None

