#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a structure to represent a record
typedef struct {
    int offset;
    int key;
} Record;

// Initialize the record set and handle external data source
void* init_records(int size, int min_val, int max_val, int max_memory, void (*external_data_source)(int*, int*)) {
    // Allocate memory for offsets, keys, and records
    int* offsets = (int*)malloc(size * sizeof(int));
    int* keys = (int*)malloc(size * sizeof(int));
    Record* records = (Record*)malloc(size * sizeof(Record));

    // Initialize the record set
    int valid_records = 0;
    for (int i = 0; i < size; i++) {
        int key;
        if (external_data_source(&key, &valid_records) == -1) {
            // Handle error or invalid data from external source
            continue;
        }
        if (key < min_val || key > max_val) {
            // Log and skip invalid keys
            printf("Invalid key %d\n", key);
            continue;
        }
        records[i].offset = i;
        records[i].key = key;
    }

    // Check for memory constraints
    int total_memory = 0;
    for (int i = 0; i < valid_records; i++) {
        total_memory += sizeof(Record);
        if (total_memory > max_memory * 1024) {
            printf("Memory limit exceeded. Reducing record set.\n");
            size = valid_records - (size - valid_records) / 2;
            break;
        }
    }

    // Log initialization process
    printf("Records created: %d\n", valid_records);
    printf("Random value range: [%d, %d]\n", min_val, max_val);
    printf("Duplicate or invalid keys encountered: %d\n", size - valid_records);
    printf("Total memory consumed: %d KB\n", total_memory / 1024);

    // Check for initialization success
    if (size == 0) {
        return NULL;
    }

    return records;
}

// Clean up the record set
void free_records(Record* records, int size) {
    free(records);
}

// Thread-safe initialization function
void* thread_safe_init_records(int size, int min_val, int max_val, int max_memory, void (*external_data_source)(int*, int*)) {
    // Use a lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Initialize the record set using the external data source
    Record* records = init_records(size, min_val, max_val, max_memory, external_data_source);

    // Release the lock
    pthread_mutex_unlock(&lock);

    return records;
}

// Handle errors and exceptions
void error_handling(int error_code) {
    switch (error_code) {
        case -1:
            printf("Error: Invalid data from external source\n");
            break;
        default:
            printf("Error: Unknown error code %d\n", error_code);
    }
}
