OffsetArray* create_offset_array(int size) {
    OffsetArray* arr = (OffsetArray*)malloc(sizeof(OffsetArray));
    arr->size = size;
    arr->data = (long*)malloc(size * sizeof(long));
    return arr;
}

// Define a function to serialize an offset array
void serialize_offset_array(FILE* file, OffsetArray* arr) {
    fwrite(&arr->size, sizeof(int), 1, file);
    fwrite(arr->data, sizeof(long), arr->size, file);
}

// Define a function to allocate and initialize a key array
KeyArray* create_key_array(int size) {
    KeyArray* arr = (KeyArray*)malloc(sizeof(KeyArray));
    arr->size = size;
    arr->data = (int*)malloc(size * sizeof(int));
    return arr;
}

// Define a function to serialize a key array
void serialize_key_array(FILE* file, KeyArray* arr) {
    fwrite(&arr->size, sizeof(int), 1, file);
    fwrite(arr->data, sizeof(int), arr->size, file);
}

// Define a structure for the record-based data format
typedef struct {
    int version;
    int checksum;
    Record records[];
} DataFormat;

// Define a function to serialize the entire dataset
void serialize_data(FILE* file, OffsetArray* offsets, KeyArray* keys) {
    DataFormat df = {0};
    // Calculate and store the checksum
    int checksum = 0;
    for (int i = 0; i < offsets->size; i++) {
        checksum += offsets->data[i];
    }
    df.checksum = checksum;

    // Serialize the record structures
    for (int i = 0; i < offsets->size; i++) {
        Record rec = {i, offsets->data[i]};
        fwrite(&rec, sizeof(Record), 1, file);
    }

    // Write the serialized data to the file
    fwrite(&df, sizeof(DataFormat), 1, file);
}

// Define a function to deserialize the dataset
void deserialize_data(FILE* file, OffsetArray** offsets, KeyArray** keys) {
    DataFormat df;
    fread(&df, sizeof(DataFormat), 1, file);

    // Check the version and checksum for integrity
    if (df.version != 0 || df.checksum != 0) {
        printf("Invalid data format\n");
        return;
    }

    // Deserialize the record structures
    int numRecords = 0;
    Record rec;
    while (fread(&rec, sizeof(Record), 1, file)) {
        offsets->data[numRecords] = rec.offset;
        keys->data[numRecords] = rec.id;
        numRecords++;
    }
}

// Define a function to free allocated memory
void free_data(OffsetArray* offsetArr, KeyArray* keyArr) {
    if (offsetArr != NULL) {
        free(offsetArr->data);
        free(offsetArr);
    }

    if (keyArr != NULL) {
        free(keyArr->data);
        free(keyArr);
    }
}

// Define a function to test the library
void test_library() {
    OffsetArray* offsets = create_offset_array(1000);
    KeyArray* keys = create_key_array(500);

    // Initialize and serialize data structures
    for (int i = 0; i < offsets->size; i++) {
        offsets->data[i] = i;
        keys->data[i] = i;
    }

    FILE* file = fopen("test.data", "wb");
    if (file != NULL) {
        serialize_offset_array(file, offsets);
        serialize_key_array(file, keys);
        serialize_data(file, offsets, keys);
        fclose(file);

        // Deserialize and verify data
        OffsetArray* deserializedOffsets;
        KeyArray* deserializedKeys;

        file = fopen("test.data", "rb");
        if (file != NULL) {
            deserialize_offsets(file, &deserializedOffsets);
            deserialize_keys(file, &deserializedKeys);

            for (int i = 0; i < offsets->size; i++) {
                if (offsets->data[i] != deserializedOffsets->data[i]) {
                    printf("Error: Offset data mismatch\n");
                    return;
                }
            }

            fclose(file);
        }

        // Clean up
        free_data(offsets, keys);
    } else {
        printf("Error: Could not create file for testing\n");
    }
}

int main() {
    test_library();
    return 0;
}
