using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace MiddlewareApplication
{
    public class DataIngestionService : IDataIngestionService
    {
        private readonly ILogger _logger;
        private readonly IDatabaseRepository _databaseRepository;
        private readonly IApiConnector _apiConnector;
        private readonly IBufferManager _bufferManager;

        public DataIngestionService(ILogger logger, IDatabaseRepository databaseRepository, IApiConnector apiConnector, IBufferManager bufferManager)
        {
            _logger = logger;
            _databaseRepository = databaseRepository;
            _apiConnector = apiConnector;
            _bufferManager = bufferManager;
        }

        public async Task ProcessDataAsync()
        {
            try
            {
                // Handle IoT devices data ingestion
                var iotData = await _apiConnector.GetIoTDataAsync();
                if (iotData != null)
                {
                    await _databaseRepository.InsertIoTDataAsync(iotData);
                }

                // Handle social media API data ingestion
                var socialMediaData = await _apiConnector.GetSocialMediaDataAsync();
                if (socialMediaData != null)
                {
                    await _databaseRepository.InsertSocialMediaDataAsync(socialMediaData);
                }

                // Handle financial market feeds data ingestion
                var financialMarketData = await _apiConnector.GetFinancialMarketDataAsync();
                if (financialMarketData != null)
                {
                    await _databaseRepository.InsertFinancialMarketDataAsync(financialMarketData);
                }

                // Handle web scraping services data ingestion
                var webScrapingData = await _apiConnector.GetWebScrapingDataAsync();
                if (webScrapingData != null)
                {
                    await _databaseRepository.InsertWebScrapingDataAsync(webScrapingData);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing data");
            }
        }

        public async Task ProcessBufferedDataAsync()
        {
            try
            {
                var bufferedData = _bufferManager.GetBufferData();
                if (bufferedData != null)
                {
                    await _databaseRepository.InsertBufferDataAsync(bufferedData);
                    _bufferManager.ClearBufferData();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing buffered data");
            }
        }

        public async Task StartProcessingAsync()
        {
            while (true)
            {
                try
                {
                    await ProcessDataAsync();
                    await Task.Delay(1000); // adjust delay as needed
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing data");
                }
            }
        }
    }
}
