class DistributedCache {
public:
    DistributedCache(const std::string& host, const std::string& port) : 
        kvStore_(host, port), cache_(std::make_shared<std::map<std::string, std::pair<int64_t, std::string>>>()), 
        lock_(std::make_unique<std::mutex>()),
        cv_(std::make_unique<std::condition_variable>()) {
        // Initialize the KV store connection
    }

    void put(const std::string& key, const std::string& value, int64_t ttl) {
        auto it = cache_->find(key);
        if (it == cache_->end()) {
            // Insert a new entry into the cache
            cache_->insert({key, {std::chrono::system_clock::now() + std::chrono::seconds(ttl), value}});
        } else {
            // Update the existing entry's TTL
            it->second.first = std::chrono::system_clock::now() + std::chrono::seconds(ttl);
        }
    }

    void get(const std::string& key, std::string& value) {
        auto it = cache_->find(key);
        if (it != cache_->end()) {
            // Retrieve the cached value
            value = it->second.second;
        } else {
            // Fetch from the KV store and update the cache
            kvStore_.get(key, value);
            put(key, value, 3600); // Default TTL is 1 hour
        }
    }

    void clearExpired() {
        auto now = std::chrono::system_clock::now();
        for (auto it = cache_->begin(); it != cache_->end();) {
            if (it->second.first <= now) {
                // Remove expired entries from the cache
                it = cache_->erase(it);
            } else {
                ++it;
            }
        }
    }

private:
