import json
from abc import ABCMeta, abstractmethod

class JsonSerializable(metaclass=ABCMeta):
    @abstractmethod
    def to_json(self):
        pass

class JsonSerializer:
    _registry = {}

    @classmethod
    def register(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def from_json(cls, json_str):
        obj = None
        try:
            data = json.loads(json_str)
            obj_id = data.get('id')
            if obj_id and obj_id in cls._registry:
                factory = cls._registry[obj_id]
                obj = factory().from_dict(data)
            else:
                raise ValueError("Invalid JSON object")
        except Exception as e:
            print(f"Error parsing JSON: {str(e)}")
        finally:
            return obj

    def to_json(self):
