        boolean isAvailable();
        void handleFailure(Throwable t);
    }

    public class CircuitBreaker<T> implements java.util.function.Predicate<T> {
        private int failureCount = 0;

        @Override
        public boolean test(T t) {
            if (!isAvailable()) return false; // service not available, break the circuit
            if (failureCount >= MAX_FAILURES) return true; // too many failures, break the circuit

            try {
                return isAvailable() && // service available, process the image
                    ((ImageProcessor<T>) t).process((T) null); 
            } catch (Exception e) {
                failureCount++;
                handleFailure(e);
                return false;
            }
        }
    }

