// Define a structure for LTE_RRC_CriticalSection
typedef struct {
    int id;
    char* name;
} LTE_RRC_CriticalSection;

// Define a dynamic pool of LTE_RRC_CriticalSection structures
void** critical_sections;

// Initialize the dynamic pool with a specified size
int init_pool(int size) {
    if (size <= 0) {
        printf("Error: Invalid pool size.\n");
        return -1;
    }

    // Allocate memory for the dynamic pool
    void* ptr = malloc(size * sizeof(LTE_RRC_CriticalSection));
    if (!ptr) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    critical_sections = (void**)malloc(size * sizeof(void*));
    if (!critical_sections) {
        free(ptr);
        printf("Error: Memory allocation for pool failed.\n");
        return -1;
    }

    // Initialize the dynamic pool
    for (int i = 0; i < size; i++) {
        LTE_RRC_CriticalSection* section = (LTE_RRC_CriticalSection*)ptr + i;
        section->id = i;
        section->name = NULL;
    }

    return size;
}

// Free the dynamic pool
void free_pool() {
    if (!critical_sections) {
        printf("Error: Pool is not initialized.\n");
        return;
    }

    // Deallocate memory for each LTE_RRC_CriticalSection structure
    for (int i = 0; i < init_pool(0); i++) {
        LTE_RRC_CriticalSection* section = critical_sections[i];
        free(section);
    }

    // Deallocate memory for the dynamic pool itself
    free(critical_sections);
}

