void rename_files_in_directory(const char* directory_path) {
    DIR *dir = opendir(directory_path);
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        char file_path[1024];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        // Extract the file name and extension
        char* file_name = strrchr(ent->d_name, '/');
        if (file_name == NULL) {
            file_name = ent->d_name;
        }
        int len = strlen(file_name);
        char* file_extension = file_name + len - 4;

        // Generate the new file name with version number and timestamp
        time_t now = time(NULL);
        struct tm* time_info = localtime(&now);
        char new_file_name[1024];
        sprintf(new_file_name, "%s-v%d-%d.%s", file_name, (int)time_info->tm_hour, (int)time_info->tm_min, file_extension);

        // Rename the file
        rename(file_path, new_file_name);
    }
    closedir(dir);
}

