class NICPool {
public:
    void addNIC(const std::string& nicName, const std::string& ipAddress, const std::string& subnetMask, const std::string& gateway, const std::string& macAddress) {
        // Lock the pool to ensure thread safety
        std::unique_lock<std::mutex> lock(poolMutex);

        // Validate NIC parameters
        if (ipAddress.empty() || subnetMask.empty() || gateway.empty() || macAddress.empty()) {
            throw std::runtime_error("Invalid NIC parameters");
        }

        // Add the new NIC to the pool
        nicPool_[nicName] = { ipAddress, subnetMask, gateway, macAddress };

        lock.unlock();
    }

    void updateNIC(const std::string& nicName, const std::string& newIpAddress) {
        // Lock the pool to ensure thread safety
        std::unique_lock<std::mutex> lock(poolMutex);

        if (nicPool_.count(nicName)) {
            nicPool_[nicName].ipAddress = newIpAddress;
        } else {
            throw std::runtime_error("NIC not found");
        }

        lock.unlock();
    }

    void removeNIC(const std::string& nicName) {
        // Lock the pool to ensure thread safety
        std::unique_lock<std::mutex> lock(poolMutex);

        if (nicPool_.count(nicName)) {
            nicPool_.erase(nicName);
        } else {
            throw std::runtime_error("NIC not found");
        }

        lock.unlock();
    }

    // Integrate with the external network monitoring service
