};

class NetworkInterfaceConfig {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<std::function<void()> > queue;

public:
    void addNicConfig(NicConfig config) {
        std::unique_lock<stdlock_guard<std::mutex>> lock(mtx);
        queue.push([=] {
            // perform configuration operation
        });
    }

    void removeNicConfig(NicConfig config) {
        std::unique_lock<std::mutex> lock(mtx);
        queue.push([=] {
            // perform removal operation
        });
    }

    void start() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this]() { return !queue.empty(); });
            auto func = queue.front();
            queue.pop();
            lock.unlock();

            try {
                func();
            } catch (...) {
                // handle exception
            }
        }
    }

    void stop() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.notify_all();
    }
};

