NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_array(N) {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*N);
    int rnti_count[16] = {0};

    for(int i=0; i<N; i++) {
        uint16_t RNTI = rand() % 65536;
        while(rnti_count[RNTI/64] >= (RNTI%64+1)) 
            RNTI = rand() % 65536;

        rnti_count[RNTI/64]++;
        array[i].RNTI = RNTI;

        for(int j=0; j<MAX_TAGS; j++) {
            char random_char = rand() % 26 + 'a';
            array[i].RX_UE_INFORMATION_TAG[j] = random_char;
            array[i].CRC_INDICATION_REL8_TAG[j] = random_char;
        }

        int flag = rand() % 2;
        array[i].CRCFLAG = (flag == 1);
    }

    return array;
